from (values
(332922,36992,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, dieser Hamster ... seit drei Jahren denselben Ausweis.'::text,'trägt'::text,'trägt'::text,'trägt'::text,'Bestie, ich hab gehört, dieser Hamster trägt seit drei Jahren denselben Ausweis.'::text),
(332926,36992,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що цей хом''як ... той самий бейдж уже три роки.'::text,'носить'::text,'носить'::text,'носить'::text,'Подруго, я чула, що цей хом''як носить той самий бейдж уже три роки.'::text),
(332925,36992,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, he oído que este hámster ... la misma credencial desde hace tres años.'::text,'lleva'::text,'lleva'::text,'lleva'::text,'Amiga, he oído que este hámster lleva la misma credencial desde hace tres años.'::text),
(332924,36992,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire que ce hamster ... le même badge depuis trois ans.'::text,'porte'::text,'porte'::text,'porte'::text,'Ma belle, j''ai entendu dire que ce hamster porte le même badge depuis trois ans.'::text),
(332927,36992,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, duydum ki bu hamster üç yıldır aynı yaka kartını ...'::text,'takıyor'::text,'takıyor'::text,'takıyor'::text,'Kankam, duydum ki bu hamster üç yıldır aynı yaka kartını takıyor.'::text),
(332928,36992,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy ez a hörcsög három éve ... ugyanazt a belépőkártyát.'::text,'hordja'::text,'hordja'::text,'hordja'::text,'Csajszi, azt hallottam, hogy ez a hörcsög három éve hordja ugyanazt a belépőkártyát.'::text),
(332931,36993,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also, er hat mir erzählt, dass der Hamster seinen Ausweis an das Lesegerät ... und rausging.'::text,'hielt'::text,'gerade hielt'::text,'gehalten hat'::text,'Okay, also, er hat mir erzählt, dass der Hamster seinen Ausweis an das Lesegerät hielt und rausging.'::text),
(332935,36993,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, він сказав мені, що хом''як ... бейдж до зчитувача і вийшов.'::text,'приклав'::text,'прикладав'::text,'приклав'::text,'Коротше, він сказав мені, що хом''як приклав бейдж до зчитувача і вийшов.'::text),
(332934,36993,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues me dijo que el hámster ... su credencial por el lector y se fue.'::text,'pasó'::text,'estaba pasando'::text,'ha pasado'::text,'Vale, pues me dijo que el hámster pasó su credencial por el lector y se fue.'::text),
(332933,36993,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bref, il m''a dit que le hamster ... son badge devant le lecteur et qu''il est sorti.'::text,'a passé'::text,'passait'::text,'a passé'::text,'Bref, il m''a dit que le hamster a passé son badge devant le lecteur et qu''il est sorti.'::text),
(332936,36993,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, bana dedi ki hamster kartını okuyucuya ... ve çıkıp gitti.'::text,'okuttu'::text,'okutuyordu'::text,'okuttu'::text,'Tamam yani, bana dedi ki hamster kartını okuyucuya okuttu ve çıkıp gitti.'::text),
(332937,36993,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, azt mondta, hogy a hörcsög ... a kártyáját a leolvasóhoz, és kisétált.'::text,'odaérintette'::text,'érintette'::text,'odaérintette'::text,'Szóval, azt mondta, hogy a hörcsög odaérintette a kártyáját a leolvasóhoz, és kisétált.'::text),
(332940,36994,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hamster hat seinen Ausweis heute genau einmal ...: um um fünf Feierabend zu machen. Klar, ein total engagierter Mitarbeiter.'::text,'benutzt'::text,'benutzt'::text,'benutzt'::text,'Der Hamster hat seinen Ausweis heute genau einmal benutzt: um um fünf Feierabend zu machen. Klar, ein total engagierter Mitarbeiter.'::text),
(332944,36994,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хом''як сьогодні ... бейдж один раз: щоб піти о п''ятій. Явно відданий працівник.'::text,'використав'::text,'використовував'::text,'використовує'::text,'Хом''як сьогодні використав бейдж один раз: щоб піти о п''ятій. Явно відданий працівник.'::text),
(332943,36994,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hámster ... su credencial una vez hoy: para irse a las cinco. Claramente un empleado entregado.'::text,'ha usado'::text,'ha estado usando'::text,'usa'::text,'El hámster ha usado su credencial una vez hoy: para irse a las cinco. Claramente un empleado entregado.'::text),
(332942,36994,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le hamster ... son badge une fois aujourd''hui : pour partir à cinq heures. Clairement un employé dévoué.'::text,'a utilisé'::text,'a utilisé'::text,'utilise'::text,'Le hamster a utilisé son badge une fois aujourd''hui : pour partir à cinq heures. Clairement un employé dévoué.'::text),
(332945,36994,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamster bugün kartını bir kez ...: beşte çıkmak için. Belli ki çok sadık bir çalışan.'::text,'kullandı'::text,'kullanıyor'::text,'kullanır'::text,'Hamster bugün kartını bir kez kullandı: beşte çıkmak için. Belli ki çok sadık bir çalışan.'::text),
(332946,36994,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hörcsög ma egyszer ... a kártyáját: hogy ötkor hazamenjen. Nyilván elkötelezett munkatárs.'::text,'használta'::text,'használta'::text,'használja'::text,'A hörcsög ma egyszer használta a kártyáját: hogy ötkor hazamenjen. Nyilván elkötelezett munkatárs.'::text),
(332949,36995,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor er um fünf ausstempelte, ... der Hamster den größten Teil des Tages verschlafen. Makellos.'::text,'hatte'::text,'hat'::text,'verschläft'::text,'Bevor er um fünf ausstempelte, hatte der Hamster den größten Teil des Tages verschlafen. Makellos.'::text),
(332953,36995,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж відбити бейдж о п''ятій, хом''як ... більшу частину дня. Бездоганно.'::text,'проспав'::text,'проспав'::text,'спить'::text,'Перш ніж відбити бейдж о п''ятій, хом''як проспав більшу частину дня. Бездоганно.'::text),
(332952,36995,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de fichar la salida a las cinco, el hámster ... casi todo el día. Impecable.'::text,'había dormido'::text,'ha dormido'::text,'duerme'::text,'Antes de fichar la salida a las cinco, el hámster había dormido casi todo el día. Impecable.'::text),
(332951,36995,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant de badger pour sortir à cinq heures, le hamster ... presque toute la journée. Impeccable.'::text,'avait dormi'::text,'a dormi'::text,'dort'::text,'Avant de badger pour sortir à cinq heures, le hamster avait dormi presque toute la journée. Impeccable.'::text),
(332954,36995,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beşte kart basıp çıkmadan önce hamster günün çoğunu ... — kusursuz.'::text,'uyuyarak geçirmişti'::text,'uyuyarak geçirdi'::text,'uyuyarak geçiriyor'::text,'Beşte kart basıp çıkmadan önce hamster günün çoğunu uyuyarak geçirmişti — kusursuz.'::text),
(332955,36995,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt ötkor kicsekkolt, a hörcsög ... a nap nagy részét. Hibátlan.'::text,'átaludta'::text,'átaludta'::text,'átalussza'::text,'Mielőtt ötkor kicsekkolt, a hörcsög átaludta a nap nagy részét. Hibátlan.'::text),
(332958,36996,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn der Hamster seinen Ausweis verliert, ... er nicht zur Tür raus, ohne Witz.'::text,'kommt'::text,'käme'::text,'kam'::text,'Bro, wenn der Hamster seinen Ausweis verliert, kommt er nicht zur Tür raus, ohne Witz.'::text),
(332962,36996,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо хом''як загубить бейдж, він ... за двері, без жартів.'::text,'не вийде'::text,'не вийшов би'::text,'не вийшов'::text,'Бро, якщо хом''як загубить бейдж, він не вийде за двері, без жартів.'::text),
(332961,36996,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si el hámster pierde su credencial, ... por la puerta, en serio.'::text,'no saldrá'::text,'no saldría'::text,'no salió'::text,'Bro, si el hámster pierde su credencial, no saldrá por la puerta, en serio.'::text),
(332960,36996,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si le hamster perd son badge, il ... la porte, sans mentir.'::text,'ne passera pas'::text,'ne passerait pas'::text,'n''a pas passé'::text,'Frérot, si le hamster perd son badge, il ne passera pas la porte, sans mentir.'::text),
(332963,36996,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, hamster kartını kaybederse kapıdan ..., yalan yok.'::text,'çıkamayacak'::text,'çıkamazdı'::text,'çıkamadı'::text,'Kanka, hamster kartını kaybederse kapıdan çıkamayacak, yalan yok.'::text),
