(346194,38466,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész éjjel pizzát ..., mégis megáll egy ölelésre. Igazi profi.'::text,'szállít'::text,'szállít'::text,'szállít'::text,'Egész éjjel pizzát szállít, mégis megáll egy ölelésre. Igazi profi.'::text),
(346197,38467,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Pizza ... direkt bis aufs Sofa geliefert, eindeutig der beste Service der Stadt.'::text,'wurde'::text,'hat'::text,'liefert'::text,'Die Pizza wurde direkt bis aufs Sofa geliefert, eindeutig der beste Service der Stadt.'::text),
(346201,38467,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Піцу ... прямо до дивана, очевидно, найкращий сервіс у місті.'::text,'доставили'::text,'доставила'::text,'доставляє'::text,'Піцу доставили прямо до дивана, очевидно, найкращий сервіс у місті.'::text),
(346200,38467,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pizza ... directamente hasta el sofá, obviamente el mejor servicio de la ciudad.'::text,'fue entregada'::text,'entregó'::text,'está entregando'::text,'La pizza fue entregada directamente hasta el sofá, obviamente el mejor servicio de la ciudad.'::text),
(346199,38467,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pizza ... jusqu''au canapé, clairement le meilleur service de la ville.'::text,'a été livrée'::text,'a livré'::text,'est en train de livrer'::text,'La pizza a été livrée jusqu''au canapé, clairement le meilleur service de la ville.'::text),
(346202,38467,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pizza doğrudan kanepeye kadar ..., belli ki şehrin en iyi servisi.'::text,'teslim edildi'::text,'teslim etti'::text,'teslim ediyor'::text,'Pizza doğrudan kanepeye kadar teslim edildi, belli ki şehrin en iyi servisi.'::text),
(346203,38467,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pizzát egészen a kanapéig ..., nyilván a város legjobb szolgáltatása.'::text,'kiszállították'::text,'kiszállította'::text,'szállítja'::text,'A pizzát egészen a kanapéig kiszállították, nyilván a város legjobb szolgáltatása.'::text),
(346206,38468,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hamster mit Brille ... die Pizza und stellte sie auf den Tisch.'::text,'lieferte'::text,'wurde geliefert'::text,'liefernd'::text,'Der Hamster mit Brille lieferte die Pizza und stellte sie auf den Tisch.'::text),
(346210,38468,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хом''як в окулярах ... піцу і поставив її на стіл.'::text,'доставив'::text,'був доставлений'::text,'доставляючи'::text,'Хом''як в окулярах доставив піцу і поставив її на стіл.'::text),
(346209,38468,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hámster con gafas ... la pizza y la puso en la mesa.'::text,'entregó'::text,'fue entregado'::text,'entregando'::text,'El hámster con gafas entregó la pizza y la puso en la mesa.'::text),
(346208,38468,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le hamster à lunettes ... la pizza et l''a posée sur la table.'::text,'a livré'::text,'a été livré'::text,'livrant'::text,'Le hamster à lunettes a livré la pizza et l''a posée sur la table.'::text),
(346211,38468,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözlüklü hamster pizzayı ... ve masaya koydu.'::text,'teslim etti'::text,'teslim edildi'::text,'teslim ederek'::text,'Gözlüklü hamster pizzayı teslim etti ve masaya koydu.'::text),
(346212,38468,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szemüveges hörcsög ... a pizzát, és letette az asztalra.'::text,'kiszállította'::text,'ki lett szállítva'::text,'szállítva'::text,'A szemüveges hörcsög kiszállította a pizzát, és letette az asztalra.'::text),
(346215,38469,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, das ... nur ein Typ sein, der Pizza liefert, er umarmt sie ja, Bro.'::text,'kann nicht'::text,'muss'::text,'darf nicht'::text,'Nee, das kann nicht nur ein Typ sein, der Pizza liefert, er umarmt sie ja, Bro.'::text),
(346219,38469,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ні, це ... бути просто хлопцем, який розвозить піцу, він же її обіймає, бро.'::text,'не може'::text,'мусить'::text,'не повинен'::text,'Та ні, це не може бути просто хлопцем, який розвозить піцу, він же її обіймає, бро.'::text),
(346218,38469,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, ese ... ser solo un chico que reparte pizzas, la está abrazando, bro.'::text,'no puede'::text,'tiene que'::text,'no debe'::text,'Qué va, ese no puede ser solo un chico que reparte pizzas, la está abrazando, bro.'::text),
(346217,38469,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, ça ... être juste un mec qui livre des pizzas, il la serre dans ses bras, frérot.'::text,'ne peut pas'::text,'doit'::text,'ne doit pas'::text,'Nan, ça ne peut pas être juste un mec qui livre des pizzas, il la serre dans ses bras, frérot.'::text),
(346220,38469,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok artık, o sadece pizza getiren biri ..., kıza sarılıyor, kanka.'::text,'olamaz'::text,'olmalı'::text,'olmamalı'::text,'Yok artık, o sadece pizza getiren biri olamaz, kıza sarılıyor, kanka.'::text),
(346221,38469,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, az ... csak egy srác, aki pizzát szállít, hiszen öleli a lányt, tesó.'::text,'nem lehet'::text,'biztos, hogy'::text,'nem szabad, hogy legyen'::text,'Á, az nem lehet csak egy srác, aki pizzát szállít, hiszen öleli a lányt, tesó.'::text),
(346224,38470,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hamster, ... die Pizza geliefert hat, blieb 2 Stunden, weit über den Vertrag hinaus.'::text,'der'::text,'der'::text,'dessen'::text,'Der Hamster, der die Pizza geliefert hat, blieb 2 Stunden, weit über den Vertrag hinaus.'::text),
(346228,38470,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хом''як, ... доставив піцу, залишився на 2 години, значно понад контракт.'::text,'який'::text,'який'::text,'чий'::text,'Хом''як, який доставив піцу, залишився на 2 години, значно понад контракт.'::text),
(346227,38470,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hámster ... entregó la pizza se quedó 2 horas, mucho más de lo que marca el contrato.'::text,'que'::text,'que'::text,'cuyo'::text,'El hámster que entregó la pizza se quedó 2 horas, mucho más de lo que marca el contrato.'::text),
