(346237,38471,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хом''як в окулярах сказав, що ... піцу так швидко, як міг.'::text,'доставив'::text,'доставив'::text,'доставляє'::text,'Хом''як в окулярах сказав, що доставив піцу так швидко, як міг.'::text),
