(346273,38475,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, він ... піцу цілий день, перш ніж нарешті сів поруч із нею.'::text,'розвозив'::text,'розвозить'::text,'розвозив'::text,'Слухай, кажуть, він розвозив піцу цілий день, перш ніж нарешті сів поруч із нею.'::text),
