(387836,43093,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toplantıya kadar uyuyan hamster 12 saat ...'::text,'uyumuş olacak'::text,'uyuyacak'::text,'uyuyor olacak'::text,'Toplantıya kadar uyuyan hamster 12 saat uyumuş olacak.'::text),
(387837,43093,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A megbeszélésig az alvó hörcsög már ... 12 órát.'::text,'aludt'::text,'alszik'::text,'aludni fog'::text,'A megbeszélésig az alvó hörcsög már aludt 12 órát.'::text),
(387840,43094,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie ihren Schönheitsschlaf nicht gehabt hätte, ... der ganze Abend eine Katastrophe gewesen!'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn sie ihren Schönheitsschlaf nicht gehabt hätte, wäre der ganze Abend eine Katastrophe gewesen!'::text),
(387844,43094,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не виспалася для краси, увесь вечір ... катастрофою!'::text,'був би'::text,'буде'::text,'був'::text,'Якби вона не виспалася для краси, увесь вечір був би катастрофою!'::text),
(387843,43094,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si no hubiera dormido su sueño reparador, toda la noche ... un desastre!'::text,'habría sido'::text,'será'::text,'fue'::text,'¡Si no hubiera dormido su sueño reparador, toda la noche habría sido un desastre!'::text),
