(387845,43094,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güzellik uykusunu uyumasaydı bütün akşam tam bir felaket ...!'::text,'olurdu'::text,'olacak'::text,'oldu'::text,'Güzellik uykusunu uyumasaydı bütün akşam tam bir felaket olurdu!'::text),
(387846,43094,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem lett volna meg a szépítő alvása, az egész este katasztrófa ...!'::text,'lett volna'::text,'lesz'::text,'volt'::text,'Ha nem lett volna meg a szépítő alvása, az egész este katasztrófa lett volna!'::text),
