(387853,43095,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хом''як за ноутбуком зізнався, що три ночі ... без сну. Суцільний кошмар!'::text,'був'::text,'бути'::text,'був'::text,'Хом''як за ноутбуком зізнався, що три ночі був без сну. Суцільний кошмар!'::text),
