(387860,43096,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le hamster à l''ordinateur portable ... se coucher il y a des heures.'::text,'aurait dû'::text,'a dû'::text,'aurait'::text,'Le hamster à l''ordinateur portable aurait dû se coucher il y a des heures.'::text),
(387863,43096,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dizüstü bilgisayarlı hamster saatler önce ...'::text,'yatmalıydı'::text,'yatmış olmalı'::text,'yatardı'::text,'Dizüstü bilgisayarlı hamster saatler önce yatmalıydı.'::text),
(387864,43096,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A laptopos hörcsög már órákkal ezelőtt ... aludni.'::text,'el kellett volna mennie'::text,'biztosan elment'::text,'elment volna'::text,'A laptopos hörcsög már órákkal ezelőtt el kellett volna mennie aludni.'::text),
(387867,43097,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der schlafende Hamster ließ sich seine Gesichtsmaske ..., bevor er in einen tiefen Schlaf fiel.'::text,'auflegen'::text,'aufzulegen'::text,'auflegend'::text,'Der schlafende Hamster ließ sich seine Gesichtsmaske auflegen, bevor er in einen tiefen Schlaf fiel.'::text),
(387871,43097,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сплячий хом''як попросив ... йому маску для обличчя, перш ніж поринути в глибокий сон.'::text,'надягти'::text,'надягти'::text,'надягаючи'::text,'Сплячий хом''як попросив надягти йому маску для обличчя, перш ніж поринути в глибокий сон.'::text),
(387870,43097,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hámster dormido se hizo ... la mascarilla antes de caer en un sueño profundo.'::text,'poner'::text,'poner'::text,'poniendo'::text,'El hámster dormido se hizo poner la mascarilla antes de caer en un sueño profundo.'::text),
(387869,43097,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le hamster endormi s''est fait ... son masque avant de sombrer dans un sommeil profond.'::text,'poser'::text,'poser'::text,'posant'::text,'Le hamster endormi s''est fait poser son masque avant de sombrer dans un sommeil profond.'::text),
(387872,43097,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uyuyan hamster derin bir uykuya dalmadan önce yüz maskesini ...'::text,'taktırdı'::text,'takmak'::text,'takarak'::text,'Uyuyan hamster derin bir uykuya dalmadan önce yüz maskesini taktırdı.'::text),
(387873,43097,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alvó hörcsög ... magára az arcmaszkot, mielőtt mély álomba merült.'::text,'feltetette'::text,'feltenni'::text,'feltéve'::text,'Az alvó hörcsög feltetette magára az arcmaszkot, mielőtt mély álomba merült.'::text),
(387876,43098,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hamster am Laptop wünscht sich, er ... letzte Nacht mehr Schlaf gehabt.'::text,'hätte'::text,'hätte'::text,'würde'::text,'Der Hamster am Laptop wünscht sich, er hätte letzte Nacht mehr Schlaf gehabt.'::text),
(387880,43098,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хом''як за ноутбуком хотів би, щоб минулої ночі в нього ... більше сну.'::text,'було'::text,'було'::text,'було б'::text,'Хом''як за ноутбуком хотів би, щоб минулої ночі в нього було більше сну.'::text),
(387879,43098,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hámster del portátil desearía ... más horas de sueño anoche.'::text,'haber tenido'::text,'tener'::text,'tendría'::text,'El hámster del portátil desearía haber tenido más horas de sueño anoche.'::text),
(387878,43098,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le hamster devant l''ordinateur portable aurait aimé ... plus la nuit dernière.'::text,'dormir'::text,'dormir'::text,'dormir'::text,'Le hamster devant l''ordinateur portable aurait aimé dormir plus la nuit dernière.'::text),
(387881,43098,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dizüstü bilgisayarın başındaki hamster, keşke dün gece daha çok ... diye düşünüyor.'::text,'uyusaydı'::text,'uyusa'::text,'uyurdu'::text,'Dizüstü bilgisayarın başındaki hamster, keşke dün gece daha çok uyusaydı diye düşünüyor.'::text),
(387882,43098,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A laptopnál ülő hörcsög azt kívánja, bárcsak többet ... tegnap éjjel.'::text,'aludt volna'::text,'aludt'::text,'aludna'::text,'A laptopnál ülő hörcsög azt kívánja, bárcsak többet aludt volna tegnap éjjel.'::text),
(387885,43099,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, der Hamster, ... Schlaf nie gestört wird, trägt angeblich jede Nacht diese Maske.'::text,'dessen'::text,'der'::text,'der'::text,'Girl, der Hamster, dessen Schlaf nie gestört wird, trägt angeblich jede Nacht diese Maske.'::text),
(387889,43099,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, хом''як, ... сон ніколи ніхто не порушує, кажуть, носить цю маску щоночі.'::text,'чий'::text,'який'::text,'який'::text,'Подруго, хом''як, чий сон ніколи ніхто не порушує, кажуть, носить цю маску щоночі.'::text),
(387888,43099,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, el hámster, ... sueño nunca se interrumpe, al parecer lleva esa mascarilla todas las noches.'::text,'cuyo'::text,'que'::text,'quien'::text,'Tía, el hámster, cuyo sueño nunca se interrumpe, al parecer lleva esa mascarilla todas las noches.'::text),
(387887,43099,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, le hamster, ... le sommeil n''est jamais dérangé, porte apparemment ce masque toutes les nuits.'::text,'dont'::text,'qui'::text,'qui'::text,'Meuf, le hamster, dont le sommeil n''est jamais dérangé, porte apparemment ce masque toutes les nuits.'::text),
(387890,43099,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, uykusu hiç ... hamster, duyduğuma göre her gece o maskeyi takıyormuş.'::text,'bölünmeyen'::text,'bölünmeyen'::text,'bölünmeyen'::text,'Kızım, uykusu hiç bölünmeyen hamster, duyduğuma göre her gece o maskeyi takıyormuş.'::text),
(387891,43099,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a hörcsög, ... az alvását soha semmi nem zavarja, állítólag minden éjjel hordja azt a maszkot.'::text,'akinek'::text,'amely'::text,'aki'::text,'Csajszi, a hörcsög, akinek az alvását soha semmi nem zavarja, állítólag minden éjjel hordja azt a maszkot.'::text),
(387894,43100,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hamster am Laptop schätzt ... offensichtlich mehr als die Arbeit.'::text,'Schlaf'::text,'den Schlaf'::text,'einen Schlaf'::text,'Der Hamster am Laptop schätzt Schlaf offensichtlich mehr als die Arbeit.'::text),
(387898,43100,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хом''як за ноутбуком, очевидно, цінує ... більше, ніж роботу.'::text,'сон'::text,'сон'::text,'сон'::text,'Хом''як за ноутбуком, очевидно, цінує сон більше, ніж роботу.'::text),
(387897,43100,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hámster del portátil obviamente valora ... más que el trabajo.'::text,'el sueño'::text,'el sueño'::text,'un sueño'::text,'El hámster del portátil obviamente valora el sueño más que el trabajo.'::text),
(387896,43100,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le hamster devant l''ordinateur portable apprécie évidemment ... plus que le travail.'::text,'le sommeil'::text,'le sommeil'::text,'un sommeil'::text,'Le hamster devant l''ordinateur portable apprécie évidemment le sommeil plus que le travail.'::text),
(387899,43100,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dizüstü bilgisayarın başındaki hamster belli ki ... işten daha çok önemsiyor.'::text,'uykuyu'::text,'uykuyu'::text,'bir uykuyu'::text,'Dizüstü bilgisayarın başındaki hamster belli ki uykuyu işten daha çok önemsiyor.'::text),
(387900,43100,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A laptopnál ülő hörcsög nyilván többre értékeli ..., mint a munkát.'::text,'az alvást'::text,'az alvást'::text,'egy alvást'::text,'A laptopnál ülő hörcsög nyilván többre értékeli az alvást, mint a munkát.'::text),
(387912,43102,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, bis morgen ... dieser Laptop-Hamster zwei Tage lang null Schlaf gehabt haben, echt.'::text,'wird'::text,'wird'::text,'hat'::text,'Bro, bis morgen wird dieser Laptop-Hamster zwei Tage lang null Schlaf gehabt haben, echt.'::text),
(387916,43102,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, до завтра цей хом''як із ноутбуком ... два дні без сну, реально.'::text,'проведе'::text,'буде'::text,'провів'::text,'Бро, до завтра цей хом''як із ноутбуком проведе два дні без сну, реально.'::text),
(387915,43102,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para mañana ese hámster del portátil ... dos días sin dormir nada, en serio.'::text,'habrá pasado'::text,'pasará'::text,'ha pasado'::text,'Bro, para mañana ese hámster del portátil habrá pasado dos días sin dormir nada, en serio.'::text),
(387914,43102,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, d''ici demain ce hamster à l''ordinateur portable ... zéro sommeil pendant deux jours, grave.'::text,'aura eu'::text,'aura'::text,'a eu'::text,'Frérot, d''ici demain ce hamster à l''ordinateur portable aura eu zéro sommeil pendant deux jours, grave.'::text),
(387917,43102,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarına kadar o dizüstü bilgisayarlı hamster iki gündür hiç ..., cidden.'::text,'uyumamış olacak'::text,'uyumayacak'::text,'uyumadı'::text,'Kanka, yarına kadar o dizüstü bilgisayarlı hamster iki gündür hiç uyumamış olacak, cidden.'::text),
(387918,43102,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, holnapra az a laptopos hörcsög már két napja nem ..., komolyan.'::text,'aludt'::text,'fog aludni'::text,'aludt'::text,'Tesó, holnapra az a laptopos hörcsög már két napja nem aludt, komolyan.'::text),
(360543,40061,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Hamster ... die zwei Eis jetzt schon seit zehn Minuten, und sie schmelzen!'::text,'hält'::text,'hält'::text,'hält'::text,'Dieser Hamster hält die zwei Eis jetzt schon seit zehn Minuten, und sie schmelzen!'::text),
(360547,40061,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей хом''як ... ці два морозива вже десять хвилин, і вони тануть!'::text,'тримає'::text,'тримає'::text,'тримає'::text,'Цей хом''як тримає ці два морозива вже десять хвилин, і вони тануть!'::text),
(360546,40061,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este hámster ... esos dos helados desde hace diez minutos y se están derritiendo!'::text,'sostiene'::text,'está sosteniendo'::text,'sostiene'::text,'¡Este hámster sostiene esos dos helados desde hace diez minutos y se están derritiendo!'::text),
(360545,40061,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce hamster ... ces deux glaces depuis dix minutes, et elles fondent !'::text,'tient'::text,'tient'::text,'tient'::text,'Ce hamster tient ces deux glaces depuis dix minutes, et elles fondent !'::text),
(360548,40061,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu hamster o iki dondurmayı on dakikadır ... ve eriyorlar!'::text,'tutuyor'::text,'tutuyor'::text,'tutar'::text,'Bu hamster o iki dondurmayı on dakikadır tutuyor ve eriyorlar!'::text),
(360549,40061,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a hörcsög már tíz perce ... azt a két jégkrémet, és olvadnak!'::text,'tartja'::text,'tartja'::text,'tartja'::text,'Ez a hörcsög már tíz perce tartja azt a két jégkrémet, és olvadnak!'::text),
(360552,40062,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie ... einen Hamster so zwei Eis halten sehen. Absolut unglaublich!'::text,'habe ich'::text,'ich habe'::text,'sah ich'::text,'Nie habe ich einen Hamster so zwei Eis halten sehen. Absolut unglaublich!'::text),
(360556,40062,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ... хом''яка, який так тримає два морозива. Абсолютно неймовірно!'::text,'я не бачив'::text,'я не бачив'::text,'не бачив я'::text,'Ніколи я не бачив хом''яка, який так тримає два морозива. Абсолютно неймовірно!'::text),
(360555,40062,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca ... a un hámster sujetar así dos helados. ¡Absolutamente increíble!'::text,'he visto'::text,'he visto'::text,'vi'::text,'Nunca he visto a un hámster sujetar así dos helados. ¡Absolutamente increíble!'::text),
(360554,40062,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... un hamster tenir deux glaces comme ça. Absolument incroyable !'::text,'je n''ai vu'::text,'j''ai vu'::text,'vis-je'::text,'Jamais je n''ai vu un hamster tenir deux glaces comme ça. Absolument incroyable !'::text),
(360557,40062,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayatımda ... iki dondurmayı böyle tutan bir hamster. Kesinlikle inanılmaz!'::text,'görmedim'::text,'görmedim'::text,'görmedim'::text,'Hayatımda görmedim iki dondurmayı böyle tutan bir hamster. Kesinlikle inanılmaz!'::text),
(360558,40062,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... hörcsögöt, ami így tartana két jégkrémet. Teljesen hihetetlen!'::text,'nem láttam'::text,'nem láttam'::text,'nem láttam'::text,'Soha nem láttam hörcsögöt, ami így tartana két jégkrémet. Teljesen hihetetlen!'::text),
(360561,40063,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Besitzer brachte den Hamster dazu, für das Foto zwei Eis am Stiel ...'::text,'zu halten'::text,'halten'::text,'hielt'::text,'Der Besitzer brachte den Hamster dazu, für das Foto zwei Eis am Stiel zu halten.'::text),
(360565,40063,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Власник змусив хом''яка ... два ескімо для фото.'::text,'тримати'::text,'тримати'::text,'тримав'::text,'Власник змусив хом''яка тримати два ескімо для фото.'::text),
(360564,40063,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El dueño consiguió que el hámster ... dos helados de palo para la foto.'::text,'sujetara'::text,'sujetar'::text,'sujetó'::text,'El dueño consiguió que el hámster sujetara dos helados de palo para la foto.'::text),
(360563,40063,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le propriétaire a convaincu le hamster de ... deux glaces pour la photo.'::text,'tenir'::text,'tenir'::text,'tenait'::text,'Le propriétaire a convaincu le hamster de tenir deux glaces pour la photo.'::text),
(360566,40063,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahibi, fotoğraf için hamstera iki çubuklu dondurma ...'::text,'tutturdu'::text,'tutturdu'::text,'tuttu'::text,'Sahibi, fotoğraf için hamstera iki çubuklu dondurma tutturdu.'::text),
(360567,40063,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gazdi rávette a hörcsögöt, hogy ... két jégkrémet a fotóhoz.'::text,'tartson'::text,'tartson'::text,'tartott'::text,'A gazdi rávette a hörcsögöt, hogy tartson két jégkrémet a fotóhoz.'::text),
(360570,40064,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Besitzer wünscht sich, der Hamster ... die Eis für noch ein Foto stillhalten.'::text,'würde'::text,'wird'::text,'hält'::text,'Der Besitzer wünscht sich, der Hamster würde die Eis für noch ein Foto stillhalten.'::text),
(360574,40064,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Власник хотів би, щоб хом''як ... ескімо нерухомо ще для одного фото.'::text,'потримав'::text,'потримає'::text,'тримає'::text,'Власник хотів би, щоб хом''як потримав ескімо нерухомо ще для одного фото.'::text),
(360573,40064,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El dueño desearía que el hámster ... quietos los helados para una foto más.'::text,'sujetara'::text,'sujetará'::text,'sujeta'::text,'El dueño desearía que el hámster sujetara quietos los helados para una foto más.'::text),
(360572,40064,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le propriétaire aimerait que le hamster ... les glaces immobiles pour une photo de plus.'::text,'tienne'::text,'tiendra'::text,'tient'::text,'Le propriétaire aimerait que le hamster tienne les glaces immobiles pour une photo de plus.'::text),
(360575,40064,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahibi, hamsterın bir fotoğraf daha için dondurmaları kıpırdatmadan ... istiyor.'::text,'tutmasını'::text,'tutacağını'::text,'tuttuğunu'::text,'Sahibi, hamsterın bir fotoğraf daha için dondurmaları kıpırdatmadan tutmasını istiyor.'::text),
(360576,40064,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gazdi azt szeretné, ha a hörcsög még egy fotó erejéig mozdulatlanul ... a jégkrémeket.'::text,'tartaná'::text,'tartja majd'::text,'tartja'::text,'A gazdi azt szeretné, ha a hörcsög még egy fotó erejéig mozdulatlanul tartaná a jégkrémeket.'::text),
(360579,40065,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hamster, ... Pfoten zwei Eis am Stiel halten, grinst in die Kamera.'::text,'dessen'::text,'der'::text,'der'::text,'Der Hamster, dessen Pfoten zwei Eis am Stiel halten, grinst in die Kamera.'::text),
(360583,40065,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хом''як, ... лапки тримають два ескімо, усміхається в камеру.'::text,'чиї'::text,'який'::text,'що'::text,'Хом''як, чиї лапки тримають два ескімо, усміхається в камеру.'::text),
(360582,40065,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hámster, ... patitas sujetan dos helados de palo, sonríe a la cámara.'::text,'cuyas'::text,'que'::text,'que'::text,'El hámster, cuyas patitas sujetan dos helados de palo, sonríe a la cámara.'::text),
(360581,40065,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le hamster, ... les pattes tiennent deux glaces, sourit à la caméra.'::text,'dont'::text,'qui'::text,'que'::text,'Le hamster, dont les pattes tiennent deux glaces, sourit à la caméra.'::text),
(360584,40065,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Patileri iki çubuklu dondurma ... hamster kameraya sırıtıyor.'::text,'tutan'::text,'tutan'::text,'tutan'::text,'Patileri iki çubuklu dondurma tutan hamster kameraya sırıtıyor.'::text),
(360585,40065,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hörcsög, ... a mancsai két jégkrémet tartanak, vigyorog a kamerába.'::text,'akinek'::text,'amely'::text,'ami'::text,'A hörcsög, akinek a mancsai két jégkrémet tartanak, vigyorog a kamerába.'::text),
(360588,40066,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... seiner winzigen Pfoten hält der Hamster beide Eis am Stiel. Ein echter Profi, ganz klar.'::text,'Trotz'::text,'Aufgrund'::text,'Im Fall'::text,'Trotz seiner winzigen Pfoten hält der Hamster beide Eis am Stiel. Ein echter Profi, ganz klar.'::text),
(360592,40066,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... крихітні лапки, хом''як тримає обидва ескімо. Справжній професіонал, звісно.'::text,'Попри'::text,'Завдяки'::text,'У разі'::text,'Попри крихітні лапки, хом''як тримає обидва ескімо. Справжній професіонал, звісно.'::text),
(360591,40066,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sus diminutas patitas, el hámster sujeta los dos helados. Todo un profesional, claramente.'::text,'A pesar de'::text,'Debido a'::text,'En caso de'::text,'A pesar de sus diminutas patitas, el hámster sujeta los dos helados. Todo un profesional, claramente.'::text),
(360590,40066,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ses minuscules pattes, le hamster tient les deux glaces. Un vrai pro, clairement.'::text,'Malgré'::text,'En raison de'::text,'En cas de'::text,'Malgré ses minuscules pattes, le hamster tient les deux glaces. Un vrai pro, clairement.'::text),
(360593,40066,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minik patilerine ... hamster iki dondurmayı da tutuyor. Tam bir profesyonel, belli ki.'::text,'rağmen'::text,'sayesinde'::text,'durumunda'::text,'Minik patilerine rağmen hamster iki dondurmayı da tutuyor. Tam bir profesyonel, belli ki.'::text),
(360594,40066,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Apró mancsai ... a hörcsög mindkét jégkrémet tartja. Igazi profi, nyilvánvalóan.'::text,'ellenére'::text,'miatt'::text,'esetén'::text,'Apró mancsai ellenére a hörcsög mindkét jégkrémet tartja. Igazi profi, nyilvánvalóan.'::text),
(360597,40067,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hamster wusste, er ... beide Eis für das Foto stillhalten. Kein einziger Biss, natürlich.'::text,'würde'::text,'wird'::text,'hält'::text,'Der Hamster wusste, er würde beide Eis für das Foto stillhalten. Kein einziger Biss, natürlich.'::text),
(360601,40067,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хом''як знав, що ... обидва ескімо нерухомо для фото. Жодного укусу, звісно.'::text,'триматиме'::text,'триматиме'::text,'тримає'::text,'Хом''як знав, що триматиме обидва ескімо нерухомо для фото. Жодного укусу, звісно.'::text),
(360600,40067,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hámster sabía que ... los dos helados quietos para la foto. Ni un solo mordisco, obviamente.'::text,'sujetaría'::text,'sujetará'::text,'está sujetando'::text,'El hámster sabía que sujetaría los dos helados quietos para la foto. Ni un solo mordisco, obviamente.'::text),
(360599,40067,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le hamster savait qu''il ... les deux glaces immobiles pour la photo. Pas une seule bouchée, évidemment.'::text,'tiendrait'::text,'tiendra'::text,'tient'::text,'Le hamster savait qu''il tiendrait les deux glaces immobiles pour la photo. Pas une seule bouchée, évidemment.'::text),
(360602,40067,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamster, fotoğraf için iki dondurmayı da kıpırdatmadan ... biliyordu. Tek bir ısırık bile yok, tabii ki.'::text,'tutacağını'::text,'tutacağını'::text,'tuttuğunu'::text,'Hamster, fotoğraf için iki dondurmayı da kıpırdatmadan tutacağını biliyordu. Tek bir ısırık bile yok, tabii ki.'::text),
(360603,40067,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hörcsög tudta, hogy a fotóhoz mozdulatlanul ... mindkét jégkrémet. Egyetlen harapás sem, persze.'::text,'fogja tartani'::text,'fogja tartani'::text,'tartja'::text,'A hörcsög tudta, hogy a fotóhoz mozdulatlanul fogja tartani mindkét jégkrémet. Egyetlen harapás sem, persze.'::text),
(360615,40069,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, der ... beide Eis ewig hochgehalten, bevor er abgebissen hat.'::text,'hatte'::text,'hat'::text,'hielt'::text,'Nee Bro, der hatte beide Eis ewig hochgehalten, bevor er abgebissen hat.'::text),
(360619,40069,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, він ... обидва морозива вгорі цілу вічність, перш ніж відкусив.'::text,'тримав'::text,'тримає'::text,'тримав'::text,'Не, бро, він тримав обидва морозива вгорі цілу вічність, перш ніж відкусив.'::text),
(360618,40069,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, bro, ... los dos helados en alto un montón de rato antes de dar ese mordisco.'::text,'había estado sujetando'::text,'ha estado sujetando'::text,'estaba sujetando'::text,'Qué va, bro, había estado sujetando los dos helados en alto un montón de rato antes de dar ese mordisco.'::text),
(360617,40069,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frérot, il ... les deux glaces en l''air pendant des plombes avant de croquer dedans.'::text,'avait tenu'::text,'a tenu'::text,'tenait'::text,'Nan frérot, il avait tenu les deux glaces en l''air pendant des plombes avant de croquer dedans.'::text),
(360620,40069,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, o ısırığı almadan önce iki dondurmayı da asırlarca havada ...'::text,'tutmuştu'::text,'tutuyor'::text,'tutuyordu'::text,'Yok kanka, o ısırığı almadan önce iki dondurmayı da asırlarca havada tutmuştu.'::text),
(360621,40069,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, egy örökkévalóságig ... fent mindkét jégkrémet, mielőtt beleharapott.'::text,'tartotta'::text,'tartja'::text,'tartotta'::text,'Nem, tesó, egy örökkévalóságig tartotta fent mindkét jégkrémet, mielőtt beleharapott.'::text),
(360624,40070,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zur Foto-Deadline ... der Hamster beide Eis 10 Minuten lang gehalten haben.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis zur Foto-Deadline wird der Hamster beide Eis 10 Minuten lang gehalten haben.'::text),
(360628,40070,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До дедлайну фотосесії хом''як ... обидва ескімо вже 10 хвилин.'::text,'триматиме'::text,'триматиме'::text,'триматиме'::text,'До дедлайну фотосесії хом''як триматиме обидва ескімо вже 10 хвилин.'::text),
(360627,40070,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el plazo de la foto, el hámster ... los dos helados 10 minutos.'::text,'llevará sujetando'::text,'sujetará'::text,'estará sujetando'::text,'Para el plazo de la foto, el hámster llevará sujetando los dos helados 10 minutos.'::text),
(360626,40070,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la deadline de la photo, le hamster ... les deux glaces depuis 10 minutes.'::text,'tiendra'::text,'tiendra'::text,'sera en train de tenir'::text,'D''ici la deadline de la photo, le hamster tiendra les deux glaces depuis 10 minutes.'::text),
(360629,40070,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fotoğraf teslim saatine kadar hamster iki dondurmayı 10 dakikadır ...'::text,'tutuyor olacak'::text,'tutacak'::text,'tutuyor olacak'::text,'Fotoğraf teslim saatine kadar hamster iki dondurmayı 10 dakikadır tutuyor olacak.'::text),
(360630,40070,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fotó határidejéig a hörcsög már 10 perce ... mindkét jégkrémet.'::text,'fogja tartani'::text,'tartja majd'::text,'fogja tartani'::text,'A fotó határidejéig a hörcsög már 10 perce fogja tartani mindkét jégkrémet.'::text),
(350427,38937,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Motor ... gleichmäßig, als er plötzlich eine Wolke schwarzen Rauchs ausstieß.'::text,'lief'::text,'lief'::text,'ist gelaufen'::text,'Der Motor lief gleichmäßig, als er plötzlich eine Wolke schwarzen Rauchs ausstieß.'::text),
(350431,38937,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двигун ... рівно, коли раптом випустив хмару чорного диму.'::text,'працював'::text,'попрацював'::text,'працював'::text,'Двигун працював рівно, коли раптом випустив хмару чорного диму.'::text),
(350430,38937,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El motor ... de forma estable cuando de repente soltó una nube de humo negro.'::text,'estaba funcionando'::text,'funcionó'::text,'ha funcionado'::text,'El motor estaba funcionando de forma estable cuando de repente soltó una nube de humo negro.'::text),
(350429,38937,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le moteur ... régulièrement quand il a soudain émis un nuage de fumée noire.'::text,'tournait'::text,'a tourné'::text,'a tourné'::text,'Le moteur tournait régulièrement quand il a soudain émis un nuage de fumée noire.'::text),
(350432,38937,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Motor düzenli ... ki aniden bir kara duman bulutu çıkardı.'::text,'çalışıyordu'::text,'çalıştı'::text,'çalıştı'::text,'Motor düzenli çalışıyordu ki aniden bir kara duman bulutu çıkardı.'::text),
(350433,38937,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A motor egyenletesen ..., amikor hirtelen fekete füstfelhőt bocsátott ki.'::text,'járt'::text,'járt'::text,'járt'::text,'A motor egyenletesen járt, amikor hirtelen fekete füstfelhőt bocsátott ki.'::text),
(350436,38938,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Motor ... heute zweimal schwarzen Rauch gemacht, also hat er heute zweimal geraucht.'::text,'hat'::text,'hat'::text,'macht'::text,'Der Motor hat heute zweimal schwarzen Rauch gemacht, also hat er heute zweimal geraucht.'::text),
(350440,38938,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двигун сьогодні двічі ... чорний дим, тож сьогодні він димів двічі.'::text,'випустив'::text,'випускав'::text,'випускає'::text,'Двигун сьогодні двічі випустив чорний дим, тож сьогодні він димів двічі.'::text),
(350439,38938,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El motor ... humo negro dos veces hoy, así que hoy ha echado humo dos veces.'::text,'ha echado'::text,'ha estado echando'::text,'echa'::text,'El motor ha echado humo negro dos veces hoy, así que hoy ha echado humo dos veces.'::text),
(350438,38938,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le moteur ... de la fumée noire deux fois aujourd''hui, donc aujourd''hui il a fumé deux fois.'::text,'a fait'::text,'a fait'::text,'fait'::text,'Le moteur a fait de la fumée noire deux fois aujourd''hui, donc aujourd''hui il a fumé deux fois.'::text),
(350441,38938,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Motor bugün iki kez kara duman ..., yani bugün iki kere tüttü.'::text,'çıkardı'::text,'çıkarıyordu'::text,'çıkarır'::text,'Motor bugün iki kez kara duman çıkardı, yani bugün iki kere tüttü.'::text),
(350442,38938,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A motor ma kétszer ... fekete füstöt, szóval ma kétszer füstölt.'::text,'eregetett'::text,'eregetett'::text,'ereget'::text,'A motor ma kétszer eregetett fekete füstöt, szóval ma kétszer füstölt.'::text),
(350445,38939,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Motor ... angesprungen, bevor der Rauch kam, denn Rauch braucht einen Motor, der an ist.'::text,'war'::text,'ist'::text,'springt'::text,'Der Motor war angesprungen, bevor der Rauch kam, denn Rauch braucht einen Motor, der an ist.'::text),
(350449,38939,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двигун ... ще до того, як вийшов дим, бо диму потрібен двигун, який увімкнений.'::text,'завівся'::text,'завівся'::text,'заводиться'::text,'Двигун завівся ще до того, як вийшов дим, бо диму потрібен двигун, який увімкнений.'::text),
(350448,38939,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El motor ... antes de que saliera el humo, porque el humo necesita un motor que esté encendido.'::text,'había arrancado'::text,'ha arrancado'::text,'arranca'::text,'El motor había arrancado antes de que saliera el humo, porque el humo necesita un motor que esté encendido.'::text),
(350447,38939,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le moteur ... avant que la fumée sorte, parce que la fumée a besoin d''un moteur allumé.'::text,'avait démarré'::text,'a démarré'::text,'démarre'::text,'Le moteur avait démarré avant que la fumée sorte, parce que la fumée a besoin d''un moteur allumé.'::text),
(350450,38939,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Motor duman çıkmadan önce ..., çünkü duman için çalışan bir motor lazım.'::text,'çalışmıştı'::text,'çalıştı'::text,'çalışır'::text,'Motor duman çıkmadan önce çalışmıştı, çünkü duman için çalışan bir motor lazım.'::text),
(350451,38939,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A motor már ..., mielőtt a füst kijött, mert a füsthöz bekapcsolt motor kell.'::text,'beindult'::text,'beindult'::text,'beindul'::text,'A motor már beindult, mielőtt a füst kijött, mert a füsthöz bekapcsolt motor kell.'::text),
(350454,38940,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ... der Motor morgen um diese Zeit wieder die ganze Weinbergtour über laufen.'::text,'wird'::text,'wird'::text,'läuft'::text,'Hör zu, angeblich wird der Motor morgen um diese Zeit wieder die ganze Weinbergtour über laufen.'::text),
(350458,38940,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, завтра в цей час двигун знову ... всю екскурсію виноградником.'::text,'працюватиме'::text,'запрацює'::text,'працює'::text,'Слухай, кажуть, завтра в цей час двигун знову працюватиме всю екскурсію виноградником.'::text),
(350457,38940,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer mañana a esta hora el motor ... otra vez durante todo el tour por los viñedos.'::text,'estará funcionando'::text,'funcionará'::text,'funciona'::text,'Oye, al parecer mañana a esta hora el motor estará funcionando otra vez durante todo el tour por los viñedos.'::text),
(350456,38940,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment demain à cette heure-ci le moteur ... encore pendant toute la visite des vignes.'::text,'sera en train de tourner'::text,'tournera'::text,'tourne'::text,'Écoute, apparemment demain à cette heure-ci le moteur sera en train de tourner encore pendant toute la visite des vignes.'::text),
(350459,38940,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anlaşılan yarın bu saatlerde motor bütün bağ turu boyunca yine ...'::text,'çalışıyor olacakmış'::text,'çalışacakmış'::text,'çalışıyormuş'::text,'Dinle, anlaşılan yarın bu saatlerde motor bütün bağ turu boyunca yine çalışıyor olacakmış.'::text),
(350460,38940,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag holnap ilyenkor a motor megint ... az egész szőlőtúra alatt.'::text,'járni fog'::text,'jár majd'::text,'jár'::text,'Figyelj, állítólag holnap ilyenkor a motor megint járni fog az egész szőlőtúra alatt.'::text),
(350463,38941,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, der Bauer meinte, er glaubt, der Motor ... nächste Woche kaputtgehen, der ist so alt.'::text,'wird'::text,'wird'::text,'geht'::text,'Girl, der Bauer meinte, er glaubt, der Motor wird nächste Woche kaputtgehen, der ist so alt.'::text),
(350467,38941,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, фермер сказав, що, на його думку, двигун ... наступного тижня, він такий старий.'::text,'зламається'::text,'ламатиметься'::text,'ламається'::text,'Подруго, фермер сказав, що, на його думку, двигун зламається наступного тижня, він такий старий.'::text),
(350466,38941,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, el granjero dijo que cree que el motor ... la semana que viene, es súper viejo.'::text,'se estropeará'::text,'se estará estropeando'::text,'se estropea'::text,'Tía, el granjero dijo que cree que el motor se estropeará la semana que viene, es súper viejo.'::text),
(350465,38941,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, le fermier a dit qu''il pense que le moteur ... la semaine prochaine, il est trop vieux.'::text,'lâchera'::text,'sera en train de lâcher'::text,'lâche'::text,'Meuf, le fermier a dit qu''il pense que le moteur lâchera la semaine prochaine, il est trop vieux.'::text),
(350468,38941,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, çiftçi motorun gelecek hafta ... düşündüğünü söyledi, o kadar eski ki.'::text,'bozulacağını'::text,'bozuluyor olacağını'::text,'bozulduğunu'::text,'Kızım, çiftçi motorun gelecek hafta bozulacağını düşündüğünü söyledi, o kadar eski ki.'::text),
(350469,38941,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a gazda azt mondta, szerinte a motor jövő héten ..., annyira öreg.'::text,'le fog robbanni'::text,'épp lerobbanóban lesz'::text,'lerobban'::text,'Csajszi, a gazda azt mondta, szerinte a motor jövő héten le fog robbanni, annyira öreg.'::text),
(350472,38942,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein alter Motor zu hart arbeitet, ... er schwarzen Rauch aus. Herrlich für die Weinberge, natürlich.'::text,'stößt'::text,'stieß'::text,'wird'::text,'Wenn ein alter Motor zu hart arbeitet, stößt er schwarzen Rauch aus. Herrlich für die Weinberge, natürlich.'::text),
(350476,38942,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо старий двигун працює надто важко, він ... чорний дим. Чудово для виноградників, звісно.'::text,'випускає'::text,'випустив'::text,'випустить'::text,'Якщо старий двигун працює надто важко, він випускає чорний дим. Чудово для виноградників, звісно.'::text),
(350475,38942,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un motor viejo trabaja demasiado, ... humo negro. Precioso para los viñedos, obviamente.'::text,'suelta'::text,'soltó'::text,'soltará'::text,'Si un motor viejo trabaja demasiado, suelta humo negro. Precioso para los viñedos, obviamente.'::text),
(350474,38942,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un vieux moteur force trop, il ... de la fumée noire. Génial pour les vignes, évidemment.'::text,'dégage'::text,'a dégagé'::text,'dégagera'::text,'Si un vieux moteur force trop, il dégage de la fumée noire. Génial pour les vignes, évidemment.'::text),
(350477,38942,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eski bir motor fazla zorlanırsa kara duman ... — bağlar için harika, tabii ki.'::text,'çıkarır'::text,'çıkardı'::text,'çıkaracak'::text,'Eski bir motor fazla zorlanırsa kara duman çıkarır — bağlar için harika, tabii ki.'::text),
(350478,38942,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy öreg motor túl keményen dolgozik, ... fekete füstöt. Remek a szőlőknek, persze.'::text,'ereget'::text,'eregetett'::text,'eregetni fog'::text,'Ha egy öreg motor túl keményen dolgozik, ereget fekete füstöt. Remek a szőlőknek, persze.'::text),
(350481,38943,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Corgi schneller fährt, ... der Motor mehr schwarzen Rauch machen.'::text,'wird'::text,'würde'::text,'machte'::text,'Wenn der Corgi schneller fährt, wird der Motor mehr schwarzen Rauch machen.'::text),
(350485,38943,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо коргі їхатиме швидше, двигун ... більше чорного диму.'::text,'випустить'::text,'випустив би'::text,'випустив'::text,'Якщо коргі їхатиме швидше, двигун випустить більше чорного диму.'::text),
(350484,38943,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el corgi conduce más rápido, el motor ... más humo negro.'::text,'echará'::text,'echaría'::text,'echó'::text,'Si el corgi conduce más rápido, el motor echará más humo negro.'::text),
(350483,38943,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le corgi roule plus vite, le moteur ... plus de fumée noire.'::text,'fera'::text,'ferait'::text,'a fait'::text,'Si le corgi roule plus vite, le moteur fera plus de fumée noire.'::text),
(350486,38943,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Korgi daha hızlı giderse motor daha çok kara duman ...'::text,'çıkaracak'::text,'çıkarırdı'::text,'çıkardı'::text,'Korgi daha hızlı giderse motor daha çok kara duman çıkaracak.'::text),
(350487,38943,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a corgi gyorsabban vezet, a motor több fekete füstöt ...'::text,'fog eregetni'::text,'eregetne'::text,'eregetett'::text,'Ha a corgi gyorsabban vezet, a motor több fekete füstöt fog eregetni.'::text),
(350499,38945,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der alte Motor ... im Laufe der Jahre oft von Hand repariert.'::text,'wurde'::text,'hat'::text,'repariert'::text,'Der alte Motor wurde im Laufe der Jahre oft von Hand repariert.'::text),
(350503,38945,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Старий двигун ... вручну багато разів за ці роки.'::text,'ремонтували'::text,'відремонтував'::text,'ремонтує'::text,'Старий двигун ремонтували вручну багато разів за ці роки.'::text),
(350502,38945,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El viejo motor ... a mano muchas veces a lo largo de los años.'::text,'ha sido reparado'::text,'ha reparado'::text,'está reparando'::text,'El viejo motor ha sido reparado a mano muchas veces a lo largo de los años.'::text),
(350501,38945,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vieux moteur ... à la main plusieurs fois au fil des années.'::text,'a été réparé'::text,'a réparé'::text,'répare'::text,'Le vieux moteur a été réparé à la main plusieurs fois au fil des années.'::text),
(350504,38945,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eski motor yıllar içinde defalarca elle ...'::text,'tamir edildi'::text,'tamir etti'::text,'tamir ediyor'::text,'Eski motor yıllar içinde defalarca elle tamir edildi.'::text),
(350505,38945,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A régi motort az évek során sokszor ... kézzel.'::text,'megjavították'::text,'megjavította'::text,'javítja'::text,'A régi motort az évek során sokszor megjavították kézzel.'::text),
(350508,38946,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Motor ... eine dichte Wolke schwarzen Rauchs aus, was typischerweise auf eine hohe Last hinweist.'::text,'stößt'::text,'wird'::text,'ausstoßend'::text,'Der Motor stößt eine dichte Wolke schwarzen Rauchs aus, was typischerweise auf eine hohe Last hinweist.'::text),
(350512,38946,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двигун ... густу хмару чорного диму, що зазвичай вказує на велике навантаження.'::text,'випускає'::text,'випускається'::text,'випускаючи'::text,'Двигун випускає густу хмару чорного диму, що зазвичай вказує на велике навантаження.'::text),
(350511,38946,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El motor ... una densa nube de humo negro, lo que normalmente indica una carga elevada.'::text,'libera'::text,'es liberado'::text,'liberando'::text,'El motor libera una densa nube de humo negro, lo que normalmente indica una carga elevada.'::text),
(350510,38946,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le moteur ... un épais nuage de fumée noire, ce qui indique généralement une forte charge.'::text,'libère'::text,'est libéré'::text,'libérant'::text,'Le moteur libère un épais nuage de fumée noire, ce qui indique généralement une forte charge.'::text),
(350513,38946,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Motor yoğun bir kara duman bulutu ..., bu genellikle yüksek yüke işaret eder.'::text,'salıyor'::text,'salınıyor'::text,'salarak'::text,'Motor yoğun bir kara duman bulutu salıyor, bu genellikle yüksek yüke işaret eder.'::text),
(350514,38946,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A motor sűrű fekete füstfelhőt ..., ami jellemzően nagy terhelésre utal.'::text,'bocsát ki'::text,'bocsáttatik ki'::text,'kibocsátva'::text,'A motor sűrű fekete füstfelhőt bocsát ki, ami jellemzően nagy terhelésre utal.'::text),
(334254,37140,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Tier ... sehr stark sein, denn es trägt einen Reiter auf dem Rücken.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Das Tier muss sehr stark sein, denn es trägt einen Reiter auf dem Rücken.'::text),
(334258,37140,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звір ... бути дуже сильним, бо несе на спині вершника.'::text,'мусить'::text,'не може'::text,'не повинен'::text,'Звір мусить бути дуже сильним, бо несе на спині вершника.'::text),
(334257,37140,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bestia ... ser muy fuerte, porque lleva a un jinete en el lomo.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'La bestia debe de ser muy fuerte, porque lleva a un jinete en el lomo.'::text),
(334256,37140,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bête ... être très forte, car elle porte un cavalier sur son dos.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'La bête doit être très forte, car elle porte un cavalier sur son dos.'::text),
(334259,37140,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayvan çok güçlü ..., çünkü sırtında bir binici taşıyor.'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Hayvan çok güçlü olmalı, çünkü sırtında bir binici taşıyor.'::text),
(334260,37140,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lény nagyon erős ..., mert egy lovast visz a hátán.'::text,'kell hogy legyen'::text,'nem lehet'::text,'nem kéne hogy legyen'::text,'A lény nagyon erős kell hogy legyen, mert egy lovast visz a hátán.'::text),
(334272,37142,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, das Tier ... ohne jede Vorwarnung von der Klippe gesprungen.'::text,'war'::text,'ist'::text,'springt'::text,'Hör zu, er hat mir erzählt, das Tier war ohne jede Vorwarnung von der Klippe gesprungen.'::text),
(334276,37142,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що звір ... зі скелі без жодного попередження.'::text,'стрибнув'::text,'стрибнув'::text,'стрибає'::text,'Слухай, він сказав мені, що звір стрибнув зі скелі без жодного попередження.'::text),
(334275,37142,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que la bestia ... del acantilado sin ningún aviso.'::text,'había saltado'::text,'ha saltado'::text,'salta'::text,'Oye, me dijo que la bestia había saltado del acantilado sin ningún aviso.'::text),
(334274,37142,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que la bête ... de la falaise sans prévenir.'::text,'avait sauté'::text,'a sauté'::text,'saute'::text,'Écoute, il m''a dit que la bête avait sauté de la falaise sans prévenir.'::text),
(334277,37142,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana hayvanın hiç uyarmadan uçurumdan ... söyledi.'::text,'atladığını'::text,'atladığını'::text,'atladığını'::text,'Dinle, bana hayvanın hiç uyarmadan uçurumdan atladığını söyledi.'::text),
(334278,37142,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a lény minden figyelmeztetés nélkül ... a szikláról.'::text,'leugrott'::text,'leugrott'::text,'leugrik'::text,'Figyelj, azt mondta, hogy a lény minden figyelmeztetés nélkül leugrott a szikláról.'::text),
(334281,37143,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als es klein war, ... sich das Tier jeden Tag hinter dem Wasserfall. Eindeutig ein Held.'::text,'versteckte'::text,'versteckte'::text,'war es gewohnt'::text,'Als es klein war, versteckte sich das Tier jeden Tag hinter dem Wasserfall. Eindeutig ein Held.'::text),
(334285,37143,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли був малим, звір щодня ... за водоспадом. Явно герой.'::text,'ховався'::text,'ховався'::text,'звик ховатися'::text,'Коли був малим, звір щодня ховався за водоспадом. Явно герой.'::text),
(334284,37143,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De pequeña, la bestia ... detrás de la cascada todos los días. Toda una heroína, obviamente.'::text,'se escondía'::text,'se escondía'::text,'estaba acostumbrada a esconderse'::text,'De pequeña, la bestia se escondía detrás de la cascada todos los días. Toda una heroína, obviamente.'::text),
(334283,37143,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle était petite, la bête ... derrière la cascade tous les jours. Un vrai héros, évidemment.'::text,'se cachait'::text,'se cachait'::text,'avait l''habitude de se cacher'::text,'Quand elle était petite, la bête se cachait derrière la cascade tous les jours. Un vrai héros, évidemment.'::text),
(334286,37143,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçükken hayvan her gün şelalenin arkasına ... — belli ki tam bir kahraman.'::text,'saklanırdı'::text,'saklanırdı'::text,'saklanmaya alışkındı'::text,'Küçükken hayvan her gün şelalenin arkasına saklanırdı — belli ki tam bir kahraman.'::text),
(334287,37143,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kicsi korában a lény minden nap ... a vízesés mögé. Nyilván egy hős.'::text,'elbújt'::text,'elbújt'::text,'hozzá volt szokva, hogy elbújjon'::text,'Kicsi korában a lény minden nap elbújt a vízesés mögé. Nyilván egy hős.'::text),
(334290,37144,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Tier beschloss, ohne Vorwarnung von der Klippe ... – eine makellose Sicherheitseinweisung.'::text,'zu springen'::text,'springen'::text,'springen'::text,'Das Tier beschloss, ohne Vorwarnung von der Klippe zu springen – eine makellose Sicherheitseinweisung.'::text),
(334294,37144,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звір вирішив ... зі скелі без попередження. Бездоганний інструктаж з безпеки.'::text,'стрибнути'::text,'стрибання'::text,'стрибнути'::text,'Звір вирішив стрибнути зі скелі без попередження. Бездоганний інструктаж з безпеки.'::text),
(334293,37144,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bestia decidió ... del acantilado sin avisar. Una charla de seguridad impecable.'::text,'saltar'::text,'saltando'::text,'saltar'::text,'La bestia decidió saltar del acantilado sin avisar. Una charla de seguridad impecable.'::text),
(334292,37144,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bête a décidé ... de la falaise sans prévenir. Un briefing sécurité impeccable.'::text,'de sauter'::text,'sauter'::text,'sauter'::text,'La bête a décidé de sauter de la falaise sans prévenir. Un briefing sécurité impeccable.'::text),
(334295,37144,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayvan hiç uyarmadan uçurumdan ... karar verdi. Kusursuz bir güvenlik brifingi.'::text,'atlamaya'::text,'atlamayı'::text,'atla'::text,'Hayvan hiç uyarmadan uçurumdan atlamaya karar verdi. Kusursuz bir güvenlik brifingi.'::text),
(334296,37144,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lény úgy döntött, hogy figyelmeztetés nélkül ... a szikláról. Hibátlan biztonsági eligazítás.'::text,'leugrik'::text,'leugrást'::text,'ugrik'::text,'A lény úgy döntött, hogy figyelmeztetés nélkül leugrik a szikláról. Hibátlan biztonsági eligazítás.'::text),
(334299,37145,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Tier ist von der Klippe gesprungen, ...?'::text,'oder?'::text,'oder?'::text,'echt?'::text,'Das Tier ist von der Klippe gesprungen, oder?'::text),
(334303,37145,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звір стрибнув зі скелі, ...?'::text,'так?'::text,'так?'::text,'справді?'::text,'Звір стрибнув зі скелі, так?'::text),
(334302,37145,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bestia saltó del acantilado, ...'::text,'¿verdad?'::text,'¿verdad?'::text,'¿en serio?'::text,'La bestia saltó del acantilado, ¿verdad?'::text),
(334301,37145,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bête a sauté de la falaise, ... ?'::text,'non ?'::text,'non ?'::text,'vraiment ?'::text,'La bête a sauté de la falaise, non ?'::text),
(334304,37145,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayvan uçurumdan atladı, ...?'::text,'değil mi?'::text,'değil mi?'::text,'öyle mi?'::text,'Hayvan uçurumdan atladı, değil mi?'::text),
(334305,37145,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lény leugrott a szikláról, ...?'::text,'ugye?'::text,'ugye?'::text,'tényleg?'::text,'A lény leugrott a szikláról, ugye?'::text),
(334308,37146,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Tier hatte keine Angst vor dem Abgrund, und ... der Reiter auf seinem Rücken.'::text,'genauso wenig'::text,'genauso'::text,'genauso wenig'::text,'Das Tier hatte keine Angst vor dem Abgrund, und genauso wenig der Reiter auf seinem Rücken.'::text),
(334312,37146,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звір не боявся висоти, і ... вершник на його спині.'::text,'так само не боявся'::text,'так само боявся'::text,'так само не боявся'::text,'Звір не боявся висоти, і так само не боявся вершник на його спині.'::text),
(334311,37146,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bestia no tenía miedo a la caída, y ... el jinete que llevaba a lomos.'::text,'tampoco'::text,'también'::text,'tampoco'::text,'La bestia no tenía miedo a la caída, y tampoco el jinete que llevaba a lomos.'::text),
(334310,37146,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bête n''avait pas peur du vide, ... le cavalier sur son dos.'::text,'pas plus que'::text,'tout comme'::text,'pas plus que'::text,'La bête n''avait pas peur du vide, pas plus que le cavalier sur son dos.'::text),
(334313,37146,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayvan uçurumdan korkmuyordu, sırtındaki binici de ...'::text,'korkmuyordu'::text,'korkuyordu'::text,'korkmuyordu'::text,'Hayvan uçurumdan korkmuyordu, sırtındaki binici de korkmuyordu.'::text),
(334314,37146,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lény nem félt a mélységtől, és ... a hátán ülő lovas sem.'::text,'nem félt'::text,'félt'::text,'nem félt'::text,'A lény nem félt a mélységtől, és nem félt a hátán ülő lovas sem.'::text),
(334326,37148,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Einbruch der Nacht ... das Tier etwa fünfzig Kilometer geflogen sein.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis zum Einbruch der Nacht wird das Tier etwa fünfzig Kilometer geflogen sein.'::text),
(334330,37148,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До настання ночі звір ... приблизно п''ятдесят кілометрів.'::text,'пролетить'::text,'полетить'::text,'летітиме'::text,'До настання ночі звір пролетить приблизно п''ятдесят кілометрів.'::text),
(334329,37148,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al anochecer, la bestia ... aproximadamente cincuenta kilómetros.'::text,'habrá volado'::text,'volará'::text,'estará volando'::text,'Al anochecer, la bestia habrá volado aproximadamente cincuenta kilómetros.'::text),
(334328,37148,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la tombée de la nuit, la bête ... environ cinquante kilomètres.'::text,'aura parcouru'::text,'parcourra'::text,'sera en train de parcourir'::text,'D''ici la tombée de la nuit, la bête aura parcouru environ cinquante kilomètres.'::text),
(334331,37148,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akşam karanlığına kadar hayvan yaklaşık elli kilometre ...'::text,'uçmuş olacak'::text,'uçacak'::text,'uçuyor olacak'::text,'Akşam karanlığına kadar hayvan yaklaşık elli kilometre uçmuş olacak.'::text),
(334332,37148,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estig a lény nagyjából ötven kilométert ...'::text,'le fog repülni'::text,'repül'::text,'repülni fog'::text,'Estig a lény nagyjából ötven kilométert le fog repülni.'::text),
(334335,37149,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn es die Burg erreicht, ... das Tier etwa drei Stunden lang geflogen sein.'::text,'wird'::text,'wird'::text,'wird'::text,'Wenn es die Burg erreicht, wird das Tier etwa drei Stunden lang geflogen sein.'::text),
(334339,37149,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли звір долетить до замку, він ... вже приблизно три години.'::text,'летітиме'::text,'летітиме'::text,'летітиме'::text,'Коли звір долетить до замку, він летітиме вже приблизно три години.'::text),
(334338,37149,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando llegue al castillo, la bestia ... unas tres horas.'::text,'llevará volando'::text,'estará volando'::text,'volará'::text,'Cuando llegue al castillo, la bestia llevará volando unas tres horas.'::text),
(334337,37149,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle atteindra le château, la bête ... depuis environ trois heures.'::text,'volera'::text,'volera'::text,'volera'::text,'Quand elle atteindra le château, la bête volera depuis environ trois heures.'::text),
(334340,37149,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaleye vardığında hayvan yaklaşık üç saattir ...'::text,'uçuyor olacak'::text,'uçuyor olacak'::text,'uçacak'::text,'Kaleye vardığında hayvan yaklaşık üç saattir uçuyor olacak.'::text),
(334341,37149,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire eléri a várat, a lény már nagyjából három órája ...'::text,'repül'::text,'repül'::text,'repülni fog'::text,'Mire eléri a várat, a lény már nagyjából három órája repül.'::text),
(334344,37150,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Sattel nicht fest gesessen hätte, ... der Reiter vom Tier gefallen.'::text,'wäre'::text,'würde'::text,'fiel'::text,'Wenn der Sattel nicht fest gesessen hätte, wäre der Reiter vom Tier gefallen.'::text),
(334348,37150,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби сідло не було туго затягнуте, вершник ... зі звіра.'::text,'упав би'::text,'упав би'::text,'упав'::text,'Якби сідло не було туго затягнуте, вершник упав би зі звіра.'::text),
(334347,37150,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la silla no hubiera estado bien apretada, el jinete ... de la bestia.'::text,'se habría caído'::text,'se caería'::text,'se cayó'::text,'Si la silla no hubiera estado bien apretada, el jinete se habría caído de la bestia.'::text),
(334346,37150,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la selle n''avait pas été bien serrée, le cavalier ... de la bête.'::text,'serait tombé'::text,'tomberait'::text,'est tombé'::text,'Si la selle n''avait pas été bien serrée, le cavalier serait tombé de la bête.'::text),
(334349,37150,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eyer sıkı olmasaydı binici hayvandan ...'::text,'düşmüş olurdu'::text,'düşerdi'::text,'düştü'::text,'Eyer sıkı olmasaydı binici hayvandan düşmüş olurdu.'::text),
(334350,37150,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a nyereg nem lett volna szoros, a lovas ... a lényről.'::text,'leesett volna'::text,'leesne'::text,'leesett'::text,'Ha a nyereg nem lett volna szoros, a lovas leesett volna a lényről.'::text),
(401925,44659,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gecko ... seit 10 Sekunden in die Kamera, was über dem Zielwert liegt.'::text,'winkt'::text,'winkt'::text,'winkt'::text,'Der Gecko winkt seit 10 Sekunden in die Kamera, was über dem Zielwert liegt.'::text),
(401929,44659,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гекон уже 10 секунд ... в камеру, що перевищує цільовий показник.'::text,'махає'::text,'махає'::text,'махає'::text,'Гекон уже 10 секунд махає в камеру, що перевищує цільовий показник.'::text),
(401928,44659,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gecko ... a la cámara desde hace 10 segundos, lo cual supera el objetivo.'::text,'saluda'::text,'está saludando'::text,'saluda'::text,'El gecko saluda a la cámara desde hace 10 segundos, lo cual supera el objetivo.'::text),
(401927,44659,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gecko ... à la caméra depuis 10 secondes, ce qui dépasse l''objectif.'::text,'fait signe'::text,'fait signe'::text,'fait signe'::text,'Le gecko fait signe à la caméra depuis 10 secondes, ce qui dépasse l''objectif.'::text),
(401930,44659,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecko 10 saniyedir kameraya el ..., bu da hedefin üzerinde.'::text,'sallıyor'::text,'sallıyor'::text,'sallar'::text,'Gecko 10 saniyedir kameraya el sallıyor, bu da hedefin üzerinde.'::text),
(401931,44659,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gekkó 10 másodperce ... a kamerának, ami a célérték felett van.'::text,'integet'::text,'integet'::text,'integet'::text,'A gekkó 10 másodperce integet a kamerának, ami a célérték felett van.'::text),
(401934,44660,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gecko ... einmal mit der Hand und fing dann an zu tanzen.'::text,'winkte'::text,'winkte gerade'::text,'hat gewinkt'::text,'Der Gecko winkte einmal mit der Hand und fing dann an zu tanzen.'::text),
(401938,44660,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гекон один раз ... рукою, а потім почав танцювати.'::text,'помахав'::text,'махав'::text,'помахав'::text,'Гекон один раз помахав рукою, а потім почав танцювати.'::text),
(401937,44660,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gecko ... la mano una vez y luego se puso a bailar.'::text,'agitó'::text,'estaba agitando'::text,'ha agitado'::text,'El gecko agitó la mano una vez y luego se puso a bailar.'::text),
(401936,44660,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gecko ... de la main une fois, puis s''est mis à danser.'::text,'a fait signe'::text,'faisait signe'::text,'a fait signe'::text,'Le gecko a fait signe de la main une fois, puis s''est mis à danser.'::text),
(401939,44660,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecko bir kez el ... ve sonra dans etmeye başladı.'::text,'salladı'::text,'sallıyordu'::text,'salladı'::text,'Gecko bir kez el salladı ve sonra dans etmeye başladı.'::text),
(401940,44660,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gekkó egyszer ..., aztán táncolni kezdett.'::text,'intett'::text,'integetett'::text,'intett'::text,'A gekkó egyszer intett, aztán táncolni kezdett.'::text),
(401943,44661,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gecko ... bisher zweimal in die Kamera gewinkt.'::text,'hat'::text,'hat'::text,'winkte'::text,'Der Gecko hat bisher zweimal in die Kamera gewinkt.'::text),
(401947,44661,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гекон поки що двічі ... в камеру.'::text,'помахав'::text,'махав'::text,'помахав'::text,'Гекон поки що двічі помахав в камеру.'::text),
(401946,44661,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora el gecko ... a la cámara dos veces.'::text,'ha saludado'::text,'ha estado saludando'::text,'saludó'::text,'Hasta ahora el gecko ha saludado a la cámara dos veces.'::text),
(401945,44661,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gecko ... la caméra deux fois jusqu''ici.'::text,'a salué'::text,'saluait'::text,'a salué'::text,'Le gecko a salué la caméra deux fois jusqu''ici.'::text),
(401948,44661,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecko şimdiye kadar kameraya iki kez el ...'::text,'salladı'::text,'sallıyor'::text,'salladı'::text,'Gecko şimdiye kadar kameraya iki kez el salladı.'::text),
(401949,44661,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gekkó eddig kétszer ... a kamerának.'::text,'intett'::text,'integetett'::text,'intett'::text,'A gekkó eddig kétszer intett a kamerának.'::text),
(401952,44662,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gecko ... in die Kamera gewinkt, bevor er anfing zu tanzen.'::text,'hatte'::text,'hat'::text,'winkt'::text,'Der Gecko hatte in die Kamera gewinkt, bevor er anfing zu tanzen.'::text),
(401956,44662,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гекон ... в камеру, перш ніж почав танцювати.'::text,'помахав'::text,'помахав'::text,'махає'::text,'Гекон помахав в камеру, перш ніж почав танцювати.'::text),
(401955,44662,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gecko ... a la cámara antes de ponerse a bailar.'::text,'había saludado'::text,'ha saludado'::text,'saluda'::text,'El gecko había saludado a la cámara antes de ponerse a bailar.'::text),
(401954,44662,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gecko ... la caméra avant de se mettre à danser.'::text,'avait salué'::text,'a salué'::text,'salue'::text,'Le gecko avait salué la caméra avant de se mettre à danser.'::text),
(401957,44662,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecko dans etmeye başlamadan önce kameraya el ...'::text,'sallamıştı'::text,'salladı'::text,'sallıyor'::text,'Gecko dans etmeye başlamadan önce kameraya el sallamıştı.'::text),
(401958,44662,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gekkó ... a kamerának, mielőtt táncolni kezdett.'::text,'intett'::text,'intett'::text,'int'::text,'A gekkó intett a kamerának, mielőtt táncolni kezdett.'::text),
(401961,44663,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Gecko mit der Hand winkt, ... sich seine Hand bewegen, weil Winken Hände bewegt.'::text,'wird'::text,'würde'::text,'bewegte'::text,'Wenn der Gecko mit der Hand winkt, wird sich seine Hand bewegen, weil Winken Hände bewegt.'::text),
(401965,44663,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо гекон помахає рукою, його рука ..., бо махання рухає руками.'::text,'поворухнеться'::text,'поворухнулася б'::text,'поворухнулася'::text,'Якщо гекон помахає рукою, його рука поворухнеться, бо махання рухає руками.'::text),
(401964,44663,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el gecko agita la mano, su mano ... porque saludar mueve las manos.'::text,'se moverá'::text,'se movería'::text,'se movió'::text,'Si el gecko agita la mano, su mano se moverá porque saludar mueve las manos.'::text),
(401963,44663,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le gecko fait signe de la main, sa main ... parce que faire signe fait bouger les mains.'::text,'bougera'::text,'bougerait'::text,'a bougé'::text,'Si le gecko fait signe de la main, sa main bougera parce que faire signe fait bouger les mains.'::text),
(401966,44663,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecko el sallarsa eli ..., çünkü el sallamak elleri hareket ettirir.'::text,'hareket edecek'::text,'hareket ederdi'::text,'hareket etti'::text,'Gecko el sallarsa eli hareket edecek, çünkü el sallamak elleri hareket ettirir.'::text),
(401967,44663,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a gekkó integet a kezével, a keze ..., mert az integetés mozgatja a kezet.'::text,'mozogni fog'::text,'mozogna'::text,'mozgott'::text,'Ha a gekkó integet a kezével, a keze mozogni fog, mert az integetés mozgatja a kezet.'::text),
(401970,44664,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Gecko sprechen könnte, ... er Hallo sagen, statt zu winken.'::text,'würde'::text,'wird'::text,'sagt'::text,'Wenn der Gecko sprechen könnte, würde er Hallo sagen, statt zu winken.'::text),
(401974,44664,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби гекон умів говорити, він ... «привіт» замість того, щоб махати.'::text,'сказав би'::text,'скаже'::text,'каже'::text,'Якби гекон умів говорити, він сказав би «привіт» замість того, щоб махати.'::text),
(401973,44664,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el gecko pudiera hablar, ... «hola» en vez de saludar con la mano.'::text,'diría'::text,'dirá'::text,'dice'::text,'Si el gecko pudiera hablar, diría «hola» en vez de saludar con la mano.'::text),
(401972,44664,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le gecko pouvait parler, il ... « salut » au lieu de faire signe.'::text,'dirait'::text,'dira'::text,'dit'::text,'Si le gecko pouvait parler, il dirait « salut » au lieu de faire signe.'::text),
(401975,44664,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecko konuşabilseydi el sallamak yerine “merhaba” ...'::text,'derdi'::text,'diyecek'::text,'diyor'::text,'Gecko konuşabilseydi el sallamak yerine “merhaba” derdi.'::text),
(401976,44664,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a gekkó tudna beszélni, integetés helyett azt ..., hogy „szia”.'::text,'mondaná'::text,'mondja majd'::text,'mondja'::text,'Ha a gekkó tudna beszélni, integetés helyett azt mondaná, hogy „szia”.'::text),
(401979,44665,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich ... der Tanz des Geckos gleich gefilmt, nachdem er in die Kamera gewinkt hatte.'::text,'wurde'::text,'hat'::text,'filmt'::text,'Girl, angeblich wurde der Tanz des Geckos gleich gefilmt, nachdem er in die Kamera gewinkt hatte.'::text),
(401983,44665,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, танець гекона ... одразу після того, як він помахав у камеру.'::text,'зняли'::text,'зняв'::text,'знімає'::text,'Подруго, кажуть, танець гекона зняли одразу після того, як він помахав у камеру.'::text),
(401982,44665,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer el baile del gecko ... justo después de que saludara a la cámara.'::text,'se grabó'::text,'grabó'::text,'está grabando'::text,'Tía, al parecer el baile del gecko se grabó justo después de que saludara a la cámara.'::text),
(401981,44665,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment la danse du gecko ... juste après qu''il a salué la caméra.'::text,'a été filmée'::text,'a filmé'::text,'est en train de filmer'::text,'Meuf, apparemment la danse du gecko a été filmée juste après qu''il a salué la caméra.'::text),
(401984,44665,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, anlaşılan geckonun dansı, kameraya el salladıktan hemen sonra ...'::text,'çekilmiş'::text,'çekmiş'::text,'çekiyormuş'::text,'Kızım, anlaşılan geckonun dansı, kameraya el salladıktan hemen sonra çekilmiş.'::text),
(401985,44665,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a gekkó táncát rögtön azután ..., hogy integetett a kamerának.'::text,'vették fel'::text,'vette fel'::text,'veszi fel'::text,'Csajszi, állítólag a gekkó táncát rögtön azután vették fel, hogy integetett a kamerának.'::text),
(401988,44666,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gecko ... wie ein echter Profi in die Kamera. Echt Weltklasse.'::text,'winkte'::text,'wurde gewinkt'::text,'winkend'::text,'Der Gecko winkte wie ein echter Profi in die Kamera. Echt Weltklasse.'::text),
(401992,44666,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гекон ... в камеру, як справжній професіонал. Справді світовий рівень.'::text,'помахав'::text,'був помаханий'::text,'махаючи'::text,'Гекон помахав в камеру, як справжній професіонал. Справді світовий рівень.'::text),
(401991,44666,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gecko ... a la cámara como un auténtico profesional. De primer nivel mundial, de verdad.'::text,'saludó'::text,'fue saludado'::text,'saludando'::text,'El gecko saludó a la cámara como un auténtico profesional. De primer nivel mundial, de verdad.'::text),
(401990,44666,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gecko ... la caméra comme un vrai pro. Vraiment de classe mondiale.'::text,'a salué'::text,'a été salué'::text,'saluant'::text,'Le gecko a salué la caméra comme un vrai pro. Vraiment de classe mondiale.'::text),
(401993,44666,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecko kameraya gerçek bir profesyonel gibi el ... — gerçekten dünya çapında.'::text,'salladı'::text,'sallandı'::text,'sallayarak'::text,'Gecko kameraya gerçek bir profesyonel gibi el salladı — gerçekten dünya çapında.'::text),
(401994,44666,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gekkó úgy ... a kamerának, mint egy igazi profi. Tényleg világklasszis.'::text,'intett'::text,'intettek neki'::text,'integetve'::text,'A gekkó úgy intett a kamerának, mint egy igazi profi. Tényleg világklasszis.'::text),
(401997,44667,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er winkt, tanzt und grinst; er ... keinen offensichtlich schrecklichen Tag haben.'::text,'kann'::text,'muss'::text,'könnte'::text,'Er winkt, tanzt und grinst; er kann keinen offensichtlich schrecklichen Tag haben.'::text),
(402001,44667,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він махає, танцює і шкіриться; у нього ... бути явно жахливий день.'::text,'не може'::text,'мусить'::text,'може'::text,'Він махає, танцює і шкіриться; у нього не може бути явно жахливий день.'::text),
(402000,44667,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saluda, baila y sonríe; ... estar teniendo un día obviamente horrible.'::text,'no puede'::text,'tiene que'::text,'podría'::text,'Saluda, baila y sonríe; no puede estar teniendo un día obviamente horrible.'::text),
(401999,44667,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il fait signe, danse et sourit ; il ... passer une journée clairement horrible.'::text,'ne peut pas'::text,'doit'::text,'pourrait'::text,'Il fait signe, danse et sourit ; il ne peut pas passer une journée clairement horrible.'::text),
(402002,44667,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sallıyor, dans ediyor ve sırıtıyor; belli ki berbat bir gün geçiriyor ...'::text,'olamaz'::text,'olmalı'::text,'olabilir'::text,'El sallıyor, dans ediyor ve sırıtıyor; belli ki berbat bir gün geçiriyor olamaz.'::text),
(402003,44667,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Integet, táncol és vigyorog; ..., hogy nyilvánvalóan szörnyű napja van.'::text,'nem lehet'::text,'biztos'::text,'lehet'::text,'Integet, táncol és vigyorog; nem lehet, hogy nyilvánvalóan szörnyű napja van.'::text),
(402006,44668,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gecko, ... uns gewinkt hat, ist lowkey ikonisch, Bro.'::text,'der'::text,'was'::text,'dessen'::text,'Der Gecko, der uns gewinkt hat, ist lowkey ikonisch, Bro.'::text),
(402010,44668,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гекон, ... помахав нам, якийсь прям культовий, бро.'::text,'який'::text,'що'::text,'чий'::text,'Гекон, який помахав нам, якийсь прям культовий, бро.'::text),
(402009,44668,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gecko ... nos saludó es medio icónico, bro.'::text,'que'::text,'lo que'::text,'cuyo'::text,'El gecko que nos saludó es medio icónico, bro.'::text),
(402008,44668,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gecko ... nous a fait coucou est un peu iconique, frérot.'::text,'qui'::text,'ce qui'::text,'dont'::text,'Le gecko qui nous a fait coucou est un peu iconique, frérot.'::text),
(402011,44668,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bize el ... gecko resmen ikonik, kanka.'::text,'sallayan'::text,'sallayan'::text,'sallayanın'::text,'Bize el sallayan gecko resmen ikonik, kanka.'::text),
(402012,44668,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gekkó, ... integetett nekünk, lowkey ikonikus, tesó.'::text,'aki'::text,'ami'::text,'akinek'::text,'A gekkó, aki integetett nekünk, lowkey ikonikus, tesó.'::text),
(390315,43369,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gecko ... seit einer Minute scharfe Chilis, und jetzt ist er rot.'::text,'isst'::text,'isst'::text,'isst'::text,'Der Gecko isst seit einer Minute scharfe Chilis, und jetzt ist er rot.'::text),
(390319,43369,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гекон уже хвилину ... гострі перчики чилі, і тепер він червоний.'::text,'їсть'::text,'їсть'::text,'їсть'::text,'Гекон уже хвилину їсть гострі перчики чилі, і тепер він червоний.'::text),
(390318,43369,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gecko ... chiles picantes desde hace un minuto y ahora está rojo.'::text,'come'::text,'está comiendo'::text,'come'::text,'El gecko come chiles picantes desde hace un minuto y ahora está rojo.'::text),
(390317,43369,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gecko ... des piments forts depuis une minute, et maintenant il est rouge.'::text,'mange'::text,'mange'::text,'mange'::text,'Le gecko mange des piments forts depuis une minute, et maintenant il est rouge.'::text),
(390320,43369,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecko bir dakikadır acı biber ... ve şimdi kıpkırmızı.'::text,'yiyor'::text,'yiyor'::text,'yer'::text,'Gecko bir dakikadır acı biber yiyor ve şimdi kıpkırmızı.'::text),
(390321,43369,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gekkó egy perce ... az erős chilipaprikát, és most vörös.'::text,'eszi'::text,'eszi'::text,'eszi'::text,'A gekkó egy perce eszi az erős chilipaprikát, és most vörös.'::text),
(390324,43370,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gecko ... ins Wasserglas, nachdem er die scharfen Chilis gegessen hatte.'::text,'sprang'::text,'sprang gerade'::text,'ist gesprungen'::text,'Der Gecko sprang ins Wasserglas, nachdem er die scharfen Chilis gegessen hatte.'::text),
(390328,43370,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гекон ... у склянку з водою, після того як з''їв гострі перчики чилі.'::text,'стрибнув'::text,'стрибав'::text,'стрибнув'::text,'Гекон стрибнув у склянку з водою, після того як з''їв гострі перчики чилі.'::text),
(390327,43370,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gecko ... al vaso de agua después de comerse los chiles picantes.'::text,'saltó'::text,'estaba saltando'::text,'ha saltado'::text,'El gecko saltó al vaso de agua después de comerse los chiles picantes.'::text),
(390326,43370,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gecko ... dans le verre d''eau après avoir mangé les piments forts.'::text,'a sauté'::text,'sautait'::text,'a sauté'::text,'Le gecko a sauté dans le verre d''eau après avoir mangé les piments forts.'::text),
(390329,43370,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecko acı biberleri yedikten sonra su bardağına ...'::text,'atladı'::text,'atlıyordu'::text,'atladı'::text,'Gecko acı biberleri yedikten sonra su bardağına atladı.'::text),
(390330,43370,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gekkó ... a vizespohárba, miután megette az erős chilipaprikákat.'::text,'beugrott'::text,'ugrált'::text,'beugrott'::text,'A gekkó beugrott a vizespohárba, miután megette az erős chilipaprikákat.'::text),
(390333,43371,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gecko ... bisher zehn scharfe Chilis gegessen.'::text,'hat'::text,'hat'::text,'aß'::text,'Der Gecko hat bisher zehn scharfe Chilis gegessen.'::text),
(390337,43371,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гекон поки що ... десять гострих перчиків чилі.'::text,'з''їв'::text,'їв'::text,'з''їв'::text,'Гекон поки що з''їв десять гострих перчиків чилі.'::text),
(390336,43371,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora el gecko ... diez chiles picantes.'::text,'se ha comido'::text,'ha estado comiendo'::text,'se comió'::text,'Hasta ahora el gecko se ha comido diez chiles picantes.'::text),
(390335,43371,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gecko ... dix piments forts jusqu''ici.'::text,'a mangé'::text,'a mangé'::text,'mangea'::text,'Le gecko a mangé dix piments forts jusqu''ici.'::text),
(390338,43371,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecko şimdiye kadar on acı biber ...'::text,'yedi'::text,'yiyor'::text,'yedi'::text,'Gecko şimdiye kadar on acı biber yedi.'::text),
(390339,43371,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gekkó eddig tíz erős chilipaprikát ...'::text,'megevett'::text,'evett'::text,'evett'::text,'A gekkó eddig tíz erős chilipaprikát megevett.'::text),
(390342,43372,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, der Gecko ... die scharfen Chilis gegessen, bevor er Feuer spuckte.'::text,'hatte'::text,'hat'::text,'isst'::text,'Bestie, ich hab gehört, der Gecko hatte die scharfen Chilis gegessen, bevor er Feuer spuckte.'::text),
(390346,43372,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що гекон ... гострі перчики чилі, перш ніж почав дихати вогнем.'::text,'з''їв'::text,'з''їв'::text,'їсть'::text,'Подруго, я чула, що гекон з''їв гострі перчики чилі, перш ніж почав дихати вогнем.'::text),
(390345,43372,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, he oído que el gecko ... los chiles picantes antes de echar fuego por la boca.'::text,'se había comido'::text,'se ha comido'::text,'se come'::text,'Amiga, he oído que el gecko se había comido los chiles picantes antes de echar fuego por la boca.'::text),
(390344,43372,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire que le gecko ... les piments forts avant de cracher du feu.'::text,'avait mangé'::text,'a mangé'::text,'mange'::text,'Ma belle, j''ai entendu dire que le gecko avait mangé les piments forts avant de cracher du feu.'::text),
(390347,43372,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, duydum ki gecko ateş püskürtmeden önce acı biberleri ...'::text,'yemişti'::text,'yedi'::text,'yiyor'::text,'Kankam, duydum ki gecko ateş püskürtmeden önce acı biberleri yemişti.'::text),
(390348,43372,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy a gekkó ... az erős chilipaprikákat, mielőtt tüzet okádott.'::text,'megette'::text,'megette'::text,'eszi'::text,'Csajszi, azt hallottam, hogy a gekkó megette az erős chilipaprikákat, mielőtt tüzet okádott.'::text),
(390351,43373,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ... der Gecko morgen um diese Zeit wieder scharfes Essen essen.'::text,'wird'::text,'wird'::text,'isst'::text,'Hör zu, angeblich wird der Gecko morgen um diese Zeit wieder scharfes Essen essen.'::text),
(390355,43373,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, завтра в цей час гекон знову ... гостру їжу.'::text,'їстиме'::text,'з''їсть'::text,'їсть'::text,'Слухай, кажуть, завтра в цей час гекон знову їстиме гостру їжу.'::text),
(390354,43373,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer mañana a esta hora el gecko ... comida picante otra vez.'::text,'estará comiendo'::text,'comerá'::text,'come'::text,'Oye, al parecer mañana a esta hora el gecko estará comiendo comida picante otra vez.'::text),
(390353,43373,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment demain à la même heure le gecko ... de nouveau des plats épicés.'::text,'sera en train de manger'::text,'mangera'::text,'mange'::text,'Écoute, apparemment demain à la même heure le gecko sera en train de manger de nouveau des plats épicés.'::text),
(390356,43373,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anlaşılan yarın bu saatlerde gecko yine acı yemek ...'::text,'yiyor olacakmış'::text,'yiyecekmiş'::text,'yiyormuş'::text,'Dinle, anlaşılan yarın bu saatlerde gecko yine acı yemek yiyor olacakmış.'::text),
(390357,43373,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag holnap ilyenkor a gekkó megint csípős ételt ...'::text,'fog enni'::text,'eszik majd'::text,'eszik'::text,'Figyelj, állítólag holnap ilyenkor a gekkó megint csípős ételt fog enni.'::text),
(390360,43374,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gecko sagte, die Chilis ... überhaupt nicht scharf. Offensichtlich wahr.'::text,'seien'::text,'sei'::text,'hätten'::text,'Der Gecko sagte, die Chilis seien überhaupt nicht scharf. Offensichtlich wahr.'::text),
(390364,43374,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гекон сказав, що перчики ... зовсім не гострі. Очевидно, правда.'::text,'були'::text,'був'::text,'мають'::text,'Гекон сказав, що перчики були зовсім не гострі. Очевидно, правда.'::text),
(390363,43374,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gecko dijo que los chiles no ... nada picantes. Obviamente cierto.'::text,'eran'::text,'era'::text,'tenían'::text,'El gecko dijo que los chiles no eran nada picantes. Obviamente cierto.'::text),
(390362,43374,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gecko a dit que les piments ... pas du tout forts. Évidemment vrai.'::text,'n''étaient'::text,'n''était'::text,'n''avaient'::text,'Le gecko a dit que les piments n''étaient pas du tout forts. Évidemment vrai.'::text),
(390365,43374,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecko biberlerin hiç acı ... söyledi. Belli ki doğru.'::text,'olmadığını'::text,'olmadığını'::text,'olmadığını'::text,'Gecko biberlerin hiç acı olmadığını söyledi. Belli ki doğru.'::text),
(390366,43374,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gekkó azt mondta, hogy a paprikák egyáltalán nem ... csípősek. Nyilván igaz.'::text,'voltak'::text,'volt'::text,'vannak'::text,'A gekkó azt mondta, hogy a paprikák egyáltalán nem voltak csípősek. Nyilván igaz.'::text),
(390369,43375,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gecko ... früher scharfes Essen, aber jetzt liebt er es eindeutig.'::text,'hasste'::text,'hasste'::text,'war es gewohnt zu hassen'::text,'Der Gecko hasste früher scharfes Essen, aber jetzt liebt er es eindeutig.'::text),
(390373,43375,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гекон раніше ... гостру їжу, але тепер явно її обожнює.'::text,'ненавидів'::text,'ненавидів би'::text,'звик ненавидіти'::text,'Гекон раніше ненавидів гостру їжу, але тепер явно її обожнює.'::text),
(390372,43375,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gecko ... odiar la comida picante, pero ahora está claro que le encanta.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'El gecko solía odiar la comida picante, pero ahora está claro que le encanta.'::text),
(390371,43375,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gecko ... la nourriture épicée, mais maintenant il l''adore clairement.'::text,'détestait'::text,'détesterait'::text,'avait l''habitude de détester'::text,'Le gecko détestait la nourriture épicée, mais maintenant il l''adore clairement.'::text),
(390374,43375,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecko eskiden acı yemekten ... ama şimdi belli ki bayılıyor.'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkındı'::text,'Gecko eskiden acı yemekten nefret ederdi ama şimdi belli ki bayılıyor.'::text),
(390375,43375,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gekkó régen ... a csípős ételt, de most nyilván imádja.'::text,'utálta'::text,'utálta volna'::text,'hozzá volt szokva, hogy utálja'::text,'A gekkó régen utálta a csípős ételt, de most nyilván imádja.'::text),
(390378,43376,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Gecko hörte nicht auf, scharfe Chilis zu ..., das ist schon krass irre.'::text,'essen'::text,'essen'::text,'essen'::text,'Bro, der Gecko hörte nicht auf, scharfe Chilis zu essen, das ist schon krass irre.'::text),
(390382,43376,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, той гекон усе продовжував ... гострі перчики чилі, це якась жесть.'::text,'їсти'::text,'їсти'::text,'їсти'::text,'Бро, той гекон усе продовжував їсти гострі перчики чилі, це якась жесть.'::text),
(390381,43376,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ese gecko siguió ... chiles picantes, está medio loco.'::text,'comiendo'::text,'comer'::text,'comer'::text,'Bro, ese gecko siguió comiendo chiles picantes, está medio loco.'::text),
(390380,43376,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ce gecko a continué à ... des piments forts, il est un peu barré.'::text,'manger'::text,'manger'::text,'manger'::text,'Frérot, ce gecko a continué à manger des piments forts, il est un peu barré.'::text),
(390383,43376,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o gecko acı biberleri ... durdu, biraz kafayı yemiş.'::text,'yiyip'::text,'yemek'::text,'ye'::text,'Kanka, o gecko acı biberleri yiyip durdu, biraz kafayı yemiş.'::text),
(390384,43376,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a gekkó csak ... az erős chiliket, kicsit elborult.'::text,'ette tovább'::text,'enni'::text,'enni'::text,'Tesó, az a gekkó csak ette tovább az erős chiliket, kicsit elborult.'::text),
(390396,43378,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gecko ... 12 scharfe Chilis gegessen, bevor das Meeting anfing.'::text,'hatte'::text,'hat'::text,'isst'::text,'Der Gecko hatte 12 scharfe Chilis gegessen, bevor das Meeting anfing.'::text),
(390400,43378,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гекон ... 12 гострих перчиків чилі до початку наради.'::text,'з''їв'::text,'з''їв'::text,'їсть'::text,'Гекон з''їв 12 гострих перчиків чилі до початку наради.'::text),
(390399,43378,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gecko ... 12 chiles picantes antes de que empezara la reunión.'::text,'se había comido'::text,'se ha comido'::text,'se come'::text,'El gecko se había comido 12 chiles picantes antes de que empezara la reunión.'::text),
(390398,43378,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gecko ... 12 piments forts avant le début de la réunion.'::text,'avait mangé'::text,'a mangé'::text,'mange'::text,'Le gecko avait mangé 12 piments forts avant le début de la réunion.'::text),
(390401,43378,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecko toplantı başlamadan önce 12 acı biber ...'::text,'yemişti'::text,'yedi'::text,'yiyor'::text,'Gecko toplantı başlamadan önce 12 acı biber yemişti.'::text),
(390402,43378,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gekkó ... 12 erős chilipaprikát, mielőtt elkezdődött a megbeszélés.'::text,'megevett'::text,'megevett'::text,'megeszik'::text,'A gekkó megevett 12 erős chilipaprikát, mielőtt elkezdődött a megbeszélés.'::text),
(361551,40173,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Krokodil ... den Dinosaurier gerade unter Wasser, als es plötzlich aus dem Fluss schoss.'::text,'jagte'::text,'jagte'::text,'hat gejagt'::text,'Das Krokodil jagte den Dinosaurier gerade unter Wasser, als es plötzlich aus dem Fluss schoss.'::text),
(361555,40173,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Крокодил ... на динозавра під водою, коли раптом вискочив із річки.'::text,'полював'::text,'вполював'::text,'вполював'::text,'Крокодил полював на динозавра під водою, коли раптом вискочив із річки.'::text),
(361554,40173,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cocodrilo ... al dinosaurio bajo el agua cuando de repente salió disparado del río.'::text,'estaba cazando'::text,'cazó'::text,'ha cazado'::text,'El cocodrilo estaba cazando al dinosaurio bajo el agua cuando de repente salió disparado del río.'::text),
(361553,40173,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le crocodile ... le dinosaure sous l''eau quand il a soudain jailli de la rivière.'::text,'chassait'::text,'a chassé'::text,'a chassé'::text,'Le crocodile chassait le dinosaure sous l''eau quand il a soudain jailli de la rivière.'::text),
(361556,40173,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Timsah dinozoru su altında ... ki aniden nehirden fırladı.'::text,'avlıyordu'::text,'avladı'::text,'avladı'::text,'Timsah dinozoru su altında avlıyordu ki aniden nehirden fırladı.'::text),
(361557,40173,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A krokodil a víz alatt ... a dinoszauruszra, amikor hirtelen kitört a folyóból.'::text,'vadászott'::text,'vadászott'::text,'vadászott'::text,'A krokodil a víz alatt vadászott a dinoszauruszra, amikor hirtelen kitört a folyóból.'::text),
(361560,40174,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig ein entspannter Tag: Die Krokodile ... diesen Dinosaurier schon den ganzen Vormittag.'::text,'jagen'::text,'jagten'::text,'jagen'::text,'Eindeutig ein entspannter Tag: Die Krokodile jagen diesen Dinosaurier schon den ganzen Vormittag.'::text),
(361564,40174,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно розслабний день: крокодили ... на цього динозавра весь ранок.'::text,'полюють'::text,'полювали'::text,'полюють'::text,'Явно розслабний день: крокодили полюють на цього динозавра весь ранок.'::text),
(361563,40174,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un día relajado, claramente: los cocodrilos ... a este dinosaurio toda la mañana.'::text,'llevan cazando'::text,'cazaron'::text,'están cazando'::text,'Un día relajado, claramente: los cocodrilos llevan cazando a este dinosaurio toda la mañana.'::text),
(361562,40174,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une journée tranquille, clairement : les crocodiles ... ce dinosaure toute la matinée.'::text,'chassent'::text,'ont chassé'::text,'chassent'::text,'Une journée tranquille, clairement : les crocodiles chassent ce dinosaure toute la matinée.'::text),
(361565,40174,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki rahat bir gün: timsahlar bütün sabah bu dinozoru ...'::text,'avlıyor'::text,'avladı'::text,'avlıyor'::text,'Belli ki rahat bir gün: timsahlar bütün sabah bu dinozoru avlıyor.'::text),
(361566,40174,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván pihentető nap: a krokodilok egész délelőtt ... erre a dinoszauruszra.'::text,'vadásznak'::text,'vadásztak'::text,'vadásznak'::text,'Nyilván pihentető nap: a krokodilok egész délelőtt vadásznak erre a dinoszauruszra.'::text),
(361569,40175,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, als der Dino hochgeschaut hat, ... das Kroko ihn schon erlegt, echt.'::text,'hatte'::text,'hat'::text,'erlegt'::text,'Alter, als der Dino hochgeschaut hat, hatte das Kroko ihn schon erlegt, echt.'::text),
(361573,40175,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, поки дино підняв голову, той кроко його вже ..., реально.'::text,'вполював'::text,'вполював'::text,'полює'::text,'Чувак, поки дино підняв голову, той кроко його вже вполював, реально.'::text),
(361572,40175,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, para cuando el dino levantó la cabeza, ese coco ya lo ..., en serio.'::text,'había cazado'::text,'ha cazado'::text,'caza'::text,'Tío, para cuando el dino levantó la cabeza, ese coco ya lo había cazado, en serio.'::text),
(361571,40175,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, le temps que le dino lève la tête, ce croco ... déjà, grave.'::text,'l''avait chopé'::text,'l''a chopé'::text,'le chope'::text,'Mec, le temps que le dino lève la tête, ce croco l''avait chopé déjà, grave.'::text),
(361574,40175,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dino başını kaldırdığında o timsah onu çoktan ..., cidden.'::text,'avlamıştı'::text,'avladı'::text,'avlıyor'::text,'Kanka, dino başını kaldırdığında o timsah onu çoktan avlamıştı, cidden.'::text),
(361575,40175,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mire a dínó felnézett, az a kroki már ..., komolyan.'::text,'elkapta'::text,'elkapta'::text,'elkapja'::text,'Tesó, mire a dínó felnézett, az a kroki már elkapta, komolyan.'::text),
(361578,40176,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, wenn der Dino da weiter trinkt, ... die Krokos ihn, ohne Witz.'::text,'jagen'::text,'jagten'::text,'jagten'::text,'Nee Bro, wenn der Dino da weiter trinkt, jagen die Krokos ihn, ohne Witz.'::text),
(361582,40176,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ні, бро, якщо той дино й далі питиме там, крокодили ... на нього, без жартів.'::text,'полюватимуть'::text,'полювали б'::text,'полювали'::text,'Та ні, бро, якщо той дино й далі питиме там, крокодили полюватимуть на нього, без жартів.'::text),
(361581,40176,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, bro, si ese dino sigue bebiendo ahí, los cocos lo ..., en serio.'::text,'cazarán'::text,'cazarían'::text,'cazaron'::text,'Qué va, bro, si ese dino sigue bebiendo ahí, los cocos lo cazarán, en serio.'::text),
(361580,40176,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frérot, si ce dino continue de boire là, les crocos ..., sans mentir.'::text,'le chasseront'::text,'le chasseraient'::text,'l''ont chassé'::text,'Nan frérot, si ce dino continue de boire là, les crocos le chasseront, sans mentir.'::text),
(361583,40176,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, o dino orada içmeye devam ederse timsahlar onu ..., yalan yok.'::text,'avlayacak'::text,'avlardı'::text,'avladı'::text,'Yok kanka, o dino orada içmeye devam ederse timsahlar onu avlayacak, yalan yok.'::text),
(361584,40176,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha az a dínó ott iszik tovább, a krokik ... rá, komolyan.'::text,'vadászni fognak'::text,'vadásznának'::text,'vadásztak'::text,'Tesó, ha az a dínó ott iszik tovább, a krokik vadászni fognak rá, komolyan.'::text),
(361587,40177,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die 5 Krokodile als ein Team jagen würden, ... sie ihr Ziel an einem Tag.'::text,'erreichten'::text,'erreichen'::text,'erreichten'::text,'Wenn die 5 Krokodile als ein Team jagen würden, erreichten sie ihr Ziel an einem Tag.'::text),
