(356655,39629,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Was für ein Tag! Der Corgi war total begeistert von den freundlichen Polizisten, und ...'::text,'der Schäferhund auch.'::text,'der Schäferhund auch.'::text,'der Schäferhund auch nicht.'::text,'Was für ein Tag! Der Corgi war total begeistert von den freundlichen Polizisten, und der Schäferhund auch.'::text),
(356659,39629,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оце день! Коргі був у повному захваті від привітних поліцейських, і ...'::text,'вівчарка теж.'::text,'вівчарка теж.'::text,'вівчарка теж ні.'::text,'Оце день! Коргі був у повному захваті від привітних поліцейських, і вівчарка теж.'::text),
(356658,39629,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Menudo día! El corgi estaba encantadísimo con los agentes tan amables, y ...'::text,'el pastor también.'::text,'el pastor también.'::text,'el pastor tampoco.'::text,'¡Menudo día! El corgi estaba encantadísimo con los agentes tan amables, y el pastor también.'::text),
(356657,39629,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quelle journée ! Le corgi était complètement ravi par les policiers sympas, et ...'::text,'le berger aussi.'::text,'le berger aussi.'::text,'le berger non plus.'::text,'Quelle journée ! Le corgi était complètement ravi par les policiers sympas, et le berger aussi.'::text),
(356660,39629,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne gün ama! Korgi güler yüzlü polislere bayılmıştı, ve ...'::text,'çoban köpeği de öyle.'::text,'çoban köpeği de öyle.'::text,'çoban köpeği de değildi.'::text,'Ne gün ama! Korgi güler yüzlü polislere bayılmıştı, ve çoban köpeği de öyle.'::text),
(356661,39629,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Micsoda nap! A corgi teljesen el volt ragadtatva a kedves rendőröktől, és ...'::text,'a pásztorkutya is.'::text,'a pásztorkutya is.'::text,'a pásztorkutya sem.'::text,'Micsoda nap! A corgi teljesen el volt ragadtatva a kedves rendőröktől, és a pásztorkutya is.'::text),
(356664,39630,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, er schwört, dass er bis heute Abend allen von den netten Cops ...'::text,'erzählt haben wird'::text,'erzählen wird'::text,'gerade erzählen wird'::text,'Warte, er schwört, dass er bis heute Abend allen von den netten Cops erzählt haben wird.'::text),
(356668,39630,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, він клянеться, що до вечора ... всім про привітних копів.'::text,'розкаже'::text,'розкаже'::text,'розповідатиме'::text,'Стривай, він клянеться, що до вечора розкаже всім про привітних копів.'::text),
(356667,39630,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, jura que para esta noche ya le ... a todo el mundo lo de los polis tan majos.'::text,'habrá contado'::text,'contará'::text,'estará contando'::text,'Espera, jura que para esta noche ya le habrá contado a todo el mundo lo de los polis tan majos.'::text),
(356666,39630,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, il jure que d''ici ce soir il ... à tout le monde des flics sympas.'::text,'aura parlé'::text,'parlera'::text,'sera en train de parler'::text,'Attends, il jure que d''ici ce soir il aura parlé à tout le monde des flics sympas.'::text),
(356669,39630,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, bu akşama kadar herkese güler yüzlü polisleri ... yemin ediyor.'::text,'anlatmış olacağına'::text,'anlatacağına'::text,'anlatıyor olacağına'::text,'Dur, bu akşama kadar herkese güler yüzlü polisleri anlatmış olacağına yemin ediyor.'::text),
(356670,39630,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, esküszik, hogy estére már mindenkinek ... a kedves zsarukról.'::text,'elmesélte'::text,'elmondja'::text,'mesélni fog'::text,'Várj, esküszik, hogy estére már mindenkinek elmesélte a kedves zsarukról.'::text),
(356673,39631,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Polizisten nicht so freundlich gewesen wären, ... der Mann nicht so entspannt ausgesehen.'::text,'hätte'::text,'wird'::text,'sah'::text,'Wenn die Polizisten nicht so freundlich gewesen wären, hätte der Mann nicht so entspannt ausgesehen.'::text),
(356677,39631,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби поліцейські не були такими привітними, чоловік ... таким розслабленим.'::text,'не виглядав би'::text,'не виглядатиме'::text,'не виглядав'::text,'Якби поліцейські не були такими привітними, чоловік не виглядав би таким розслабленим.'::text),
(356676,39631,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los agentes no hubieran sido tan amables, el hombre ... tan relajado.'::text,'no habría parecido'::text,'no parecerá'::text,'no pareció'::text,'Si los agentes no hubieran sido tan amables, el hombre no habría parecido tan relajado.'::text),
(356675,39631,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les policiers n''avaient pas été si sympas, l''homme ... aussi détendu.'::text,'n''aurait pas eu l''air'::text,'n''aura pas l''air'::text,'n''avait pas l''air'::text,'Si les policiers n''avaient pas été si sympas, l''homme n''aurait pas eu l''air aussi détendu.'::text),
(356678,39631,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Polisler bu kadar güler yüzlü olmasaydı adam bu kadar rahat ...'::text,'görünmezdi'::text,'görünmeyecek'::text,'görünmedi'::text,'Polisler bu kadar güler yüzlü olmasaydı adam bu kadar rahat görünmezdi.'::text),
(356679,39631,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a rendőrök nem lettek volna ilyen barátságosak, a férfi ... ilyen nyugodtnak.'::text,'nem tűnt volna'::text,'nem fog tűnni'::text,'nem tűnt'::text,'Ha a rendőrök nem lettek volna ilyen barátságosak, a férfi nem tűnt volna ilyen nyugodtnak.'::text),
(356682,39632,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann bedankte sich bei der Polizistin dafür, dass sie so freundlich zu seinen Hunden ...'::text,'war'::text,'zu sein'::text,'gewesen'::text,'Der Mann bedankte sich bei der Polizistin dafür, dass sie so freundlich zu seinen Hunden war.'::text),
(356686,39632,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік подякував поліцейській за те, що вона ... такою привітною до його собак.'::text,'була'::text,'бути'::text,'була'::text,'Чоловік подякував поліцейській за те, що вона була такою привітною до його собак.'::text),
(356685,39632,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre le dio las gracias a la agente por ... tan amable con sus perros.'::text,'ser'::text,'ser'::text,'sido'::text,'El hombre le dio las gracias a la agente por ser tan amable con sus perros.'::text),
(356684,39632,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme a remercié la policière ... si sympa avec ses chiens.'::text,'d''avoir été'::text,'d''être'::text,'été'::text,'L''homme a remercié la policière d''avoir été si sympa avec ses chiens.'::text),
(356687,39632,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam, köpeklerine karşı bu kadar dostça ... için polis kadına teşekkür etti.'::text,'olduğu'::text,'olmak'::text,'olmuş'::text,'Adam, köpeklerine karşı bu kadar dostça olduğu için polis kadına teşekkür etti.'::text),
(356688,39632,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi megköszönte a rendőrnőnek, hogy ilyen kedves ... a kutyáival.'::text,'volt'::text,'lenni'::text,'volt'::text,'A férfi megköszönte a rendőrnőnek, hogy ilyen kedves volt a kutyáival.'::text),
(356700,39634,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... schon eine Weile durch den Park geradelt, als die freundlichen Polizisten ihn anhielten.'::text,'war'::text,'ist'::text,'radelt'::text,'Der Mann war schon eine Weile durch den Park geradelt, als die freundlichen Polizisten ihn anhielten.'::text),
(356704,39634,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік уже якийсь час ... парком, коли привітні поліцейські його зупинили.'::text,'їхав на велосипеді'::text,'їде на велосипеді'::text,'їздить на велосипеді'::text,'Чоловік уже якийсь час їхав на велосипеді парком, коли привітні поліцейські його зупинили.'::text),
(356703,39634,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... un rato por el parque en bici cuando los agentes tan amables lo pararon.'::text,'había estado pedaleando'::text,'ha estado pedaleando'::text,'pedalea'::text,'El hombre había estado pedaleando un rato por el parque en bici cuando los agentes tan amables lo pararon.'::text),
(356702,39634,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... dans le parc depuis un moment quand les policiers sympas l''ont arrêté.'::text,'pédalait'::text,'pédale'::text,'pédale'::text,'L''homme pédalait dans le parc depuis un moment quand les policiers sympas l''ont arrêté.'::text),
(356705,39634,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güler yüzlü polisler onu durdurduğunda adam bir süredir parkta bisiklet ...'::text,'sürüyordu'::text,'sürüyor'::text,'sürer'::text,'Güler yüzlü polisler onu durdurduğunda adam bir süredir parkta bisiklet sürüyordu.'::text),
(356706,39634,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi már egy ideje ... a parkban, amikor a barátságos rendőrök megállították.'::text,'biciklizett'::text,'biciklizik'::text,'biciklizik'::text,'A férfi már egy ideje biciklizett a parkban, amikor a barátságos rendőrök megállították.'::text),
(356376,39598,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der arme Affe ... in einer Eishülle, als jemand kam, um ihn zu befreien. Ein Albtraum!'::text,'saß'::text,'saß'::text,'hat gesessen'::text,'Der arme Affe saß in einer Eishülle, als jemand kam, um ihn zu befreien. Ein Albtraum!'::text),
(356380,39598,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бідолашна мавпа ... всередині крижаної шкаралупи, коли хтось прийшов її звільнити. Жах!'::text,'сиділа'::text,'посиділа'::text,'сиділа'::text,'Бідолашна мавпа сиділа всередині крижаної шкаралупи, коли хтось прийшов її звільнити. Жах!'::text),
(356379,39598,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pobre mono ... dentro de una capa de hielo cuando alguien vino a liberarlo. ¡Una pesadilla!'::text,'estaba sentado'::text,'se sentó'::text,'ha estado sentado'::text,'El pobre mono estaba sentado dentro de una capa de hielo cuando alguien vino a liberarlo. ¡Una pesadilla!'::text),
(356378,39598,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pauvre singe ... dans une coquille de glace quand quelqu''un est venu le libérer. Un cauchemar !'::text,'était assis'::text,'s''est assis'::text,'a été assis'::text,'Le pauvre singe était assis dans une coquille de glace quand quelqu''un est venu le libérer. Un cauchemar !'::text),
(356381,39598,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zavallı maymun, biri onu kurtarmaya geldiğinde bir buz kabuğunun içinde ...; tam bir kâbus!'::text,'oturuyordu'::text,'oturdu'::text,'oturdu'::text,'Zavallı maymun, biri onu kurtarmaya geldiğinde bir buz kabuğunun içinde oturuyordu; tam bir kâbus!'::text),
(356382,39598,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szegény majom egy jégpáncél belsejében ..., amikor valaki eljött kiszabadítani. Rémálom!'::text,'ült'::text,'ült'::text,'ült'::text,'A szegény majom egy jégpáncél belsejében ült, amikor valaki eljött kiszabadítani. Rémálom!'::text),
(356385,39599,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser arme Affe ... seit Stunden im Eis, und niemand hat ihn bisher befreit!'::text,'sitzt'::text,'sitzt'::text,'sitzt'::text,'Dieser arme Affe sitzt seit Stunden im Eis, und niemand hat ihn bisher befreit!'::text),
(356389,39599,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця бідолашна мавпа ... в льоду вже кілька годин, і ніхто її досі не звільнив!'::text,'сидить'::text,'сидить'::text,'сидить'::text,'Ця бідолашна мавпа сидить в льоду вже кілька годин, і ніхто її досі не звільнив!'::text),
(356388,39599,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este pobre mono ... dentro del hielo desde hace horas y nadie lo ha liberado todavía!'::text,'está sentado'::text,'está sentado'::text,'se sienta'::text,'¡Este pobre mono está sentado dentro del hielo desde hace horas y nadie lo ha liberado todavía!'::text),
(356387,39599,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce pauvre singe ... dans la glace depuis des heures, et personne ne l''a encore libéré !'::text,'est assis'::text,'est assis'::text,'est assis'::text,'Ce pauvre singe est assis dans la glace depuis des heures, et personne ne l''a encore libéré !'::text),
(356390,39599,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu zavallı maymun saatlerdir buzun içinde ... ve kimse onu hâlâ kurtarmadı!'::text,'oturuyor'::text,'oturuyor'::text,'oturur'::text,'Bu zavallı maymun saatlerdir buzun içinde oturuyor ve kimse onu hâlâ kurtarmadı!'::text),
(356391,39599,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a szegény majom órák óta ... a jégben, és még senki nem szabadította ki!'::text,'ül'::text,'ül'::text,'ül'::text,'Ez a szegény majom órák óta ül a jégben, és még senki nem szabadította ki!'::text),
(356403,39601,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, er hat mir erzählt, dass er allein diese Woche drei Schneeaffen aus dem Eis ...'::text,'befreit hat'::text,'befreit hat'::text,'befreite'::text,'Rate mal, er hat mir erzählt, dass er allein diese Woche drei Schneeaffen aus dem Eis befreit hat.'::text),
(356407,39601,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, він сказав мені, що лише цього тижня ... з льоду трьох снігових мавп.'::text,'звільнив'::text,'звільняв'::text,'звільнив'::text,'Уяви, він сказав мені, що лише цього тижня звільнив з льоду трьох снігових мавп.'::text),
(356406,39601,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, me dijo que solo esta semana ... a tres macacos de las nieves del hielo.'::text,'ha liberado'::text,'ha estado liberando'::text,'liberó'::text,'Adivina qué, me dijo que solo esta semana ha liberado a tres macacos de las nieves del hielo.'::text),
(356405,39601,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, il m''a dit qu''il ... trois macaques des neiges de la glace rien que cette semaine.'::text,'a libéré'::text,'libérait'::text,'a libéré'::text,'Devine quoi, il m''a dit qu''il a libéré trois macaques des neiges de la glace rien que cette semaine.'::text),
(356408,39601,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu, bana sadece bu hafta üç kar maymununu buzdan ... söyledi.'::text,'kurtardığını'::text,'kurtardığını'::text,'kurtardığını'::text,'Bil bakalım ne oldu, bana sadece bu hafta üç kar maymununu buzdan kurtardığını söyledi.'::text),
(356409,39601,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta, hogy csak ezen a héten három havasi makákót ... ki a jégből.'::text,'szabadított'::text,'szabadítgatott'::text,'szabadított'::text,'Képzeld, azt mondta, hogy csak ezen a héten három havasi makákót szabadított ki a jégből.'::text),
(356412,39602,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... das Eis den Affen komplett bedeckt, als er kam, um ihn zu befreien.'::text,'hatte'::text,'hat'::text,'bedeckt'::text,'Okay, also angeblich hatte das Eis den Affen komplett bedeckt, als er kam, um ihn zu befreien.'::text),
(356416,39602,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, лід ... мавпу повністю, поки він прийшов її звільнити.'::text,'вкрив'::text,'вкрив'::text,'вкриває'::text,'Коротше, кажуть, лід вкрив мавпу повністю, поки він прийшов її звільнити.'::text),
(356415,39602,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer el hielo ... al mono por completo cuando él llegó para liberarlo.'::text,'había cubierto'::text,'ha cubierto'::text,'cubre'::text,'Vale, pues al parecer el hielo había cubierto al mono por completo cuando él llegó para liberarlo.'::text),
(356414,39602,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors apparemment la glace ... complètement le singe quand il est venu le libérer.'::text,'avait recouvert'::text,'a recouvert'::text,'recouvre'::text,'Bon alors apparemment la glace avait recouvert complètement le singe quand il est venu le libérer.'::text),
(356417,39602,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, anlaşılan o onu kurtarmaya geldiğinde buz maymunu tamamen ...'::text,'kaplamıştı'::text,'kapladı'::text,'kaplıyor'::text,'Tamam, anlaşılan o onu kurtarmaya geldiğinde buz maymunu tamamen kaplamıştı.'::text),
(356418,39602,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag mire eljött kiszabadítani, a jég teljesen ... a majmot.'::text,'beborította'::text,'beborította'::text,'beborítja'::text,'Szóval állítólag mire eljött kiszabadítani, a jég teljesen beborította a majmot.'::text),
(356421,39603,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du ... super vorsichtig gewesen sein, um den Affen ohne einen einzigen Kratzer zu befreien.'::text,'musst'::text,'solltest'::text,'kannst nicht'::text,'Respekt, du musst super vorsichtig gewesen sein, um den Affen ohne einen einzigen Kratzer zu befreien.'::text),
(356425,39603,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти ... дуже обережним, щоб звільнити ту мавпу без жодної подряпини.'::text,'напевно, був'::text,'мав бути'::text,'не міг бути'::text,'Респект, ти напевно, був дуже обережним, щоб звільнити ту мавпу без жодної подряпини.'::text),
(356424,39603,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, ... tener muchísimo cuidado para liberar a ese mono sin un solo rasguño.'::text,'debiste de'::text,'deberías haber'::text,'no pudiste'::text,'Respeto, debiste de tener muchísimo cuidado para liberar a ese mono sin un solo rasguño.'::text),
(356423,39603,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, tu ... être super prudent pour libérer ce singe sans une seule égratignure.'::text,'as dû'::text,'aurais dû'::text,'n''as pas pu'::text,'Respect, tu as dû être super prudent pour libérer ce singe sans une seule égratignure.'::text),
(356426,39603,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar, o maymunu tek bir çizik olmadan kurtarmak için çok dikkatli ...'::text,'davranmış olmalısın'::text,'davranmalıydın'::text,'davranmış olamazsın'::text,'Saygılar, o maymunu tek bir çizik olmadan kurtarmak için çok dikkatli davranmış olmalısın.'::text),
(356427,39603,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le a kalappal, ... nagyon óvatos voltál, hogy egyetlen karcolás nélkül szabadítottad ki azt a majmot.'::text,'biztosan'::text,'kellett volna, hogy'::text,'nem lehet, hogy'::text,'Le a kalappal, biztosan nagyon óvatos voltál, hogy egyetlen karcolás nélkül szabadítottad ki azt a majmot.'::text),
(356430,39604,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jemand musste dafür sorgen, dass das Eis ... wurde, bevor der Affe befreit werden konnte.'::text,'aufgebrochen'::text,'aufbrechen'::text,'aufzubrechen'::text,'Jemand musste dafür sorgen, dass das Eis aufgebrochen wurde, bevor der Affe befreit werden konnte.'::text),
(356434,39604,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хтось мав подбати, щоб лід був ..., перш ніж мавпу змогли звільнити.'::text,'розколотий'::text,'розколоти'::text,'розколоти'::text,'Хтось мав подбати, щоб лід був розколотий, перш ніж мавпу змогли звільнити.'::text),
(356433,39604,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alguien tuvo que hacer ... el hielo antes de poder liberar al mono.'::text,'romper'::text,'romper'::text,'romper'::text,'Alguien tuvo que hacer romper el hielo antes de poder liberar al mono.'::text),
(356432,39604,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quelqu''un a dû faire ... la glace avant de pouvoir libérer le singe.'::text,'casser'::text,'casser'::text,'casser'::text,'Quelqu''un a dû faire casser la glace avant de pouvoir libérer le singe.'::text),
(356435,39604,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maymun kurtarılmadan önce birinin buzu ... gerekiyordu.'::text,'kırdırması'::text,'kırması'::text,'kırmak'::text,'Maymun kurtarılmadan önce birinin buzu kırdırması gerekiyordu.'::text),
(356436,39604,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Valakinek ... kellett a jeget, mielőtt a majmot ki lehetett szabadítani.'::text,'feltöretnie'::text,'feltörnie'::text,'feltörni'::text,'Valakinek feltöretnie kellett a jeget, mielőtt a majmot ki lehetett szabadítani.'::text),
(356439,39605,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jetzt ist der Affe trocken, aber er wünscht sich, jemand ... ihn eine Stunde früher befreit.'::text,'hätte'::text,'hätte'::text,'würde'::text,'Jetzt ist der Affe trocken, aber er wünscht sich, jemand hätte ihn eine Stunde früher befreit.'::text),
(356443,39605,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тепер мавпа суха, але вона хотіла б, щоб хтось ... її на годину раніше.'::text,'звільнив'::text,'звільнив'::text,'звільнив'::text,'Тепер мавпа суха, але вона хотіла б, щоб хтось звільнив її на годину раніше.'::text),
(356442,39605,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora el mono está seco, pero desearía que alguien lo ... una hora antes.'::text,'hubiera liberado'::text,'liberara'::text,'liberaría'::text,'Ahora el mono está seco, pero desearía que alguien lo hubiera liberado una hora antes.'::text),
(356441,39605,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maintenant le singe est sec, mais il aurait aimé que quelqu''un l''... une heure plus tôt.'::text,'ait libéré'::text,'libère'::text,'libérerait'::text,'Maintenant le singe est sec, mais il aurait aimé que quelqu''un l''ait libéré une heure plus tôt.'::text),
(356444,39605,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maymun artık kuru ama keşke biri onu bir saat önce ... diyor.'::text,'kurtarsaydı'::text,'kurtarsa'::text,'kurtarırdı'::text,'Maymun artık kuru ama keşke biri onu bir saat önce kurtarsaydı diyor.'::text),
(356445,39605,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A majom most már száraz, de azt kívánja, bárcsak valaki egy órával korábban ...'::text,'kiszabadította volna'::text,'kiszabadította'::text,'kiszabadítaná'::text,'A majom most már száraz, de azt kívánja, bárcsak valaki egy órával korábban kiszabadította volna.'::text),
(356448,39606,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Person, ... Handschuhe gelb sind, befreit den Affen aus dem Eis.'::text,'deren'::text,'die'::text,'die'::text,'Die Person, deren Handschuhe gelb sind, befreit den Affen aus dem Eis.'::text),
(356452,39606,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Людина, ... рукавички жовті, звільняє мавпу з льоду.'::text,'чиї'::text,'яка'::text,'яка'::text,'Людина, чиї рукавички жовті, звільняє мавпу з льоду.'::text),
(356451,39606,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La persona ... guantes son amarillos libera al mono del hielo.'::text,'cuyos'::text,'que'::text,'que'::text,'La persona cuyos guantes son amarillos libera al mono del hielo.'::text),
(356450,39606,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La personne ... les gants sont jaunes libère le singe de la glace.'::text,'dont'::text,'qui'::text,'que'::text,'La personne dont les gants sont jaunes libère le singe de la glace.'::text),
(356453,39606,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eldivenleri sarı ... kişi maymunu buzdan kurtarıyor.'::text,'olan'::text,'olan'::text,'olan'::text,'Eldivenleri sarı olan kişi maymunu buzdan kurtarıyor.'::text),
(356454,39606,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a személy, ... a kesztyűje sárga, kiszabadítja a majmot a jégből.'::text,'akinek'::text,'aki'::text,'amely'::text,'Az a személy, akinek a kesztyűje sárga, kiszabadítja a majmot a jégből.'::text),
(356466,39608,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Morgen ... die Kälte den gefangenen Affen komplett eingefroren haben, wenn ihn niemand befreit!'::text,'wird'::text,'wird'::text,'friert'::text,'Bis zum Morgen wird die Kälte den gefangenen Affen komplett eingefroren haben, wenn ihn niemand befreit!'::text),
(356470,39608,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До ранку холод повністю ... мавпу в пастці, якщо хтось її не звільнить!'::text,'заморозить'::text,'заморозить'::text,'заморожує'::text,'До ранку холод повністю заморозить мавпу в пастці, якщо хтось її не звільнить!'::text),
(356469,39608,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para la mañana, el frío ... por completo al mono atrapado, a menos que alguien lo libere!'::text,'habrá congelado'::text,'congelará'::text,'congela'::text,'¡Para la mañana, el frío habrá congelado por completo al mono atrapado, a menos que alguien lo libere!'::text),
(356468,39608,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le matin, le froid ... complètement le singe piégé, à moins que quelqu''un le libère !'::text,'aura gelé'::text,'gèlera'::text,'gèle'::text,'D''ici le matin, le froid aura gelé complètement le singe piégé, à moins que quelqu''un le libère !'::text),
(356471,39608,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri onu kurtarmazsa sabaha kadar soğuk, kapana kısılmış maymunu tamamen ...!'::text,'dondurmuş olacak'::text,'donduracak'::text,'donduruyor'::text,'Biri onu kurtarmazsa sabaha kadar soğuk, kapana kısılmış maymunu tamamen dondurmuş olacak!'::text),
(356472,39608,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reggelre a hideg teljesen ... a csapdába esett majmot, hacsak valaki ki nem szabadítja!'::text,'megfagyasztja'::text,'megfagyasztja'::text,'fagyasztja'::text,'Reggelre a hideg teljesen megfagyasztja a csapdába esett majmot, hacsak valaki ki nem szabadítja!'::text),
(340599,37845,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn er den Kleiderschrank nicht verwüstet hätte, ... das Zimmer jetzt eigentlich sauber.'::text,'wäre'::text,'wäre'::text,'wird'::text,'Bro, wenn er den Kleiderschrank nicht verwüstet hätte, wäre das Zimmer jetzt eigentlich sauber.'::text),
(340603,37845,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби він не розгромив гардеробну, кімната зараз ... доволі чистою.'::text,'була б'::text,'була б'::text,'буде'::text,'Бро, якби він не розгромив гардеробну, кімната зараз була б доволі чистою.'::text),
(340602,37845,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si no hubiera destrozado el vestidor, la habitación ... bastante limpia ahora mismo.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Bro, si no hubiera destrozado el vestidor, la habitación estaría bastante limpia ahora mismo.'::text),
(340601,37845,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, s''il n''avait pas saccagé le dressing, la chambre ... plutôt propre là maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Frérot, s''il n''avait pas saccagé le dressing, la chambre serait plutôt propre là maintenant.'::text),
(340604,37845,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o dolabı dağıtmasaydı oda şu an baya temiz ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Kanka, o dolabı dağıtmasaydı oda şu an baya temiz olurdu.'::text),
(340605,37845,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha nem dúlta volna fel a gardróbot, a szoba most elég tiszta ...'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Tesó, ha nem dúlta volna fel a gardróbot, a szoba most elég tiszta lenne.'::text),
(340608,37846,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kleidung im Schrank soll an jenem Morgen von der Frau zusammengelegt ...'::text,'worden sein'::text,'werden'::text,'werdend'::text,'Die Kleidung im Schrank soll an jenem Morgen von der Frau zusammengelegt worden sein.'::text),
(340612,37846,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що одяг у гардеробній ... складений жінкою того ранку.'::text,'був'::text,'бути'::text,'будучи'::text,'Кажуть, що одяг у гардеробній був складений жінкою того ранку.'::text),
(340611,37846,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dicen que la ropa del vestidor ... doblada por la mujer esa mañana.'::text,'fue'::text,'es'::text,'siendo'::text,'Dicen que la ropa del vestidor fue doblada por la mujer esa mañana.'::text),
(340610,37846,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que les vêtements du dressing ... pliés par la femme ce matin-là.'::text,'ont été'::text,'sont'::text,'étant'::text,'On dit que les vêtements du dressing ont été pliés par la femme ce matin-là.'::text),
(340613,37846,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dolaptaki kıyafetlerin o sabah kadın tarafından katlanmış ... söyleniyor.'::text,'olduğu'::text,'olduğu'::text,'olarak'::text,'Dolaptaki kıyafetlerin o sabah kadın tarafından katlanmış olduğu söyleniyor.'::text),
(340614,37846,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag a gardróbban lévő ruhákat aznap reggel a nő ... össze.'::text,'hajtotta'::text,'hajtja'::text,'hajtva'::text,'Állítólag a gardróbban lévő ruhákat aznap reggel a nő hajtotta össze.'::text),
(340617,37847,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau warf dem Mann vor, alles aus ihrem Kleiderschrank ...'::text,'gezerrt zu haben'::text,'zu zerren'::text,'gezerrt'::text,'Die Frau warf dem Mann vor, alles aus ihrem Kleiderschrank gezerrt zu haben.'::text),
(340621,37847,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка звинуватила чоловіка в тому, що він ... все з її гардеробної.'::text,'витягнув'::text,'витягнути'::text,'витягнув'::text,'Жінка звинуватила чоловіка в тому, що він витягнув все з її гардеробної.'::text),
(340620,37847,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer acusó al hombre de ... todo de su vestidor.'::text,'sacar'::text,'sacar'::text,'sacado'::text,'La mujer acusó al hombre de sacar todo de su vestidor.'::text),
(340619,37847,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme a accusé l''homme ... tout de son dressing.'::text,'d''avoir sorti'::text,'de sortir'::text,'sorti'::text,'La femme a accusé l''homme d''avoir sorti tout de son dressing.'::text),
(340622,37847,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın, adamı dolabındaki her şeyi ... suçladı.'::text,'çıkarmakla'::text,'çıkarmak'::text,'çıkardı'::text,'Kadın, adamı dolabındaki her şeyi çıkarmakla suçladı.'::text),
(340623,37847,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő azzal vádolta a férfit, hogy mindent ... a gardróbjából.'::text,'kirángatott'::text,'kirángatni'::text,'kirángatott'::text,'A nő azzal vádolta a férfit, hogy mindent kirángatott a gardróbjából.'::text),
(340626,37848,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schrank ist voller Kleidung, also ... sie das mit dem Nichts-zum-Anziehen nicht ernst gemeint haben.'::text,'kann'::text,'muss'::text,'sollte'::text,'Der Schrank ist voller Kleidung, also kann sie das mit dem Nichts-zum-Anziehen nicht ernst gemeint haben.'::text),
(340630,37848,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гардеробна повна одягу, тож вона ... казати серйозно, що їй нічого вдягнути.'::text,'не могла'::text,'мабуть, мусила'::text,'не мала б'::text,'Гардеробна повна одягу, тож вона не могла казати серйозно, що їй нічого вдягнути.'::text),
(340629,37848,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vestidor está lleno de ropa, así que ... hablar en serio con lo de no tener nada que ponerse.'::text,'no podía'::text,'tenía que'::text,'no debería'::text,'El vestidor está lleno de ropa, así que no podía hablar en serio con lo de no tener nada que ponerse.'::text),
(340628,37848,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dressing est plein de vêtements, donc elle ... sérieuse en disant qu''elle n''avait rien à se mettre.'::text,'ne pouvait pas être'::text,'devait être'::text,'n''aurait pas dû être'::text,'Le dressing est plein de vêtements, donc elle ne pouvait pas être sérieuse en disant qu''elle n''avait rien à se mettre.'::text),
(340631,37848,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dolap kıyafet dolu, yani giyecek hiçbir şeyi olmadığını söylerken ciddi ...'::text,'olamaz'::text,'olmalı'::text,'olmamalıydı'::text,'Dolap kıyafet dolu, yani giyecek hiçbir şeyi olmadığını söylerken ciddi olamaz.'::text),
(340632,37848,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gardrób tele van ruhával, szóval ... komolyan gondolta, hogy nincs mit felvennie.'::text,'nem lehet, hogy'::text,'biztosan'::text,'nem kellett volna'::text,'A gardrób tele van ruhával, szóval nem lehet, hogy komolyan gondolta, hogy nincs mit felvennie.'::text),
(340635,37849,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht nur ... jedes Regal im Kleiderschrank, sondern stellte sich auch noch auf den Haufen.'::text,'leerte er'::text,'er leerte'::text,'er leerte'::text,'Nicht nur leerte er jedes Regal im Kleiderschrank, sondern stellte sich auch noch auf den Haufen.'::text),
(340639,37849,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не лише ... кожну полицю в гардеробній, а ще й став на купу.'::text,'спорожнив'::text,'спорожнив'::text,'спорожнив'::text,'Він не лише спорожнив кожну полицю в гардеробній, а ще й став на купу.'::text),
(340638,37849,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No solo ... todos los estantes del vestidor, sino que además se subió al montón.'::text,'vació'::text,'vació'::text,'vació'::text,'No solo vació todos los estantes del vestidor, sino que además se subió al montón.'::text),
(340637,37849,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non seulement ... chaque étagère du dressing, mais il est aussi monté sur la pile.'::text,'a-t-il vidé'::text,'il a vidé'::text,'il a bien vidé'::text,'Non seulement a-t-il vidé chaque étagère du dressing, mais il est aussi monté sur la pile.'::text),
(340640,37849,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dolaptaki her rafı ... kalmadı, bir de yığının üstüne çıktı.'::text,'boşaltmakla'::text,'boşaltmakla'::text,'boşaltmakla'::text,'Dolaptaki her rafı boşaltmakla kalmadı, bir de yığının üstüne çıktı.'::text),
(340641,37849,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nemcsak ... a gardrób összes polcát, hanem még a kupacra is ráállt.'::text,'kiürítette'::text,'kiürítette'::text,'kiürítette'::text,'Nemcsak kiürítette a gardrób összes polcát, hanem még a kupacra is ráállt.'::text),
(340644,37850,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also, angeblich hat sie ihn den ganzen Kleiderschrank für ein Outfit ... lassen.'::text,'ausräumen'::text,'auszuräumen'::text,'ausgeräumt'::text,'Okay, also, angeblich hat sie ihn den ganzen Kleiderschrank für ein Outfit ausräumen lassen.'::text),
(340648,37850,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, вона змусила його ... всю гардеробну заради одного образу.'::text,'спорожнити'::text,'спорожнити'::text,'спорожнив'::text,'Коротше, кажуть, вона змусила його спорожнити всю гардеробну заради одного образу.'::text),
(340647,37850,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer le hizo ... todo el vestidor por un solo conjunto.'::text,'vaciar'::text,'vaciar'::text,'vaciado'::text,'Vale, pues al parecer le hizo vaciar todo el vestidor por un solo conjunto.'::text),
(340646,37850,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment elle lui a fait ... tout le dressing pour une seule tenue.'::text,'vider'::text,'vider'::text,'vidé'::text,'Bon alors, apparemment elle lui a fait vider tout le dressing pour une seule tenue.'::text),
(340649,37850,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, anlaşılan tek bir kombin için ona bütün dolabı ...'::text,'boşalttırmış'::text,'boşaltmak'::text,'boşalttı'::text,'Tamam, anlaşılan tek bir kombin için ona bütün dolabı boşalttırmış.'::text),
(340650,37850,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag ... vele az egész gardróbot egyetlen szett miatt.'::text,'kiüríttette'::text,'kiüríteni'::text,'kiürítette'::text,'Szóval állítólag kiüríttette vele az egész gardróbot egyetlen szett miatt.'::text),
(340653,37851,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ich wünschte, mein Kleiderschrank ... so stylisch wie deiner.'::text,'wäre'::text,'ist'::text,'wird'::text,'Ehrlich, ich wünschte, mein Kleiderschrank wäre so stylisch wie deiner.'::text),
(340657,37851,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, хотів би я, щоб моя гардеробна ... такою ж стильною, як твоя.'::text,'була'::text,'є'::text,'буде'::text,'Чесно, хотів би я, щоб моя гардеробна була такою ж стильною, як твоя.'::text),
(340656,37851,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ojalá mi armario ... tan estiloso como el tuyo.'::text,'fuera'::text,'es'::text,'será'::text,'Sinceramente, ojalá mi armario fuera tan estiloso como el tuyo.'::text),
(340655,37851,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, j''aimerais que mon dressing ... aussi stylé que le tien.'::text,'soit'::text,'est'::text,'sera'::text,'Franchement, j''aimerais que mon dressing soit aussi stylé que le tien.'::text),
(340658,37851,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası keşke benim dolabım da seninki kadar şık ...'::text,'olsa'::text,NULL::text,'olacak'::text,'Açıkçası keşke benim dolabım da seninki kadar şık olsa.'::text),
(340659,37851,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, bárcsak az én gardróbom is olyan stílusos ..., mint a tiéd.'::text,'lenne'::text,NULL::text,'lesz'::text,'Őszintén, bárcsak az én gardróbom is olyan stílusos lenne, mint a tiéd.'::text),
(340662,37852,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dein Kleiderschrank, ... Regale Pullis in allen Farben tragen, ist ikonisch.'::text,'dessen'::text,'der'::text,'der'::text,'Dein Kleiderschrank, dessen Regale Pullis in allen Farben tragen, ist ikonisch.'::text),
(340666,37852,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твоя гардеробна, ... полиці ховають светри всіх кольорів, просто культова.'::text,'чиї'::text,'яка'::text,'що'::text,'Твоя гардеробна, чиї полиці ховають светри всіх кольорів, просто культова.'::text),
(340665,37852,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu vestidor, ... estantes guardan jerséis de todos los colores, es icónico.'::text,'cuyos'::text,'que'::text,'que'::text,'Tu vestidor, cuyos estantes guardan jerséis de todos los colores, es icónico.'::text),
(340664,37852,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ton dressing, ... les étagères contiennent des pulls de toutes les couleurs, est iconique.'::text,'dont'::text,'qui'::text,'que'::text,'Ton dressing, dont les étagères contiennent des pulls de toutes les couleurs, est iconique.'::text),
(340667,37852,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rafları her renkten kazakla dolu ... dolabın efsane.'::text,'olan'::text,'olan'::text,'olan'::text,'Rafları her renkten kazakla dolu olan dolabın efsane.'::text),
(340668,37852,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gardróbod, ... polcain minden színű pulóver van, ikonikus.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A gardróbod, amelynek a polcain minden színű pulóver van, ikonikus.'::text),
(340671,37853,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat ... auf dem Boden des Kleiderschranks hinterlassen. Nur ein kleines Chaos, echt.'::text,'einen Berg Klamotten'::text,'den Berg Klamotten'::text,'Berg Klamotten'::text,'Er hat einen Berg Klamotten auf dem Boden des Kleiderschranks hinterlassen. Nur ein kleines Chaos, echt.'::text),
(340675,37853,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він залишив ... на підлозі гардеробної. Невеликий безлад, справді.'::text,'гору одягу'::text,'гору одягу'::text,'гору одягу'::text,'Він залишив гору одягу на підлозі гардеробної. Невеликий безлад, справді.'::text),
(340674,37853,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dejó ... en el suelo del vestidor. Un desorden mínimo, la verdad.'::text,'una montaña de ropa'::text,'la montaña de ropa'::text,'montaña de ropa'::text,'Dejó una montaña de ropa en el suelo del vestidor. Un desorden mínimo, la verdad.'::text),
(340673,37853,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a laissé ... par terre dans le dressing. Un petit désordre, vraiment.'::text,'une montagne de vêtements'::text,'la montagne de vêtements'::text,'montagne de vêtements'::text,'Il a laissé une montagne de vêtements par terre dans le dressing. Un petit désordre, vraiment.'::text),
(340676,37853,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dolabın zemininde ... bıraktı. Ufak bir dağınıklık, gerçekten.'::text,'bir kıyafet dağı'::text,'kıyafet dağını'::text,'kıyafet dağı'::text,'Dolabın zemininde bir kıyafet dağı bıraktı. Ufak bir dağınıklık, gerçekten.'::text),
(340677,37853,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hagyott a gardrób padlóján. Apró rendetlenség, tényleg.'::text,'Egy hegynyi ruhát'::text,'A hegynyi ruhát'::text,'Hegynyi ruhát'::text,'Egy hegynyi ruhát hagyott a gardrób padlóján. Apró rendetlenség, tényleg.'::text),
(340680,37854,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat den ganzen Kleiderschrank ausgeräumt, ... ein einziges T-Shirt zu finden. Makellose Strategie.'::text,'um'::text,'damit'::text,'falls'::text,'Er hat den ganzen Kleiderschrank ausgeräumt, um ein einziges T-Shirt zu finden. Makellose Strategie.'::text),
(340684,37854,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він спорожнив усю гардеробну, ... знайти одну-єдину футболку. Бездоганна стратегія.'::text,'щоб'::text,'аби'::text,'на випадок, якщо'::text,'Він спорожнив усю гардеробну, щоб знайти одну-єдину футболку. Бездоганна стратегія.'::text),
(340683,37854,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vació todo el vestidor ... encontrar una sola camiseta. Estrategia impecable.'::text,'para'::text,'para que'::text,'por si'::text,'Vació todo el vestidor para encontrar una sola camiseta. Estrategia impecable.'::text),
(340682,37854,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a vidé tout le dressing ... trouver un seul t-shirt. Stratégie impeccable.'::text,'afin de'::text,'pour que'::text,'au cas où'::text,'Il a vidé tout le dressing afin de trouver un seul t-shirt. Stratégie impeccable.'::text),
(340685,37854,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tek bir tişört ... bütün dolabı boşalttı. Kusursuz strateji.'::text,'bulmak için'::text,'bulsun diye'::text,'bulursa diye'::text,'Tek bir tişört bulmak için bütün dolabı boşalttı. Kusursuz strateji.'::text),
(340686,37854,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kiürítette az egész gardróbot, ... találjon egyetlen pólót. Hibátlan stratégia.'::text,'hogy'::text,'azért, hogy'::text,'arra az esetre, ha'::text,'Kiürítette az egész gardróbot, hogy találjon egyetlen pólót. Hibátlan stratégia.'::text),
(338655,37629,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Sonne ... gerade hinter dem fernen Ufer unter, als der Junge seine Angel auswarf.'::text,'ging'::text,'geht'::text,'ist'::text,'Die Sonne ging gerade hinter dem fernen Ufer unter, als der Junge seine Angel auswarf.'::text),
(338659,37629,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сонце ... за далеким берегом, коли хлопець закинув вудку.'::text,'сідало'::text,'сідає'::text,'сіло'::text,'Сонце сідало за далеким берегом, коли хлопець закинув вудку.'::text),
(338658,37629,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sol ... tras la orilla lejana cuando el chico lanzó el sedal.'::text,'se estaba poniendo'::text,'se pone'::text,'se ha puesto'::text,'El sol se estaba poniendo tras la orilla lejana cuando el chico lanzó el sedal.'::text),
(338657,37629,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le soleil ... derrière la rive lointaine quand le garçon a lancé sa ligne.'::text,'se couchait'::text,'se couche'::text,'s''est couché'::text,'Le soleil se couchait derrière la rive lointaine quand le garçon a lancé sa ligne.'::text),
(338660,37629,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk oltasını attığında güneş uzaktaki kıyının ardında ...'::text,'batıyordu'::text,'batar'::text,'battı'::text,'Çocuk oltasını attığında güneş uzaktaki kıyının ardında batıyordu.'::text),
(338661,37629,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nap épp ... a túlsó part mögött, amikor a fiú bedobta a zsinórt.'::text,'lemenőben volt'::text,'lemegy'::text,'lement'::text,'A nap épp lemenőben volt a túlsó part mögött, amikor a fiú bedobta a zsinórt.'::text),
(338664,37630,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge ... seit dem späten Nachmittag seine Angel in den See aus.'::text,'wirft'::text,'wirft'::text,'wirft'::text,'Der Junge wirft seit dem späten Nachmittag seine Angel in den See aus.'::text),
(338668,37630,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець ... вудку в озеро від пізнього пообіддя.'::text,'закидає'::text,'закидає'::text,'закидає'::text,'Хлопець закидає вудку в озеро від пізнього пообіддя.'::text),
(338667,37630,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico ... el sedal al lago desde última hora de la tarde.'::text,'lanza'::text,'está lanzando'::text,'lanza'::text,'El chico lanza el sedal al lago desde última hora de la tarde.'::text),
(338666,37630,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon ... sa ligne dans le lac depuis la fin d''après-midi.'::text,'lance'::text,'lance'::text,'lance'::text,'Le garçon lance sa ligne dans le lac depuis la fin d''après-midi.'::text),
(338669,37630,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk öğleden sonranın geç saatlerinden beri göle olta ...'::text,'atıyor'::text,'atıyor'::text,'atar'::text,'Çocuk öğleden sonranın geç saatlerinden beri göle olta atıyor.'::text),
(338670,37630,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú késő délután óta ... a zsinórt a tóba.'::text,'dobálja'::text,'dobálja'::text,'dobja'::text,'A fiú késő délután óta dobálja a zsinórt a tóba.'::text),
(338673,37631,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge ... die Schnur weit hinaus und sah dann zu, wie sie sich legte.'::text,'warf'::text,'warf gerade'::text,'hat geworfen'::text,'Der Junge warf die Schnur weit hinaus und sah dann zu, wie sie sich legte.'::text),
(338677,37631,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець ... волосінь далеко і потім стояв, дивлячись, як вона осідає.'::text,'закинув'::text,'закидав'::text,'закинув'::text,'Хлопець закинув волосінь далеко і потім стояв, дивлячись, як вона осідає.'::text),
(338676,37631,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico ... el sedal muy lejos y luego se quedó mirando cómo se asentaba.'::text,'lanzó'::text,'estaba lanzando'::text,'ha lanzado'::text,'El chico lanzó el sedal muy lejos y luego se quedó mirando cómo se asentaba.'::text),
(338675,37631,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon ... sa ligne loin, puis il est resté à la regarder se poser.'::text,'a lancé'::text,'lançait'::text,'a lancé'::text,'Le garçon a lancé sa ligne loin, puis il est resté à la regarder se poser.'::text),
(338678,37631,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk misinayı uzağa ... ve sonra suya oturmasını izleyerek durdu.'::text,'attı'::text,'atıyordu'::text,'attı'::text,'Çocuk misinayı uzağa attı ve sonra suya oturmasını izleyerek durdu.'::text),
(338679,37631,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú messzire ... a zsinórt, aztán állt, és nézte, ahogy megállapodik a vízen.'::text,'bedobta'::text,'dobta'::text,'bedobta'::text,'A fiú messzire bedobta a zsinórt, aztán állt, és nézte, ahogy megállapodik a vízen.'::text),
(338682,37632,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Individuum ... seine Angel heute Abend ungefähr zwanzigmal ausgeworfen.'::text,'hat'::text,'hat'::text,'wirft'::text,'Das Individuum hat seine Angel heute Abend ungefähr zwanzigmal ausgeworfen.'::text),
(338686,37632,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Індивід цього вечора ... вудку приблизно двадцять разів.'::text,'закинув'::text,'закидав'::text,'закидає'::text,'Індивід цього вечора закинув вудку приблизно двадцять разів.'::text),
(338685,37632,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El individuo ... el sedal aproximadamente veinte veces esta tarde.'::text,'ha lanzado'::text,'ha estado lanzando'::text,'lanza'::text,'El individuo ha lanzado el sedal aproximadamente veinte veces esta tarde.'::text),
(338684,37632,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''individu ... sa ligne environ vingt fois ce soir.'::text,'a lancé'::text,'a lancé'::text,'lance'::text,'L''individu a lancé sa ligne environ vingt fois ce soir.'::text),
(338687,37632,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birey bu akşam oltasını yaklaşık yirmi kez ...'::text,'attı'::text,'atıyor'::text,'atar'::text,'Birey bu akşam oltasını yaklaşık yirmi kez attı.'::text),
(338688,37632,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyed ma este nagyjából hússzor ... be a zsinórt.'::text,'dobta'::text,'dobálta'::text,'dobja'::text,'Az egyed ma este nagyjából hússzor dobta be a zsinórt.'::text),
(338691,37633,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Sonnenuntergang ... der Junge seine Angel fünfzigmal ausgeworfen. Die Fische waren natürlich schwer beeindruckt.'::text,'hatte'::text,'hat'::text,'wirft'::text,'Bis zum Sonnenuntergang hatte der Junge seine Angel fünfzigmal ausgeworfen. Die Fische waren natürlich schwer beeindruckt.'::text),
(338695,37633,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця хлопець ... вудку п''ятдесят разів. Риби, звісно, були дуже вражені.'::text,'закинув'::text,'закинув'::text,'закидає'::text,'До заходу сонця хлопець закинув вудку п''ятдесят разів. Риби, звісно, були дуже вражені.'::text),
(338694,37633,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, el chico ... el sedal cincuenta veces. Los peces, claramente, estaban muy impresionados.'::text,'había lanzado'::text,'ha lanzado'::text,'lanza'::text,'Para el atardecer, el chico había lanzado el sedal cincuenta veces. Los peces, claramente, estaban muy impresionados.'::text),
(338693,37633,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au coucher du soleil, le garçon ... sa ligne cinquante fois. Les poissons, clairement, étaient très impressionnés.'::text,'avait lancé'::text,'a lancé'::text,'lance'::text,'Au coucher du soleil, le garçon avait lancé sa ligne cinquante fois. Les poissons, clairement, étaient très impressionnés.'::text),
(338696,37633,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar çocuk oltasını elli kez ...; balıklar da belli ki çok etkilenmişti.'::text,'atmıştı'::text,'attı'::text,'atıyor'::text,'Gün batımına kadar çocuk oltasını elli kez atmıştı; balıklar da belli ki çok etkilenmişti.'::text),
(338697,37633,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtáig a fiú ötvenszer ... be a zsinórt. A halak nyilván nagyon le voltak nyűgözve.'::text,'dobta'::text,'dobta'::text,'dobja'::text,'Napnyugtáig a fiú ötvenszer dobta be a zsinórt. A halak nyilván nagyon le voltak nyűgözve.'::text),
(338700,37634,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er noch einmal auswirft, ... jeder Fisch im See davon. Genau das, was er braucht.'::text,'schwimmt'::text,'schwämme'::text,'schwamm'::text,'Wenn er noch einmal auswirft, schwimmt jeder Fisch im See davon. Genau das, was er braucht.'::text),
(338704,37634,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він знову закине, кожна риба в озері ... геть. Саме те, що йому треба.'::text,'попливе'::text,'попливла б'::text,'попливла'::text,'Якщо він знову закине, кожна риба в озері попливе геть. Саме те, що йому треба.'::text),
(338703,37634,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si vuelve a lanzar, cada pez del lago ... nadando. Justo lo que necesita.'::text,'se alejará'::text,'se alejaría'::text,'se alejó'::text,'Si vuelve a lanzar, cada pez del lago se alejará nadando. Justo lo que necesita.'::text),
(338702,37634,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il relance, tous les poissons du lac ... à la nage. Exactement ce qu''il lui faut.'::text,'s''enfuiront'::text,'s''enfuiraient'::text,'se sont enfuis'::text,'S''il relance, tous les poissons du lac s''enfuiront à la nage. Exactement ce qu''il lui faut.'::text),
(338705,37634,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir daha atarsa göldeki her balık yüzüp ... — tam da ihtiyacı olan şey.'::text,'gidecek'::text,'giderdi'::text,'gitti'::text,'Bir daha atarsa göldeki her balık yüzüp gidecek — tam da ihtiyacı olan şey.'::text),
(338706,37634,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha újra bedobja, a tó összes hala ... tőle. Pont erre van szüksége.'::text,'el fog úszni'::text,'elúszna'::text,'elúszott'::text,'Ha újra bedobja, a tó összes hala el fog úszni tőle. Pont erre van szüksége.'::text),
(338718,37636,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Schnur ... so weit über den See ausgeworfen, dass die Fische verloren sind!'::text,'wurde'::text,'hat'::text,'wirft'::text,'Die Schnur wurde so weit über den See ausgeworfen, dass die Fische verloren sind!'::text),
(338722,37636,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Волосінь ... так далеко в озеро, що риби приречені!'::text,'закинули'::text,'закинула'::text,'закидає'::text,'Волосінь закинули так далеко в озеро, що риби приречені!'::text),
(338721,37636,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El sedal ... tan lejos en el lago que los peces están perdidos!'::text,'fue lanzado'::text,'lanzó'::text,'está lanzando'::text,'¡El sedal fue lanzado tan lejos en el lago que los peces están perdidos!'::text),
(338720,37636,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La ligne ... si loin sur le lac que les poissons sont condamnés !'::text,'a été lancée'::text,'a lancé'::text,'lance'::text,'La ligne a été lancée si loin sur le lac que les poissons sont condamnés !'::text),
(338723,37636,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Misina göle o kadar uzağa ... ki balıklar mahvoldu!'::text,'atıldı'::text,'attı'::text,'atıyor'::text,'Misina göle o kadar uzağa atıldı ki balıklar mahvoldu!'::text),
(338724,37636,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zsinórt olyan messzire ... a tóba, hogy a halaknak annyi!'::text,'dobták be'::text,'dobta be'::text,'dobja be'::text,'A zsinórt olyan messzire dobták be a tóba, hogy a halaknak annyi!'::text),
(338727,37637,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Abend ... er seine Angel in diesen See aus, und die Fische leben in Angst und Schrecken!'::text,'wirft'::text,'wirft'::text,'hat'::text,'Jeden Abend wirft er seine Angel in diesen See aus, und die Fische leben in Angst und Schrecken!'::text),
(338731,37637,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щовечора він ... вудку в це озеро, і риби живуть у жаху!'::text,'закидає'::text,'закидає'::text,'закинув'::text,'Щовечора він закидає вудку в це озеро, і риби живуть у жаху!'::text),
(338730,37637,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Todas las tardes ... el sedal en este lago y los peces viven aterrorizados!'::text,'lanza'::text,'está lanzando'::text,'ha lanzado'::text,'¡Todas las tardes lanza el sedal en este lago y los peces viven aterrorizados!'::text),
(338729,37637,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque soir, il ... sa ligne dans ce lac, et les poissons vivent dans la terreur !'::text,'lance'::text,'lance'::text,'a lancé'::text,'Chaque soir, il lance sa ligne dans ce lac, et les poissons vivent dans la terreur !'::text),
(338732,37637,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her akşam bu göle olta ... ve balıklar dehşet içinde yaşıyor!'::text,'atıyor'::text,'atıyor'::text,'attı'::text,'Her akşam bu göle olta atıyor ve balıklar dehşet içinde yaşıyor!'::text),
(338733,37637,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden este ... a zsinórt ebbe a tóba, és a halak rettegésben élnek!'::text,'bedobja'::text,'bedobja'::text,'bedobta'::text,'Minden este bedobja a zsinórt ebbe a tóba, és a halak rettegésben élnek!'::text),
(338745,37639,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er schwört, dass er bis nächsten Sommer seine Angel über den ganzen See ...'::text,'ausgeworfen haben wird'::text,'auswerfen wird'::text,'auswirft'::text,'Hör zu, er schwört, dass er bis nächsten Sommer seine Angel über den ganzen See ausgeworfen haben wird.'::text),
(338749,37639,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він клянеться, що до наступного літа ... вудку через усе озеро.'::text,'закине'::text,'закине'::text,'закидає'::text,'Слухай, він клянеться, що до наступного літа закине вудку через усе озеро.'::text),
(338748,37639,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, jura que para el verano que viene ... el sedal de punta a punta del lago.'::text,'habrá lanzado'::text,'lanzará'::text,'lanza'::text,'Oye, jura que para el verano que viene habrá lanzado el sedal de punta a punta del lago.'::text),
(338747,37639,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il jure que d''ici l''été prochain il ... sa ligne à travers tout le lac.'::text,'aura lancé'::text,'lancera'::text,'lance'::text,'Écoute, il jure que d''ici l''été prochain il aura lancé sa ligne à travers tout le lac.'::text),
(338750,37639,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, gelecek yaza kadar oltasını bütün gölün öbür ucuna ... yemin ediyor.'::text,'atmış olacağına'::text,'atacağına'::text,'attığına'::text,'Dinle, gelecek yaza kadar oltasını bütün gölün öbür ucuna atmış olacağına yemin ediyor.'::text),
(338751,37639,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, esküszik, hogy jövő nyárra ... a zsinórt az egész tavon át.'::text,'átdobta'::text,'átdobja'::text,'átdobja'::text,'Figyelj, esküszik, hogy jövő nyárra átdobta a zsinórt az egész tavon át.'::text),
(332067,36897,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen Mittag ... die belebte Straße wieder Menschenmassen anziehen.'::text,'wird'::text,'wird'::text,'zieht'::text,'Morgen Mittag wird die belebte Straße wieder Menschenmassen anziehen.'::text),
(332071,36897,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра опівдні жвава вулиця знову ... натовпи.'::text,'приваблюватиме'::text,'привабить'::text,'приваблює'::text,'Завтра опівдні жвава вулиця знову приваблюватиме натовпи.'::text),
(332070,36897,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a mediodía, la calle concurrida ... multitudes otra vez.'::text,'estará atrayendo'::text,'atraerá'::text,'atrae'::text,'Mañana a mediodía, la calle concurrida estará atrayendo multitudes otra vez.'::text),
(332069,36897,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à midi, la rue animée ... à nouveau les foules.'::text,'sera en train d''attirer'::text,'attirera'::text,'attire'::text,'Demain à midi, la rue animée sera en train d''attirer à nouveau les foules.'::text),
(332072,36897,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın öğlen işlek cadde yine kalabalıkları ...'::text,'çekiyor olacak'::text,'çekecek'::text,'çeker'::text,'Yarın öğlen işlek cadde yine kalabalıkları çekiyor olacak.'::text),
(332073,36897,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap délben a forgalmas utca megint ... a tömeget.'::text,'vonzani fogja'::text,'vonzza majd'::text,'vonzza'::text,'Holnap délben a forgalmas utca megint vonzani fogja a tömeget.'::text),
(332076,36898,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Arbeiter versprechen, dass nichts auf der Straße noch einmal ihre Aufmerksamkeit ...'::text,'auf sich ziehen wird'::text,'gerade auf sich ziehen wird'::text,'auf sich zieht'::text,'Die Arbeiter versprechen, dass nichts auf der Straße noch einmal ihre Aufmerksamkeit auf sich ziehen wird.'::text),
(332080,36898,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Робітники обіцяють, що ніщо на вулиці більше не ... їхньої уваги.'::text,'приверне'::text,'привертатиме'::text,'привертає'::text,'Робітники обіцяють, що ніщо на вулиці більше не приверне їхньої уваги.'::text),
(332079,36898,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los obreros prometen que nada en la calle ... su atención otra vez.'::text,'atraerá'::text,'estará atrayendo'::text,'está atrayendo'::text,'Los obreros prometen que nada en la calle atraerá su atención otra vez.'::text),
(332078,36898,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les ouvriers promettent que rien dans la rue ne ... plus leur attention.'::text,'captera'::text,'sera en train de capter'::text,'capte'::text,'Les ouvriers promettent que rien dans la rue ne captera plus leur attention.'::text),
(332081,36898,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İşçiler sokaktaki hiçbir şeyin bir daha dikkatlerini ... söz veriyor.'::text,'çekmeyeceğine'::text,'çekmiyor olacağına'::text,'çekmediğine'::text,'İşçiler sokaktaki hiçbir şeyin bir daha dikkatlerini çekmeyeceğine söz veriyor.'::text),
(332082,36898,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A munkások megígérik, hogy az utcán semmi nem ... többé a figyelmüket.'::text,'fogja elvonni'::text,'vonja el majd'::text,'vonja el'::text,'A munkások megígérik, hogy az utcán semmi nem fogja elvonni többé a figyelmüket.'::text),
(332085,36899,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du mit so viel Selbstbewusstsein läufst, ... du die Aufmerksamkeit von allen auf dich.'::text,'ziehst'::text,'zogst'::text,'wirst'::text,'Ehrlich, wenn du mit so viel Selbstbewusstsein läufst, ziehst du die Aufmerksamkeit von allen auf dich.'::text),
(332089,36899,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, коли ти йдеш з такою впевненістю, ти ... увагу всіх.'::text,'привертаєш'::text,'привернула'::text,'привернеш'::text,'Чесно, коли ти йдеш з такою впевненістю, ти привертаєш увагу всіх.'::text),
(332088,36899,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si caminas con tanta seguridad, ... la atención de todo el mundo.'::text,'atraes'::text,'atrajiste'::text,'atraerás'::text,'Sinceramente, si caminas con tanta seguridad, atraes la atención de todo el mundo.'::text),
(332087,36899,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, quand tu marches avec autant d''assurance, tu ... l''attention de tout le monde.'::text,'attires'::text,'as attiré'::text,'attireras'::text,'Franchement, quand tu marches avec autant d''assurance, tu attires l''attention de tout le monde.'::text),
(332090,36899,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, o kadar özgüvenle yürüyünce herkesin dikkatini ...'::text,'çekiyorsun'::text,'çektin'::text,'çekeceksin'::text,'Açıkçası, o kadar özgüvenle yürüyünce herkesin dikkatini çekiyorsun.'::text),
(332091,36899,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha ilyen magabiztosan sétálsz, mindenki figyelmét ...'::text,'magadra vonod'::text,'magadra vontad'::text,'magadra fogod vonni'::text,'Őszintén, ha ilyen magabiztosan sétálsz, mindenki figyelmét magadra vonod.'::text),
(332094,36900,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, die vorbeiging, ... die Aufmerksamkeit beider Arbeiter auf sich.'::text,'zog'::text,'wurde gezogen'::text,'ziehend'::text,'Die Frau, die vorbeiging, zog die Aufmerksamkeit beider Arbeiter auf sich.'::text),
(332098,36900,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, що проходила повз, ... увагу обох робітників.'::text,'привернула'::text,'була привернута'::text,'привертаючи'::text,'Жінка, що проходила повз, привернула увагу обох робітників.'::text),
(332097,36900,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer que pasaba ... la atención de los dos obreros.'::text,'atrajo'::text,'fue atraída'::text,'atrayendo'::text,'La mujer que pasaba atrajo la atención de los dos obreros.'::text),
(332096,36900,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme qui passait ... l''attention des deux ouvriers.'::text,'a attiré'::text,'a été attirée'::text,'attirant'::text,'La femme qui passait a attiré l''attention des deux ouvriers.'::text),
(332099,36900,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yanlarından geçen kadın iki işçinin de dikkatini ...'::text,'çekti'::text,'çekildi'::text,'çekerek'::text,'Yanlarından geçen kadın iki işçinin de dikkatini çekti.'::text),
(332100,36900,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az arra sétáló nő ... mindkét munkás figyelmét.'::text,'magára vonta'::text,'magára vonatott'::text,'magára vonva'::text,'Az arra sétáló nő magára vonta mindkét munkás figyelmét.'::text),
(332103,36901,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Irgendwas ... sie mehr anziehen als der Fernseher. Tolle Teamarbeit.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Irgendwas muss sie mehr anziehen als der Fernseher. Tolle Teamarbeit.'::text),
(332107,36901,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щось ... приваблювати їх більше, ніж телевізор. Чудова командна робота.'::text,'мусить'::text,'не може'::text,'не повинно'::text,'Щось мусить приваблювати їх більше, ніж телевізор. Чудова командна робота.'::text),
(332106,36901,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Algo ... estar atrayéndolos más que la tele. Qué gran trabajo en equipo.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'Algo debe de estar atrayéndolos más que la tele. Qué gran trabajo en equipo.'::text),
(332105,36901,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quelque chose ... les attirer plus que la télé. Super travail d''équipe.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'Quelque chose doit les attirer plus que la télé. Super travail d''équipe.'::text),
(332108,36901,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir şey onları televizyondan daha çok cezbediyor ... — harika takım çalışması.'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Bir şey onları televizyondan daha çok cezbediyor olmalı — harika takım çalışması.'::text),
(332109,36901,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Valami ... jobban vonzza őket, mint a tévé. Remek csapatmunka.'::text,'biztosan'::text,'nem lehet, hogy'::text,'nem kéne, hogy'::text,'Valami biztosan jobban vonzza őket, mint a tévé. Remek csapatmunka.'::text),
(332112,36902,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fernseher, ... ein Vermögen gekostet hat, zog weniger Aufmerksamkeit auf sich als die Straße. Makellose Prioritäten.'::text,'der'::text,'wer'::text,'der'::text,'Der Fernseher, der ein Vermögen gekostet hat, zog weniger Aufmerksamkeit auf sich als die Straße. Makellose Prioritäten.'::text),
(332116,36902,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Телевізор, ... коштував цілий статок, привернув менше уваги, ніж вулиця. Бездоганні пріоритети.'::text,'який'::text,'хто'::text,'що'::text,'Телевізор, який коштував цілий статок, привернув менше уваги, ніж вулиця. Бездоганні пріоритети.'::text),
(332115,36902,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tele, ... costó una fortuna, atrajo menos atención que la calle. Prioridades impecables.'::text,'que'::text,'quien'::text,'que'::text,'La tele, que costó una fortuna, atrajo menos atención que la calle. Prioridades impecables.'::text),
(332114,36902,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La télé, ... a coûté une fortune, a attiré moins d''attention que la rue. Des priorités impeccables.'::text,'qui'::text,'qui'::text,'que'::text,'La télé, qui a coûté une fortune, a attiré moins d''attention que la rue. Des priorités impeccables.'::text),
(332117,36902,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir servete mal ... televizyon, sokaktan daha az dikkat çekti. Kusursuz öncelikler.'::text,'olan'::text,'olan'::text,'olan'::text,'Bir servete mal olan televizyon, sokaktan daha az dikkat çekti. Kusursuz öncelikler.'::text),
(332118,36902,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tévé, ... egy vagyonba került, kevesebb figyelmet kapott, mint az utca. Hibátlan prioritások.'::text,'ami'::text,'aki'::text,'amely'::text,'A tévé, ami egy vagyonba került, kevesebb figyelmet kapott, mint az utca. Hibátlan prioritások.'::text),
(332121,36903,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ihr Chef meinte, ein runtergefallener Fernseher ... viel mehr Aufmerksamkeit auf sich ziehen als die Straße, echt.'::text,'würde'::text,'wird'::text,'zieht'::text,'Bro, ihr Chef meinte, ein runtergefallener Fernseher würde viel mehr Aufmerksamkeit auf sich ziehen als die Straße, echt.'::text),
(332125,36903,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, їхній бос сказав, що впалий телик ... набагато більше уваги, ніж вулиця, реально.'::text,'привернув би'::text,'приверне'::text,'привертає'::text,'Бро, їхній бос сказав, що впалий телик привернув би набагато більше уваги, ніж вулиця, реально.'::text),
(332124,36903,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, su jefe dijo que una tele caída ... muchísima más atención que la calle, en serio.'::text,'atraería'::text,'atraerá'::text,'atrae'::text,'Bro, su jefe dijo que una tele caída atraería muchísima más atención que la calle, en serio.'::text),
(332123,36903,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, leur boss a dit qu''une télé qui tombe ... bien plus l''attention que la rue, grave.'::text,'attirerait'::text,'attirera'::text,'attire'::text,'Frérot, leur boss a dit qu''une télé qui tombe attirerait bien plus l''attention que la rue, grave.'::text),
(332126,36903,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, patronları düşen bir televizyonun sokaktan çok daha fazla dikkat ... söyledi, cidden.'::text,'çekeceğini'::text,'çekeceğini'::text,'çektiğini'::text,'Kanka, patronları düşen bir televizyonun sokaktan çok daha fazla dikkat çekeceğini söyledi, cidden.'::text),
(332127,36903,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a főnökük azt mondta, egy leejtett tévé sokkal több figyelmet ..., mint az utca, komolyan.'::text,'vonzana'::text,'vonz majd'::text,'vonz'::text,'Tesó, a főnökük azt mondta, egy leejtett tévé sokkal több figyelmet vonzana, mint az utca, komolyan.'::text),
(332130,36904,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, früher ... diese Straße jedes Wochenende Massen an, echt.'::text,'zog'::text,'zog'::text,'war es gewohnt'::text,'Yo, früher zog diese Straße jedes Wochenende Massen an, echt.'::text),
(332134,36904,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, колись ця вулиця ... натовпи щовихідних, реально.'::text,'приваблювала'::text,'приваблювала'::text,'звикла приваблювати'::text,'Йо, колись ця вулиця приваблювала натовпи щовихідних, реально.'::text),
(332133,36904,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, antes esta calle ... multitudes cada fin de semana, en serio.'::text,'atraía'::text,'atraía'::text,'estaba acostumbrada a atraer'::text,'Oye, antes esta calle atraía multitudes cada fin de semana, en serio.'::text),
(332132,36904,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, à l''époque cette rue ... les foules tous les week-ends, grave.'::text,'attirait'::text,'attirait'::text,'avait l''habitude d''attirer'::text,'Yo, à l''époque cette rue attirait les foules tous les week-ends, grave.'::text),
(332135,36904,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hey, eskiden bu sokak her hafta sonu kalabalıkları ..., cidden.'::text,'çekerdi'::text,'çekerdi'::text,'çekmeye alışkındı'::text,'Hey, eskiden bu sokak her hafta sonu kalabalıkları çekerdi, cidden.'::text),
(332136,36904,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyi, régen ez az utca minden hétvégén ... a tömeget, komolyan.'::text,'vonzotta'::text,'vonzotta'::text,'hozzá volt szokva, hogy vonzza'::text,'Figyi, régen ez az utca minden hétvégén vonzotta a tömeget, komolyan.'::text),
(332148,36906,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In diesem Moment ... die vorbeigehende Frau die Aufmerksamkeit beider Arbeiter auf sich.'::text,'zieht'::text,'zieht'::text,'hat'::text,'In diesem Moment zieht die vorbeigehende Frau die Aufmerksamkeit beider Arbeiter auf sich.'::text),
(332152,36906,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цієї миті жінка, що проходить повз, ... увагу обох робітників.'::text,'привертає'::text,'привертає'::text,'привернула'::text,'Цієї миті жінка, що проходить повз, привертає увагу обох робітників.'::text),
(332151,36906,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento, la mujer que pasa ... la atención de los dos obreros.'::text,'está atrayendo'::text,'atrae'::text,'ha atraído'::text,'En este momento, la mujer que pasa está atrayendo la atención de los dos obreros.'::text),
(332150,36906,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la femme qui passe ... l''attention des deux ouvriers.'::text,'attire'::text,'attire'::text,'a attiré'::text,'En ce moment, la femme qui passe attire l''attention des deux ouvriers.'::text),
(332153,36906,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda yanlarından geçen kadın iki işçinin de dikkatini ...'::text,'çekiyor'::text,'çeker'::text,'çekti'::text,'Şu anda yanlarından geçen kadın iki işçinin de dikkatini çekiyor.'::text),
(332154,36906,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a pillanatban az arra sétáló nő ... mindkét munkás figyelmét.'::text,'magára vonja'::text,'magára vonja'::text,'magára vonta'::text,'Ebben a pillanatban az arra sétáló nő magára vonja mindkét munkás figyelmét.'::text),
(333993,37111,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Pferde in diesem Stall mögen Karotten, ...?'::text,'oder?'::text,'oder?'::text,'echt?'::text,'Die Pferde in diesem Stall mögen Karotten, oder?'::text),
(333997,37111,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коні в цій стайні люблять моркву, ...?'::text,'так?'::text,'так?'::text,'хіба?'::text,'Коні в цій стайні люблять моркву, так?'::text),
(333996,37111,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A los caballos de este establo les gustan las zanahorias, ...'::text,'¿verdad?'::text,'¿no?'::text,'¿sí?'::text,'A los caballos de este establo les gustan las zanahorias, ¿verdad?'::text),
(333995,37111,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les chevaux de cette écurie aiment les carottes, ... ?'::text,'non ?'::text,'pas vrai ?'::text,'si ?'::text,'Les chevaux de cette écurie aiment les carottes, non ?'::text),
(333998,37111,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu ahırdaki atlar havuç sever, ...?'::text,'değil mi?'::text,'değil mi?'::text,'öyle mi?'::text,'Bu ahırdaki atlar havuç sever, değil mi?'::text),
(333999,37111,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az istállóban lévő lovak szeretik a répát, ...?'::text,'ugye?'::text,'nem?'::text,'tényleg?'::text,'Az istállóban lévő lovak szeretik a répát, ugye?'::text),
(334011,37113,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend ... die Pferde in diesem Stall absolut jede Karotte gefressen haben!'::text,'werden'::text,'werden'::text,'werden'::text,'Bis heute Abend werden die Pferde in diesem Stall absolut jede Karotte gefressen haben!'::text),
(334015,37113,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора коні в цій стайні ... абсолютно кожну морквину!'::text,'з''їдять'::text,'з''їдять'::text,'їстимуть'::text,'До вечора коні в цій стайні з''їдять абсолютно кожну морквину!'::text),
(334014,37113,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para esta noche, los caballos de este establo ... absolutamente todas las zanahorias!'::text,'se habrán comido'::text,'se comerán'::text,'estarán comiendo'::text,'¡Para esta noche, los caballos de este establo se habrán comido absolutamente todas las zanahorias!'::text),
(334013,37113,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, les chevaux de cette écurie ... absolument toutes les carottes !'::text,'auront mangé'::text,'mangeront'::text,'seront en train de manger'::text,'D''ici ce soir, les chevaux de cette écurie auront mangé absolument toutes les carottes !'::text),
(334016,37113,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar bu ahırdaki atlar kesinlikle bütün havuçları ...!'::text,'yemiş olacak'::text,'yiyecek'::text,'yiyor olacak'::text,'Bu akşama kadar bu ahırdaki atlar kesinlikle bütün havuçları yemiş olacak!'::text),
(334017,37113,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére az istálló lovai az összes répát ...!'::text,'megették'::text,'megeszik'::text,'enni fogják'::text,'Estére az istálló lovai az összes répát megették!'::text),
(334020,37114,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Kiste leer gewesen wäre, ... das Pferd in diesem Stall den schlimmsten Tag aller Zeiten gehabt!'::text,'hätte'::text,'hätte'::text,'hatte'::text,'Wenn die Kiste leer gewesen wäre, hätte das Pferd in diesem Stall den schlimmsten Tag aller Zeiten gehabt!'::text),
(334024,37114,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ящик був порожній, у коня в цій стайні ... найгірший день у житті!'::text,'був би'::text,'був би'::text,'був'::text,'Якби ящик був порожній, у коня в цій стайні був би найгірший день у житті!'::text),
(334023,37114,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si la caja hubiera estado vacía, el caballo de este establo ... el peor día de su vida!'::text,'habría tenido'::text,'tendría'::text,'tuvo'::text,'¡Si la caja hubiera estado vacía, el caballo de este establo habría tenido el peor día de su vida!'::text),
(334022,37114,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la caisse avait été vide, le cheval de cette écurie ... la pire journée de sa vie !'::text,'aurait passé'::text,'passerait'::text,'a passé'::text,'Si la caisse avait été vide, le cheval de cette écurie aurait passé la pire journée de sa vie !'::text),
(334025,37114,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kasa boş olsaydı bu ahırdaki at hayatının en kötü gününü ...!'::text,'geçirmiş olurdu'::text,'geçirirdi'::text,'geçirdi'::text,'Kasa boş olsaydı bu ahırdaki at hayatının en kötü gününü geçirmiş olurdu!'::text),
(334026,37114,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a láda üres lett volna, ennek az istállónak a lova minden idők legrosszabb napját ...!'::text,'élte volna át'::text,'élné át'::text,'élte át'::text,'Ha a láda üres lett volna, ennek az istállónak a lova minden idők legrosszabb napját élte volna át!'::text),
(334029,37115,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Pferd weigerte sich, den Stall ohne seine Karotte ... – eine totale Katastrophe!'::text,'zu verlassen'::text,'verlassen'::text,'verlassen'::text,'Das Pferd weigerte sich, den Stall ohne seine Karotte zu verlassen – eine totale Katastrophe!'::text),
(334033,37115,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кінь відмовився ... стайню без своєї морквини. Повна катастрофа!'::text,'покинути'::text,'покидання'::text,'покинути'::text,'Кінь відмовився покинути стайню без своєї морквини. Повна катастрофа!'::text),
(334032,37115,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El caballo se negó ... el establo sin su zanahoria. ¡Un desastre total!'::text,'a dejar'::text,'dejando'::text,'dejar'::text,'El caballo se negó a dejar el establo sin su zanahoria. ¡Un desastre total!'::text),
(334031,37115,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cheval a refusé ... l''écurie sans sa carotte. Un désastre total !'::text,'de quitter'::text,'quittant'::text,'quitter'::text,'Le cheval a refusé de quitter l''écurie sans sa carotte. Un désastre total !'::text),
(334034,37115,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'At havucu olmadan ahırdan ... reddetti. Tam bir felaket!'::text,'çıkmayı'::text,'çıkarak'::text,'çık'::text,'At havucu olmadan ahırdan çıkmayı reddetti. Tam bir felaket!'::text),
(334035,37115,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ló nem volt hajlandó ... az istállót a répája nélkül. Teljes katasztrófa!'::text,'elhagyni'::text,'elhagyva'::text,'elhagy'::text,'A ló nem volt hajlandó elhagyni az istállót a répája nélkül. Teljes katasztrófa!'::text),
(334038,37116,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Moment, ich hab gehört, das Pferd in dem Stall ... hungrig gewesen sein, so schnell hat es die Karotte genommen.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Moment, ich hab gehört, das Pferd in dem Stall muss hungrig gewesen sein, so schnell hat es die Karotte genommen.'::text),
(334042,37116,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, я чула, що кінь у тій стайні ... бути голодним, так швидко він схопив морквину.'::text,'мусив'::text,'не міг'::text,'не мав'::text,'Стривай, я чула, що кінь у тій стайні мусив бути голодним, так швидко він схопив морквину.'::text),
(334041,37116,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, he oído que el caballo de ese establo ... tener hambre, cogió la zanahoria rapidísimo.'::text,'debía de'::text,'no podía'::text,'no debería'::text,'Espera, he oído que el caballo de ese establo debía de tener hambre, cogió la zanahoria rapidísimo.'::text),
(334040,37116,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, j''ai entendu dire que le cheval de cette écurie ... avoir faim, il a pris la carotte si vite.'::text,'devait'::text,'ne pouvait pas'::text,'n''aurait pas dû'::text,'Attends, j''ai entendu dire que le cheval de cette écurie devait avoir faim, il a pris la carotte si vite.'::text),
(334043,37116,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, duydum ki o ahırdaki at aç ..., havucu o kadar hızlı aldı ki.'::text,'olmalıymış'::text,'olamazmış'::text,'olmamalıymış'::text,'Dur, duydum ki o ahırdaki at aç olmalıymış, havucu o kadar hızlı aldı ki.'::text),
(334044,37116,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, azt hallottam, hogy abban az istállóban a ló ... éhes volt, olyan gyorsan elvette a répát.'::text,'biztosan'::text,'nem lehet, hogy'::text,'nem kellett volna, hogy'::text,'Várj, azt hallottam, hogy abban az istállóban a ló biztosan éhes volt, olyan gyorsan elvette a répát.'::text),
(334047,37117,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, dass sie letzte Woche den ganzen Stall für die Pferde haben ... lassen.'::text,'putzen'::text,'zu putzen'::text,'putzend'::text,'Hör zu, er hat mir erzählt, dass sie letzte Woche den ganzen Stall für die Pferde haben putzen lassen.'::text),
(334051,37117,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що минулого тижня вони домовилися, щоб усю стайню ... для коней.'::text,'почистили'::text,'почистити'::text,'чистячи'::text,'Слухай, він сказав мені, що минулого тижня вони домовилися, щоб усю стайню почистили для коней.'::text),
(334050,37117,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que la semana pasada hicieron ... todo el establo para los caballos.'::text,'limpiar'::text,'limpiar'::text,'limpiando'::text,'Oye, me dijo que la semana pasada hicieron limpiar todo el establo para los caballos.'::text),
(334049,37117,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''ils ont fait ... toute l''écurie la semaine dernière pour les chevaux.'::text,'nettoyer'::text,'nettoyer'::text,'nettoyant'::text,'Écoute, il m''a dit qu''ils ont fait nettoyer toute l''écurie la semaine dernière pour les chevaux.'::text),
(334052,37117,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana geçen hafta atlar için bütün ahırı ... söyledi.'::text,'temizlettiklerini'::text,'temizlemeyi'::text,'temizlerken'::text,'Dinle, bana geçen hafta atlar için bütün ahırı temizlettiklerini söyledi.'::text),
(334053,37117,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a múlt héten ... az egész istállót a lovak miatt.'::text,'kitakaríttatták'::text,'kitakarítani'::text,'takarítva'::text,'Figyelj, azt mondta, hogy a múlt héten kitakaríttatták az egész istállót a lovak miatt.'::text),
(334065,37119,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Stall, durch ... Gang der Junge gelaufen ist, ist eindeutig ein sehr seriöser Arbeitsplatz.'::text,'dessen'::text,'den'::text,'wo'::text,'Der Stall, durch dessen Gang der Junge gelaufen ist, ist eindeutig ein sehr seriöser Arbeitsplatz.'::text),
(334069,37119,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стайня, ... проходом ішов хлопчик, явно дуже серйозне робоче місце.'::text,'чиїм'::text,'якою'::text,'де'::text,'Стайня, чиїм проходом ішов хлопчик, явно дуже серйозне робоче місце.'::text),
(334068,37119,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El establo, por ... pasillo caminó el niño, es claramente un lugar de trabajo muy serio.'::text,'cuyo'::text,'el cual'::text,'donde'::text,'El establo, por cuyo pasillo caminó el niño, es claramente un lugar de trabajo muy serio.'::text),
(334067,37119,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''écurie, ... le garçon a parcouru l''allée, est clairement un lieu de travail très sérieux.'::text,'dont'::text,'que'::text,'où'::text,'L''écurie, dont le garçon a parcouru l''allée, est clairement un lieu de travail très sérieux.'::text),
(334070,37119,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuğun ... yürüdüğü ahır belli ki çok ciddi bir iş yeri.'::text,'koridorunda'::text,'içinde'::text,'orada'::text,'Çocuğun koridorunda yürüdüğü ahır belli ki çok ciddi bir iş yeri.'::text),
(334071,37119,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az istálló, ... folyosóján a kisfiú végigsétált, nyilvánvalóan nagyon komoly munkahely.'::text,'amelynek a'::text,'amely'::text,'ahol'::text,'Az istálló, amelynek a folyosóján a kisfiú végigsétált, nyilvánvalóan nagyon komoly munkahely.'::text),
(334074,37120,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Pferde in diesem Stall fressen jeden Tag ...'::text,'Heu'::text,'ein Heu'::text,'die Heus'::text,'Die Pferde in diesem Stall fressen jeden Tag Heu.'::text),
(334078,37120,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коні в цій стайні щодня їдять ...'::text,'сіно'::text,'сіно'::text,'сіна'::text,'Коні в цій стайні щодня їдять сіно.'::text),
(334077,37120,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los caballos de este establo comen ... todos los días.'::text,'heno'::text,'un heno'::text,'los henos'::text,'Los caballos de este establo comen heno todos los días.'::text),
(334076,37120,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les chevaux de cette écurie mangent ... tous les jours.'::text,'du foin'::text,'un foin'::text,'les foins'::text,'Les chevaux de cette écurie mangent du foin tous les jours.'::text),
(334079,37120,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu ahırdaki atlar her gün ... yiyor.'::text,'kuru ot'::text,'bir kuru ot'::text,'kuru otlar'::text,'Bu ahırdaki atlar her gün kuru ot yiyor.'::text),
(334080,37120,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ennek az istállónak a lovai minden nap ... esznek.'::text,'szénát'::text,'egy szénát'::text,'a szénákat'::text,'Ennek az istállónak a lovai minden nap szénát esznek.'::text),
(334083,37121,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Pferde in diesem Stall bekommen Karotten, ... sie ruhig bleiben.'::text,'vorausgesetzt, dass'::text,'falls'::text,'es sei denn'::text,'Die Pferde in diesem Stall bekommen Karotten, vorausgesetzt, dass sie ruhig bleiben.'::text),
(334087,37121,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коні в цій стайні отримують моркву, ... вони залишаються спокійними.'::text,'за умови, що'::text,'на випадок, якщо'::text,'хіба що'::text,'Коні в цій стайні отримують моркву, за умови, що вони залишаються спокійними.'::text),
(334086,37121,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los caballos de este establo reciben zanahorias ... se queden tranquilos.'::text,'siempre que'::text,'por si'::text,'a menos que'::text,'Los caballos de este establo reciben zanahorias siempre que se queden tranquilos.'::text),
(334085,37121,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les chevaux de cette écurie ont des carottes ... ils restent calmes.'::text,'à condition qu'''::text,'au cas où'::text,'à moins qu'''::text,'Les chevaux de cette écurie ont des carottes à condition qu'' ils restent calmes.'::text),
(334088,37121,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu ahırdaki atlar sakin ... havuç alıyor.'::text,'kalmaları şartıyla'::text,'kalırlar diye'::text,'kalmadıkça'::text,'Bu ahırdaki atlar sakin kalmaları şartıyla havuç alıyor.'::text),
(334089,37121,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ennek az istállónak a lovai répát kapnak, ... nyugodtak maradnak.'::text,'feltéve, hogy'::text,'arra az esetre, ha'::text,'hacsak nem'::text,'Ennek az istállónak a lovai répát kapnak, feltéve, hogy nyugodtak maradnak.'::text),
(375519,41725,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, wenn die Möwe weiter so tief fliegt, ... wir den Hafen völlig sicher.'::text,'erreichen'::text,'erreichten'::text,'erreichten'::text,'Klar, wenn die Möwe weiter so tief fliegt, erreichen wir den Hafen völlig sicher.'::text),
(375523,41725,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, якщо чайка й далі летітиме так низько, ми ... до порту в повній безпеці.'::text,'долетимо'::text,'долетіли б'::text,'долетіли'::text,'Звісно, якщо чайка й далі летітиме так низько, ми долетимо до порту в повній безпеці.'::text),
(375522,41725,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, si la gaviota sigue volando tan bajo, ... al puerto completamente a salvo.'::text,'llegaremos'::text,'llegaríamos'::text,'llegamos'::text,'Obviamente, si la gaviota sigue volando tan bajo, llegaremos al puerto completamente a salvo.'::text),
(375521,41725,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, si la mouette continue de voler aussi bas, on ... le port en toute sécurité.'::text,'atteindra'::text,'atteindrait'::text,'a atteint'::text,'Évidemment, si la mouette continue de voler aussi bas, on atteindra le port en toute sécurité.'::text),
(375524,41725,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki martı bu kadar alçaktan uçmaya devam ederse limana tamamen güvenle ...'::text,'varacağız'::text,'varırdık'::text,'vardık'::text,'Tabii ki martı bu kadar alçaktan uçmaya devam ederse limana tamamen güvenle varacağız.'::text),
(375525,41725,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván, ha a sirály továbbra is ilyen alacsonyan repül, tökéletes biztonságban ... a kikötőbe.'::text,'érünk be'::text,'érnénk be'::text,'értünk be'::text,'Nyilván, ha a sirály továbbra is ilyen alacsonyan repül, tökéletes biztonságban érünk be a kikötőbe.'::text),
(375528,41726,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ich Zügel für eine Möwe hätte, ... ich jeden Hafen per Vogel besuchen. Eindeutig ein großartiger Plan.'::text,'würde'::text,'werde'::text,'besuche'::text,'Wenn ich Zügel für eine Möwe hätte, würde ich jeden Hafen per Vogel besuchen. Eindeutig ein großartiger Plan.'::text),
(375532,41726,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в мене були віжки для чайки, я ... кожен порт на птасі. Явно чудовий план.'::text,'відвідав би'::text,'відвідаю'::text,'відвідую'::text,'Якби в мене були віжки для чайки, я відвідав би кожен порт на птасі. Явно чудовий план.'::text),
(375531,41726,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tuviera riendas para una gaviota, ... todos los puertos en pájaro. Claramente un gran plan.'::text,'visitaría'::text,'visitaré'::text,'visito'::text,'Si tuviera riendas para una gaviota, visitaría todos los puertos en pájaro. Claramente un gran plan.'::text),
(375530,41726,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si j''avais des rênes pour une mouette, je ... chaque port à dos d''oiseau. Clairement un super plan.'::text,'visiterais'::text,'visiterai'::text,'visite'::text,'Si j''avais des rênes pour une mouette, je visiterais chaque port à dos d''oiseau. Clairement un super plan.'::text),
(375533,41726,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir martı için dizginlerim olsa her limanı kuşla ...; belli ki harika bir plan.'::text,'gezerdim'::text,'gezeceğim'::text,'geziyorum'::text,'Bir martı için dizginlerim olsa her limanı kuşla gezerdim; belli ki harika bir plan.'::text),
(375534,41726,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha lenne gyeplőm egy sirályhoz, minden kikötőt madárháton ..., nyilván remek terv.'::text,'látogatnék meg'::text,'meglátogatok'::text,'látogatok'::text,'Ha lenne gyeplőm egy sirályhoz, minden kikötőt madárháton látogatnék meg, nyilván remek terv.'::text),
(375537,41727,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die roten Frachtschiffe ... an jenem Morgen früh im Hafen entladen.'::text,'wurden'::text,'haben'::text,'werden'::text,'Die roten Frachtschiffe wurden an jenem Morgen früh im Hafen entladen.'::text),
(375541,41727,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Червоні вантажні судна ... в порту рано того ранку.'::text,'розвантажили'::text,'розвантажили'::text,'розвантажують'::text,'Червоні вантажні судна розвантажили в порту рано того ранку.'::text),
(375540,41727,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los barcos de carga rojos ... en el puerto temprano esa mañana.'::text,'fueron descargados'::text,'descargaron'::text,'son descargados'::text,'Los barcos de carga rojos fueron descargados en el puerto temprano esa mañana.'::text),
(375539,41727,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les cargos rouges ... au port tôt ce matin-là.'::text,'ont été déchargés'::text,'ont déchargé'::text,'sont déchargés'::text,'Les cargos rouges ont été déchargés au port tôt ce matin-là.'::text),
(375542,41727,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kırmızı yük gemileri o sabah erkenden limanda ...'::text,'boşaltıldı'::text,'boşalttı'::text,'boşaltılıyor'::text,'Kırmızı yük gemileri o sabah erkenden limanda boşaltıldı.'::text),
(375543,41727,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piros teherhajókat aznap kora reggel ... a kikötőben.'::text,'kirakodták'::text,'kirakodta'::text,'kirakodják'::text,'A piros teherhajókat aznap kora reggel kirakodták a kikötőben.'::text),
(375555,41729,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mit 2 Frachtschiffen am Kai ... das hier der wichtigste Logistikhafen der Stadt sein.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Mit 2 Frachtschiffen am Kai muss das hier der wichtigste Logistikhafen der Stadt sein.'::text),
(375559,41729,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'З 2 вантажними суднами біля причалу це ... бути головним логістичним портом міста.'::text,'мусить'::text,'не може'::text,'не повинно'::text,'З 2 вантажними суднами біля причалу це мусить бути головним логістичним портом міста.'::text),
(375558,41729,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con 2 barcos de carga en el muelle, este ... ser el principal puerto logístico de la ciudad.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'Con 2 barcos de carga en el muelle, este debe de ser el principal puerto logístico de la ciudad.'::text),
(375557,41729,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avec 2 cargos à quai, ce ... être le principal port logistique de la ville.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'Avec 2 cargos à quai, ce doit être le principal port logistique de la ville.'::text),
(375560,41729,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rıhtımda 2 yük gemisiyle bu, şehrin ana lojistik limanı ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Rıhtımda 2 yük gemisiyle bu, şehrin ana lojistik limanı olmalı.'::text),
(375561,41729,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'2 teherhajóval a dokkban ez ... a város fő logisztikai kikötője.'::text,'biztosan'::text,'nem lehet'::text,'nem kellene hogy legyen'::text,'2 teherhajóval a dokkban ez biztosan a város fő logisztikai kikötője.'::text),
(375564,41730,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hafen, ... der Reiter flog, war ein furchterregendes Labyrinth aus riesigen Schiffen!'::text,'durch den'::text,'der'::text,'wo'::text,'Der Hafen, durch den der Reiter flog, war ein furchterregendes Labyrinth aus riesigen Schiffen!'::text),
(375568,41730,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Порт, ... пролетів вершник, був жахливим лабіринтом гігантських кораблів!'::text,'через який'::text,'хто'::text,'де'::text,'Порт, через який пролетів вершник, був жахливим лабіринтом гігантських кораблів!'::text),
(375567,41730,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El puerto ... atravesó el jinete era un laberinto aterrador de barcos gigantes!'::text,'que'::text,'quien'::text,'donde'::text,'¡El puerto que atravesó el jinete era un laberinto aterrador de barcos gigantes!'::text),
(375566,41730,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le port ... le cavalier a traversé était un labyrinthe terrifiant de navires géants !'::text,'que'::text,'qui'::text,'où'::text,'Le port que le cavalier a traversé était un labyrinthe terrifiant de navires géants !'::text),
(375569,41730,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Binicinin içinden ... liman, dev gemilerden oluşan korkunç bir labirentti!'::text,'uçtuğu'::text,'uçan'::text,'uçtuğu yer'::text,'Binicinin içinden uçtuğu liman, dev gemilerden oluşan korkunç bir labirentti!'::text),
(375570,41730,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kikötő, ... a lovas átrepült, óriáshajók félelmetes útvesztője volt!'::text,'amelyen'::text,'aki'::text,'ahol'::text,'A kikötő, amelyen a lovas átrepült, óriáshajók félelmetes útvesztője volt!'::text),
(375573,41731,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Reiter sagte, es ... an diesem Tag sein erster Ritt in den Hafen. Der pure Horror!'::text,'war'::text,'ist'::text,'ist gewesen'::text,'Der Reiter sagte, es war an diesem Tag sein erster Ritt in den Hafen. Der pure Horror!'::text),
(375577,41731,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вершник сказав, що це ... його перша поїздка в порт того дня. Суцільний жах!'::text,'була'::text,'є'::text,'була'::text,'Вершник сказав, що це була його перша поїздка в порт того дня. Суцільний жах!'::text),
(375576,41731,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jinete dijo que ... su primer viaje al puerto ese día. ¡Terror absoluto!'::text,'era'::text,'es'::text,'ha sido'::text,'El jinete dijo que era su primer viaje al puerto ese día. ¡Terror absoluto!'::text),
(375575,41731,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cavalier a dit que ... sa première course vers le port ce jour-là. La terreur totale !'::text,'c''était'::text,'c''est'::text,'ça a été'::text,'Le cavalier a dit que c''était sa première course vers le port ce jour-là. La terreur totale !'::text),
(375578,41731,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Binici, bunun o gün limana ilk yolculuğu ... söyledi. Tam bir dehşet!'::text,'olduğunu'::text,'olduğunu'::text,'olduğunu'::text,'Binici, bunun o gün limana ilk yolculuğu olduğunu söyledi. Tam bir dehşet!'::text),
(375579,41731,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lovas azt mondta, hogy aznap ez ... az első útja a kikötőbe. Tiszta rettegés!'::text,'volt'::text,NULL::text,'volt'::text,'A lovas azt mondta, hogy aznap ez volt az első útja a kikötőbe. Tiszta rettegés!'::text),
(375582,41732,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Reiter ... früher Angst, über einen Hafen zu fliegen; jetzt reitet er auf einer Möwe.'::text,'hatte'::text,'hätte'::text,'war es gewohnt'::text,'Der Reiter hatte früher Angst, über einen Hafen zu fliegen; jetzt reitet er auf einer Möwe.'::text),
(375586,41732,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вершник ... польотів над портом; тепер він їздить на чайці.'::text,'колись боявся'::text,'боявся б'::text,'звик боятися'::text,'Вершник колись боявся польотів над портом; тепер він їздить на чайці.'::text),
(375585,41732,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jinete ... tener miedo de volar sobre un puerto; ahora monta una gaviota.'::text,'solía'::text,'tendría'::text,'estaba acostumbrado a'::text,'El jinete solía tener miedo de volar sobre un puerto; ahora monta una gaviota.'::text),
(375584,41732,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cavalier ... peur de survoler un port ; maintenant il chevauche une mouette.'::text,'avait autrefois'::text,'aurait'::text,'avait l''habitude d''avoir'::text,'Le cavalier avait autrefois peur de survoler un port ; maintenant il chevauche une mouette.'::text),
(375587,41732,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Binici eskiden bir limanın üstünden uçmaktan ...; şimdi bir martıya biniyor.'::text,'korkardı'::text,'korkardı'::text,'korkmaya alışkındı'::text,'Binici eskiden bir limanın üstünden uçmaktan korkardı; şimdi bir martıya biniyor.'::text),
(375588,41732,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lovas régen ... attól, hogy egy kikötő fölött repüljön; most sirályon lovagol.'::text,'félt'::text,'félne'::text,'hozzá volt szokva, hogy féljen'::text,'A lovas régen félt attól, hogy egy kikötő fölött repüljön; most sirályon lovagol.'::text),
(375591,41733,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Reiter bat die Möwe, ihn zum Turm im Hafen ...'::text,'zu bringen'::text,'bringen'::text,'bringen'::text,'Der Reiter bat die Möwe, ihn zum Turm im Hafen zu bringen.'::text),
(375595,41733,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вершник попросив чайку ... його до вежі в порту.'::text,'віднести'::text,'несення'::text,'віднести'::text,'Вершник попросив чайку віднести його до вежі в порту.'::text),
(375594,41733,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jinete le pidió a la gaviota que lo ... a la torre del puerto.'::text,'llevara'::text,'llevando'::text,'llevar'::text,'El jinete le pidió a la gaviota que lo llevara a la torre del puerto.'::text),
(375593,41733,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cavalier a demandé à la mouette ... à la tour du port.'::text,'de l''emmener'::text,'l''emmenant'::text,'l''emmener'::text,'Le cavalier a demandé à la mouette de l''emmener à la tour du port.'::text),
(375596,41733,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Binici martıdan onu limandaki kuleye ... istedi.'::text,'götürmesini'::text,'götürerek'::text,'götür'::text,'Binici martıdan onu limandaki kuleye götürmesini istedi.'::text),
(375597,41733,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lovas megkérte a sirályt, hogy ... el a kikötői toronyhoz.'::text,'vigye'::text,'víve'::text,'vinni'::text,'A lovas megkérte a sirályt, hogy vigye el a kikötői toronyhoz.'::text),
(375609,41735,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... diese Möwe den Hafen besser als jeder Kapitän.'::text,'kennt'::text,'kennt'::text,'hat gekannt'::text,'Okay, also angeblich kennt diese Möwe den Hafen besser als jeder Kapitän.'::text),
(375613,41735,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, що ця чайка ... порт краще за будь-якого капітана.'::text,'знає'::text,'знає'::text,'знала'::text,'Коротше, кажуть, що ця чайка знає порт краще за будь-якого капітана.'::text),
(375612,41735,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues dicen que esta gaviota ... el puerto mejor que cualquier capitán.'::text,'conoce'::text,'está conociendo'::text,'ha conocido'::text,'Vale, pues dicen que esta gaviota conoce el puerto mejor que cualquier capitán.'::text),
(375611,41735,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, la rumeur dit que cette mouette ... le port mieux que n''importe quel capitaine.'::text,'connaît'::text,'connaît'::text,'a connu'::text,'Bon alors, la rumeur dit que cette mouette connaît le port mieux que n''importe quel capitaine.'::text),
(375614,41735,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, söylentiye göre bu martı limanı herhangi bir kaptandan daha iyi ...'::text,'biliyormuş'::text,'biliyormuş'::text,'bilmiş'::text,'Tamam, söylentiye göre bu martı limanı herhangi bir kaptandan daha iyi biliyormuş.'::text),
(375615,41735,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval a pletyka szerint ez a sirály jobban ... a kikötőt, mint bármelyik kapitány.'::text,'ismeri'::text,'ismeri'::text,'ismerte'::text,'Szóval a pletyka szerint ez a sirály jobban ismeri a kikötőt, mint bármelyik kapitány.'::text),
(361668,40186,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ein Husky ... sich gerade auf dem Rücken, als sein identischer Zwilling rüberkam, ohne Witz.'::text,'wälzte'::text,'wälzte'::text,'hat gewälzt'::text,'Bro, ein Husky wälzte sich gerade auf dem Rücken, als sein identischer Zwilling rüberkam, ohne Witz.'::text),
(361672,40186,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, один хаскі ... на спині, коли до нього підійшов його ідентичний близнюк, без жартів.'::text,'качався'::text,'перекотився'::text,'перекотився'::text,'Бро, один хаскі качався на спині, коли до нього підійшов його ідентичний близнюк, без жартів.'::text),
(361671,40186,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, un husky ... panza arriba cuando su gemelo idéntico se acercó, en serio.'::text,'se estaba revolcando'::text,'se revolcó'::text,'se ha revolcado'::text,'Bro, un husky se estaba revolcando panza arriba cuando su gemelo idéntico se acercó, en serio.'::text),
(361670,40186,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, un husky ... sur le dos quand son jumeau identique est arrivé, sans mentir.'::text,'se roulait'::text,'s''est roulé'::text,'s''est roulé'::text,'Frérot, un husky se roulait sur le dos quand son jumeau identique est arrivé, sans mentir.'::text),
(361673,40186,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bir husky sırtüstü ... ki tıpatıp aynı ikizi yanına geldi, yalan yok.'::text,'yuvarlanıyordu'::text,'yuvarlandı'::text,'yuvarlandı'::text,'Kanka, bir husky sırtüstü yuvarlanıyordu ki tıpatıp aynı ikizi yanına geldi, yalan yok.'::text),
(361674,40186,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az egyik husky épp a hátán ..., amikor odajött a tök egyforma ikertestvére, komolyan.'::text,'hengergett'::text,'hengeredett meg'::text,'hengeredett meg'::text,'Tesó, az egyik husky épp a hátán hengergett, amikor odajött a tök egyforma ikertestvére, komolyan.'::text),
(361677,40187,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, diese identischen Huskys ... sich schon den ganzen Tag gegenseitig herum, echt.'::text,'schubsen'::text,'schubsen'::text,'schubsen'::text,'Nee, diese identischen Huskys schubsen sich schon den ganzen Tag gegenseitig herum, echt.'::text),
(361681,40187,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, ці ідентичні хаскі ... одне одного цілий день, реально.'::text,'штовхають'::text,'штовхають'::text,'штовхають'::text,'Не, ці ідентичні хаскі штовхають одне одного цілий день, реально.'::text),
(361680,40187,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, estos huskies idénticos ... todo el día, en serio.'::text,'llevan empujándose'::text,'se están empujando'::text,'se empujan'::text,'Qué va, estos huskies idénticos llevan empujándose todo el día, en serio.'::text),
(361679,40187,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, ces huskies identiques ... toute la journée, grave.'::text,'se bousculent'::text,'se bousculent'::text,'se bousculent'::text,'Nan, ces huskies identiques se bousculent toute la journée, grave.'::text),
(361682,40187,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, bu tıpatıp aynı huskyler bütün gün birbirlerini ..., cidden.'::text,'itip kakıyor'::text,'itip kakıyor'::text,'itip kakar'::text,'Yok, bu tıpatıp aynı huskyler bütün gün birbirlerini itip kakıyor, cidden.'::text),
(361683,40187,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, ezek az egyforma huskyk egész nap ... egymást, komolyan.'::text,'lökdösik'::text,'lökdösik'::text,'lökdösik'::text,'Á, ezek az egyforma huskyk egész nap lökdösik egymást, komolyan.'::text),
(361686,40188,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um 15:15 Uhr, während des Meetings, ... sich einer der identischen Huskys auf dem Rücken.'::text,'wälzte'::text,'wälzte'::text,'hat gewälzt'::text,'Um 15:15 Uhr, während des Meetings, wälzte sich einer der identischen Huskys auf dem Rücken.'::text),
(361690,40188,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'О 15:15, під час наради, один з ідентичних хаскі ... на спині.'::text,'качався'::text,'перекотився'::text,'перекотився'::text,'О 15:15, під час наради, один з ідентичних хаскі качався на спині.'::text),
(361689,40188,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A las 15:15, durante la reunión, uno de los huskies idénticos ... panza arriba.'::text,'se estaba revolcando'::text,'se revolcó'::text,'se ha revolcado'::text,'A las 15:15, durante la reunión, uno de los huskies idénticos se estaba revolcando panza arriba.'::text),
(361688,40188,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À 15 h 15, pendant la réunion, l''un des huskies identiques ... sur le dos.'::text,'se roulait'::text,'s''est roulé'::text,'s''est roulé'::text,'À 15 h 15, pendant la réunion, l''un des huskies identiques se roulait sur le dos.'::text),
(361691,40188,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 15.15''te, toplantı sırasında, tıpatıp aynı huskylerden biri sırtüstü ...'::text,'yuvarlanıyordu'::text,'yuvarlandı'::text,'yuvarlandı'::text,'Saat 15.15''te, toplantı sırasında, tıpatıp aynı huskylerden biri sırtüstü yuvarlanıyordu.'::text),
(361692,40188,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'15:15-kor, a megbeszélés alatt, az egyik egyforma husky a hátán ...'::text,'hengergett'::text,'hengeredett meg'::text,'hengeredett meg'::text,'15:15-kor, a megbeszélés alatt, az egyik egyforma husky a hátán hengergett.'::text),
(361704,40190,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als ich mich umdrehte, ... die identischen Huskys schon die Plätze getauscht. Absolutes Chaos!'::text,'hatten'::text,'haben'::text,'tauschen'::text,'Als ich mich umdrehte, hatten die identischen Huskys schon die Plätze getauscht. Absolutes Chaos!'::text),
(361708,40190,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки я обернувся, ідентичні хаскі ... місцями. Абсолютний хаос!'::text,'помінялися'::text,'помінялися'::text,'міняються'::text,'Поки я обернувся, ідентичні хаскі помінялися місцями. Абсолютний хаос!'::text),
(361707,40190,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando me di la vuelta, los huskies idénticos ... de sitio. ¡Caos absoluto!'::text,'habían cambiado'::text,'han cambiado'::text,'cambian'::text,'Para cuando me di la vuelta, los huskies idénticos habían cambiado de sitio. ¡Caos absoluto!'::text),
(361706,40190,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que je me retourne, les huskies identiques ... de place. Le chaos total !'::text,'avaient changé'::text,'ont changé'::text,'changent'::text,'Le temps que je me retourne, les huskies identiques avaient changé de place. Le chaos total !'::text),
(361709,40190,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ben dönene kadar tıpatıp aynı huskyler yer ...: tam bir kaos!'::text,'değiştirmişti'::text,'değiştirdi'::text,'değiştiriyor'::text,'Ben dönene kadar tıpatıp aynı huskyler yer değiştirmişti: tam bir kaos!'::text),
(361710,40190,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire megfordultam, az egyforma huskyk ... helyet. Totális káosz!'::text,'cseréltek'::text,'cseréltek'::text,'cserélnek'::text,'Mire megfordultam, az egyforma huskyk cseréltek helyet. Totális káosz!'::text),
(361713,40191,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... ich versuchen, diese identischen Huskys auseinanderzuhalten. Ein Albtraum!'::text,'werde'::text,'werde'::text,'versuche'::text,'Morgen um diese Zeit werde ich versuchen, diese identischen Huskys auseinanderzuhalten. Ein Albtraum!'::text),
(361717,40191,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час я ... розрізнити цих ідентичних хаскі. Жах!'::text,'намагатимусь'::text,'спробую'::text,'намагаюся'::text,'Завтра в цей час я намагатимусь розрізнити цих ідентичних хаскі. Жах!'::text),
(361716,40191,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ... distinguir a estos huskies idénticos. ¡Una pesadilla!'::text,'estaré intentando'::text,'intentaré'::text,'intento'::text,'Mañana a esta hora estaré intentando distinguir a estos huskies idénticos. ¡Una pesadilla!'::text),
(361715,40191,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, je ... de distinguer ces huskies identiques. Un cauchemar !'::text,'serai en train d''essayer'::text,'essaierai'::text,'essaie'::text,'Demain à la même heure, je serai en train d''essayer de distinguer ces huskies identiques. Un cauchemar !'::text),
(361718,40191,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde bu tıpatıp aynı huskyleri ayırt etmeye ...; tam bir kâbus!'::text,'çalışıyor olacağım'::text,'çalışacağım'::text,'çalışıyorum'::text,'Yarın bu saatlerde bu tıpatıp aynı huskyleri ayırt etmeye çalışıyor olacağım; tam bir kâbus!'::text),
(361719,40191,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor ... megkülönböztetni ezeket az egyforma huskykat. Rémálom!'::text,'próbálom majd'::text,'megpróbálom'::text,'próbálom'::text,'Holnap ilyenkor próbálom majd megkülönböztetni ezeket az egyforma huskykat. Rémálom!'::text),
(361722,40192,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich hab eine Idee: Ich ... den identischen Huskys verschiedene Halsbänder.'::text,'kaufe'::text,'kaufe'::text,'kaufe'::text,'Ich hab eine Idee: Ich kaufe den identischen Huskys verschiedene Halsbänder.'::text),
(361726,40192,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У мене є ідея: я ... ідентичним хаскі різні нашийники.'::text,'куплю'::text,'купуватиму'::text,'купую'::text,'У мене є ідея: я куплю ідентичним хаскі різні нашийники.'::text),
(361725,40192,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tengo una idea: les ... collares distintos a los huskies idénticos.'::text,'compraré'::text,'estaré comprando'::text,'compro'::text,'Tengo una idea: les compraré collares distintos a los huskies idénticos.'::text),
(361724,40192,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'J''ai une idée : j''... des colliers différents aux huskies identiques.'::text,'achèterai'::text,'serai en train d''acheter'::text,'achète'::text,'J''ai une idée : j''achèterai des colliers différents aux huskies identiques.'::text),
(361727,40192,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir fikrim var: tıpatıp aynı huskylere farklı tasmalar ...'::text,'alacağım'::text,'alıyor olacağım'::text,'alıyorum'::text,'Bir fikrim var: tıpatıp aynı huskylere farklı tasmalar alacağım.'::text),
(361728,40192,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Van egy ötletem: ... az egyforma huskyknak különböző nyakörvet.'::text,'veszek'::text,'fogok venni'::text,'veszek'::text,'Van egy ötletem: veszek az egyforma huskyknak különböző nyakörvet.'::text),
(361731,40193,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn zwei Huskys identische Zeichnungen ..., verwechseln die Leute sie oft.'::text,'haben'::text,'hatten'::text,'haben werden'::text,'Wenn zwei Huskys identische Zeichnungen haben, verwechseln die Leute sie oft.'::text),
(361735,40193,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо два хаскі ... ідентичний окрас, люди часто їх плутають.'::text,'мають'::text,'мали'::text,'матимуть'::text,'Якщо два хаскі мають ідентичний окрас, люди часто їх плутають.'::text),
(361734,40193,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si dos huskies ... marcas idénticas, la gente suele confundirlos.'::text,'tienen'::text,'tenían'::text,'tendrán'::text,'Si dos huskies tienen marcas idénticas, la gente suele confundirlos.'::text),
(361733,40193,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si deux huskies ... des marques identiques, les gens les confondent souvent.'::text,'ont'::text,'avaient'::text,'auront'::text,'Si deux huskies ont des marques identiques, les gens les confondent souvent.'::text),
(361736,40193,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki husky tıpatıp aynı desenlere ..., insanlar onları sık sık karıştırır.'::text,'sahipse'::text,'sahip olduysa'::text,'sahip olacaksa'::text,'İki husky tıpatıp aynı desenlere sahipse, insanlar onları sık sık karıştırır.'::text),
(361737,40193,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha két huskynak egyforma mintázata ..., az emberek gyakran összekeverik őket.'::text,'van'::text,'volt'::text,'lesz'::text,'Ha két huskynak egyforma mintázata van, az emberek gyakran összekeverik őket.'::text),
(361740,40194,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die identischen Huskys Nase an Nase stehen, ... der Besitzer sie nicht auseinanderhalten.'::text,'wird'::text,'würde'::text,'konnte'::text,'Wenn die identischen Huskys Nase an Nase stehen, wird der Besitzer sie nicht auseinanderhalten.'::text),
(361744,40194,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ідентичні хаскі стоять ніс до носа, власник їх ...'::text,'не розрізнить'::text,'не розрізнив би'::text,'не розрізнив'::text,'Якщо ідентичні хаскі стоять ніс до носа, власник їх не розрізнить.'::text),
(361743,40194,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los huskies idénticos se ponen nariz con nariz, el dueño ...'::text,'no los distinguirá'::text,'no los distinguiría'::text,'no los distinguió'::text,'Si los huskies idénticos se ponen nariz con nariz, el dueño no los distinguirá.'::text),
(361742,40194,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les huskies identiques se mettent truffe contre truffe, le propriétaire ...'::text,'ne les distinguera pas'::text,'ne les distinguerait pas'::text,'ne les a pas distingués'::text,'Si les huskies identiques se mettent truffe contre truffe, le propriétaire ne les distinguera pas.'::text),
(361745,40194,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tıpatıp aynı huskyler burun buruna durursa sahibi onları ...'::text,'ayırt edemeyecek'::text,'ayırt edemezdi'::text,'ayırt edemedi'::text,'Tıpatıp aynı huskyler burun buruna durursa sahibi onları ayırt edemeyecek.'::text),
(361746,40194,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az egyforma huskyk orr orr mellett állnak, a gazdi ... őket.'::text,'nem fogja megkülönböztetni'::text,'nem különböztetné meg'::text,'nem különböztette meg'::text,'Ha az egyforma huskyk orr orr mellett állnak, a gazdi nem fogja megkülönböztetni őket.'::text),
(361749,40195,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn diese Huskys nicht identisch ..., wäre das Leben für den Besitzer etwas leichter.'::text,'wären'::text,'sind'::text,'gewesen wären'::text,'Wenn diese Huskys nicht identisch wären, wäre das Leben für den Besitzer etwas leichter.'::text),
(361753,40195,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ці хаскі не ... ідентичними, власникові жилося б трохи легше.'::text,'були'::text,'є'::text,'були'::text,'Якби ці хаскі не були ідентичними, власникові жилося б трохи легше.'::text),
(361752,40195,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si estos huskies no ... idénticos, la vida sería un poco más fácil para el dueño.'::text,'fueran'::text,'son'::text,'hubieran sido'::text,'Si estos huskies no fueran idénticos, la vida sería un poco más fácil para el dueño.'::text),
(361751,40195,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ces huskies ... identiques, la vie serait un peu plus facile pour le propriétaire.'::text,'n''étaient pas'::text,'ne sont pas'::text,'n''avaient pas été'::text,'Si ces huskies n''étaient pas identiques, la vie serait un peu plus facile pour le propriétaire.'::text),
(361754,40195,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu huskyler tıpatıp aynı ..., sahibinin hayatı biraz daha kolay olurdu.'::text,'olmasaydı'::text,'değil'::text,'olmamış olsaydı'::text,'Bu huskyler tıpatıp aynı olmasaydı, sahibinin hayatı biraz daha kolay olurdu.'::text),
(361755,40195,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ezek a huskyk nem ... egyformák, a gazdi élete kicsit könnyebb lenne.'::text,'lennének'::text,NULL::text,'lettek volna'::text,'Ha ezek a huskyk nem lennének egyformák, a gazdi élete kicsit könnyebb lenne.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
commit;
